```java
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null
      ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";
  static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
  static final String ERR_RE = "\"error\"\\s*:\\s*\"([^\"]+)\"";

  static String jv(Object o) {
    if (o instanceof Number || o instanceof Boolean) return o.toString();
    return "\"" + String.valueOf(o).replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }

  static String user(Session s) {
    return "bench-" + (Math.floorMod(s.userId() - 1, 16L) + 1);
  }

  static String err(Session s) {
    return s.contains("err") ? s.getString("err") : null;
  }

  static boolean is401(Session s) {
    return s.contains("st") && s.getInt("st") == 401;
  }

  static boolean hasNext(Session s) {
    if (!s.contains("next")) return false;
    Object o = s.get("next");
    if (o == null) return false;
    String t = o.toString().trim();
    return !t.isEmpty() && !t.equals("null");
  }

  // Common checks: allowed statuses, status/err capture, denied is always a failure.
  static HttpRequestActionBuilder std(HttpRequestActionBuilder b, boolean lenient,
                                      boolean saveCsrf, int[] ok, int... extra) {
    int[] codes = ok;
    if (lenient) {
      codes = Arrays.copyOf(ok, ok.length + 1 + extra.length);
      codes[ok.length] = 401;
      for (int i = 0; i < extra.length; i++) codes[ok.length + 1 + i] = extra[i];
    }
    HttpRequestActionBuilder r = b.check(
        status().in(codes),
        status().saveAs("st"),
        regex(ERR_RE).optional().saveAs("err"),
        regex("\"error\"\\s*:\\s*\"denied\"").notExists());
    if (saveCsrf) r = r.check(regex(CSRF_RE).optional().saveAs("csrf"));
    return r;
  }

  static ChainBuilder loginChain() {
    return exec(s -> s.removeAll("formHidden", "formAny", "formCsrf", "loc", "csrf"))
        .exec(http("GET login-form").get("/v2/login-form").check(
            status().is(200),
            css("input[type=hidden][name=csrf]", "value").optional().saveAs("formHidden"),
            css("input[name=csrf]", "value").optional().saveAs("formAny")))
        .exec(s -> {
          String t = null;
          if (s.contains("formHidden")) t = s.getString("formHidden");
          if ((t == null || t.isEmpty()) && s.contains("formAny")) t = s.getString("formAny");
          if (t == null || t.isEmpty()) return s.markAsFailed();
          return s.set("formCsrf", t);
        })
        .exec(http("POST login").post("/v2/login").asJson()
            .body(StringBody(s -> "{\"username\":\"" + user(s) + "\",\"password\":\"bench\",\"csrf\":"
                + jv(s.getString("formCsrf")) + "}"))
            .check(status().in(200, 302),
                header("Location").optional().saveAs("loc"),
                regex(CSRF_RE).optional().saveAs("csrf")))
        .doIf(s -> s.contains("loc")).then(
            exec(http("GET login redirect").get("#{loc}").check(
                status().is(200),
                regex(CSRF_RE).optional().saveAs("csrf"))))
        .exec(s -> s.contains("csrf") ? s : s.markAsFailed());
  }

  static ChainBuilder recoverCart() {
    return doIf(s -> s.contains("cartId")).then(
        exec(http("POST cart recover").post("/v2/carts/#{cartId}/recover").asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 201, 202, 204),
                regex(CSRF_RE).optional().saveAs("csrf"),
                header("ETag").optional().saveAs("etag"))));
  }

  static ChainBuilder recovery() {
    return doIf(s -> "expired".equals(err(s))).then(
        exec(http("POST session renew").post("/v2/session/renew").asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), regex(CSRF_RE).optional().saveAs("csrf"))),
        recoverCart())
        .doIf(s -> "session".equals(err(s))).then(
            loginChain(),
            recoverCart());
  }

  static ChainBuilder rereadCart() {
    return exec(http("GET cart reread").get("/v2/carts/#{cartId}").check(
        status().is(200),
        header("ETag").saveAs("etag")));
  }

  // One attempt, bounded recovery on 401 expired/session, one re-read+retry on 412.
  static ChainBuilder guarded(Function<Boolean, HttpRequestActionBuilder> mk, boolean etagOp) {
    return exec(s -> s.removeAll("st", "err", "rec"))
        .exec(mk.apply(true))
        .doIf(s -> is401(s) && ("expired".equals(err(s)) || "session".equals(err(s)))).then(
            exec(s -> s.set("rec", true)),
            recovery(),
            doIf(s -> etagOp && s.contains("cartId")).then(rereadCart()),
            exec(s -> s.remove("st")),
            exec(mk.apply(false)))
        .doIf(s -> etagOp && !s.contains("rec") && s.contains("st") && s.getInt("st") == 412).then(
            rereadCart(),
            exec(mk.apply(false)));
  }

  static void addCandidates(List<Object> out, Object o) {
    if (o instanceof Iterable) {
      for (Object x : (Iterable<?>) o) out.add(x);
    } else if (o != null) {
      out.add(o);
    }
  }

  static Session pick(Session s) {
    if (s.contains("pid")) return s;
    List<Object> cands = new ArrayList<>();
    if (s.contains("plist")) addCandidates(cands, s.get("plist"));
    if (s.contains("plist2")) addCandidates(cands, s.get("plist2"));
    for (Object c : cands) {
      if (!(c instanceof Map)) continue;
      Map<?, ?> m = (Map<?, ?>) c;
      Object variants = m.get("variants");
      if (!(variants instanceof Iterable)) continue;
      for (Object v : (Iterable<?>) variants) {
        if (!(v instanceof Map)) continue;
        Map<?, ?> vm = (Map<?, ?>) v;
        Object st = vm.get("in_stock");
        boolean inStock = st instanceof Boolean ? (Boolean) st : "true".equalsIgnoreCase(String.valueOf(st));
        if (inStock && m.get("id") != null && vm.get("id") != null) {
          return s.set("pid", m.get("id")).set("vid", vm.get("id"));
        }
      }
    }
    return s;
  }

  static HttpRequestActionBuilder catalogReq(String name, String url, boolean lenient) {
    return std(http(name).get(url).check(
        jsonPath("$..products[*]").ofMap().findAll().optional().saveAs("plist"),
        jsonPath("$..product").ofMap().findAll().optional().saveAs("plist2"),
        jsonPath("$.next").ofString().optional().saveAs("next")),
        lenient, false, new int[]{200});
  }

  static ChainBuilder catalogChain() {
    return exec(s -> s.removeAll("pid", "vid", "next", "plist", "plist2", "nurl"))
        .exec(guarded(l -> catalogReq("GET catalog", "/v2/catalog", l), false))
        .exec(s -> pick(s))
        .repeat(3).on(
            doIf(s -> !s.contains("pid") && hasNext(s)).then(
                exec(s -> s.set("nurl", s.get("next").toString()).removeAll("next", "plist", "plist2")),
                guarded(l -> catalogReq("GET catalog page", "#{nurl}", l), false),
                exec(s -> pick(s))))
        .exec(s -> s.contains("pid") ? s : s.markAsFailed());
  }

  static ChainBuilder createCart() {
    return guarded(l -> {
      HttpRequestActionBuilder b = http("POST cart").post("/v2/carts").asJson()
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody(s -> "{\"product_id\":" + jv(s.get("pid"))
              + ",\"variant_id\":" + jv(s.get("vid")) + "}"))
          .check(header("ETag").optional().saveAs("etag"));
      if (l) b = b.check(jsonPath("$.id").ofObject().optional().saveAs("cartId"));
      else b = b.check(jsonPath("$.id").ofObject().saveAs("cartId"));
      return std(b, l, true, new int[]{201});
    }, false)
        .exec(s -> s.contains("cartId") ? s : s.markAsFailed());
  }

  static ChainBuilder getCart(String name) {
    return guarded(l -> {
      HttpRequestActionBuilder b = http(name).get("/v2/carts/#{cartId}");
      if (l) b = b.check(header("ETag").optional().saveAs("etag"));
      else b = b.check(header("ETag").saveAs("etag"));
      return std(b, l, false, new int[]{200});
    }, false);
  }

  static ChainBuilder patchCart() {
    return guarded(l -> std(
        http("PATCH cart").patch("/v2/carts/#{cartId}").asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .body(StringBody("{\"quantity\":2}"))
            .check(header("ETag").optional().saveAs("etag")),
        l, true, new int[]{200, 204}, 412), true);
  }

  static ChainBuilder placeOrder() {
    return guarded(l -> {
      HttpRequestActionBuilder b = http("POST order").post("/v2/orders").asJson()
          .header("X-CSRF-Token", "#{csrf}")
          .header("Idempotency-Key", "idem-#{cartId}")
          .header("If-Match", "#{etag}")
          .body(StringBody(s -> "{\"cart_id\":" + jv(s.get("cartId")) + "}"))
          .check(regex("\"accepted\"\\s*:\\s*false").notExists());
      if (!l) b = b.check(jsonPath("$.accepted").ofBoolean().is(true));
      return std(b, l, true, new int[]{201}, 412);
    }, true);
  }

  static ChainBuilder journey() {
    return exec(flushCookieJar())
        .exec(s -> s.removeAll("pid", "vid", "cartId", "etag", "csrf", "rec", "next",
            "plist", "plist2", "nurl", "st", "err", "loc", "formHidden", "formAny", "formCsrf"))
        .exec(loginChain())
        .exec(catalogChain())
        .exec(createCart())
        .exec(getCart("GET cart"))
        .exec(patchCart())
        .exec(getCart("GET cart before order"))
        .exec(placeOrder());
  }

  HttpProtocolBuilder protocol = http.baseUrl(BASE)
      .disableFollowRedirect()
