import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { parseHTML } from 'k6/html';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
  thresholds: {
    checks: ['rate>0.99'],
  },
};

http.setResponseCallback(http.expectedStatuses(200, 201, 202, 302, 401, 412, 429));

// ---------- helpers ----------
function hdr(res, name) {
  const want = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === want) return res.headers[k];
  }
  return null;
}

function jsonOf(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function errOf(res) {
  const b = jsonOf(res);
  if (b && b.error !== undefined && b.error !== null) {
    return typeof b.error === 'string' ? b.error : JSON.stringify(b.error);
  }
  return '';
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  return BASE + '/' + loc;
}

function pathOf(url) {
  return url.indexOf(BASE) === 0 ? url.substring(BASE.length) : url;
}

