function pickInput(body, inputName, formHint) {
  let best = null;
  let bestScore = -1;
  try {
    const doc = parseHTML(body);
    const sel = doc.find('input[name="' + inputName + '"]');
    const n = sel.size();
    for (let i = 0; i < n; i++) {
      const el = sel.eq(i);
      const value = el.attr('value');
      if (value === undefined || value === null || value === '') continue;
      if (el.attr('disabled') !== undefined) continue;
      let score = 1;
      const type = (el.attr('type') || '').toLowerCase();
      if (type === 'hidden') score += 2;
      try {
        const action = el.closest('form').attr('action');
        if (action !== undefined && action !== null && formHint && action.indexOf(formHint) !== -1) score += 4;
      } catch (e) {}
      if (score > bestScore) {
        bestScore = score;
        best = value;
      }
    }
