      if (!new RegExp('name\\s*=\\s*["\']?' + inputName + '["\']?(\\s|/|>|$)', 'i').test(t)) continue;
      if (/\bdisabled\b/i.test(t)) continue;
      const m = t.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      if (m) {
        best = m[1] !== undefined ? m[1] : m[2] !== undefined ? m[2] : m[3];
        break;
      }
    }
  }
  return best;
}

function newState() {
  const vuIdx = ((__VU - 1) % 16) + 1;
  return {
    jar: new http.CookieJar(),
    username: 'bench-' + vuIdx,
    csrf: null,
    cartId: null,
    etag: null,
  };
}

// ---------- login ----------
function login(st) {
  const form = http.get(BASE + '/v2/login-form', {
    jar: st.jar,
    redirects: 0,
    tags: { name: 'GET /v2/login-form' },
  });
  check(form, { 'login form 200': (r) => r.status === 200 });
  const token = pickInput(form.body || '', 'csrf', '/login');
  check(token, { 'csrf token extracted': (t) => !!t });
  if (!token) fail('csrf token not found in login form');

  let res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: st.username, password: 'bench', csrf: token }),
    {
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      jar: st.jar,
      redirects: 0,
      tags: { name: 'POST /v2/login' },
    }
  );
  if (res.status === 302) {
    const loc = resolveUrl(hdr(res, 'Location'));
    if (loc) {
      res = http.get(loc, {
        headers: { Accept: 'application/json' },
        jar: st.jar,
        redirects: 0,
        tags: { name: 'GET login-location' },
      });
    }
  }
  const ok = check(res, { 'login ok': (r) => r.status === 200 || r.status === 201 });
  if (!ok) fail('login failed status=' + res.status);
  const body = jsonOf(res);
  if (body && body.csrf) st.csrf = body.csrf;
  check(st.csrf, { 'login returned csrf': (c) => !!c });
  if (!st.csrf) fail('no csrf after login');
}

// ---------- authenticated call with bounded recovery ----------
function rawRenew(st) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': st.csrf,
    },
    jar: st.jar,
    redirects: 0,
    tags: { name: 'POST /v2/session/renew' },
  });
  if (res.status === 200 || res.status === 201) {
    const b = jsonOf(res);
    if (b && b.csrf) {
      st.csrf = b.csrf;
      return true;
    }
  }
  return false;
}

function refreshEtag(st) {
  if (!st.cartId) return;
  const r = http.get(BASE + '/v2/carts/' + st.cartId, {
    headers: { Accept: 'application/json' },
    jar: st.jar,
    redirects: 0,
    tags: { name: 'GET /v2/carts/{id}' },
  });
  const e = hdr(r, 'ETag');
  if (e) st.etag = e;
}

function recoverCart(st) {
  if (!st.cartId) return;
  const r = http.post(BASE + '/v2/carts/' + st.cartId + '/recover', '{}', {
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': st.csrf,
    },
    jar: st.jar,
    redirects: 0,
    tags: { name: 'POST /v2/carts/{id}/recover' },
  });
  const b = jsonOf(r);
  if (b && b.csrf) st.csrf = b.csrf;
  const e = hdr(r, 'ETag');
  if (e) st.etag = e;
}

function call(st, method, path, body, extraHeaders, name) {
  let recovered = false;
  let retries429 = 0;
  const extra = Object.assign({}, extraHeaders || {});
  for (;;) {
    const headers = Object.assign(
      { 'Content-Type': 'application/json', Accept: 'application/json' },
      extra
    );
    if (method !== 'GET') headers['X-CSRF-Token'] = st.csrf;
    const res = http.request(
      method,
      path.indexOf('http') === 0 ? path : BASE + path,
      body === null || body === undefined ? null : JSON.stringify(body),
      { headers: headers, jar: st.jar, redirects: 0, tags: { name: name || method + ' ' + path } }
    );

    if (res.status === 429 && retries429 < 4) {
      retries429++;
      const ra = parseFloat(hdr(res, 'Retry-After'));
      sleep(isNaN(ra) ? 1 : ra);
      continue;
    }

    if (res.status === 401 && !recovered) {
      const e = errOf(res);
      if (e.indexOf('expired') !== -1) {
        recovered = true;
        if (!rawRenew(st)) {
          login(st);
        }
        recoverCart(st);
        if (extra['If-Match']) {
          refreshEtag(st);
          if (st.etag) extra['If-Match'] = st.etag;
        }
        continue;
      }
      if (e.indexOf('session') !== -1) {
        recovered = true;
        // revoked: try renew once, else fresh form + login
        if (!rawRenew(st)) {
          login(st);
        }
        recoverCart(st);
        if (extra['If-Match']) {
          refreshEtag(st);
          if (st.etag) extra['If-Match'] = st.etag;
        }
        continue;
      }
      // denied or anything else: not expiry
      return res;
    }

    if (res.status >= 200 && res.status < 300) {
      const b = jsonOf(res);
      if (b && b.csrf) st.csrf = b.csrf;
    }
    return res;
  }
}

// ---------- catalog ----------
function productsOf(body) {
  if (!body) return [];
  const d = body.data !== undefined ? body.data : body;
  if (!d) return [];
  if (Array.isArray(d.products)) return d.products;
  if (d.product) return [d.product];
  if (Array.isArray(d)) return d;
  if (d.id && d.variants) return [d];
  return [];
}

function firstInStock(products) {
  for (const p of products) {
    const vs = p.variants || [];
    for (const v of vs) {
      if (v.in_stock === true) return { product_id: p.id, variant_id: v.id };
    }
  }
  return null;
}

function chooseProduct(st) {
  const res = call(st, 'GET', '/v2/catalog', null, null, 'GET /v2/catalog');
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const body = jsonOf(res);
  let pick = firstInStock(productsOf(body));
  if (pick) return pick;

  let next = body && body.next ? body.next : '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3 && !pick) {
    pages++;
    const url = resolveUrl(next);
    const r = call(st, 'GET', url, null, null, 'GET /v2/catalog/page');
    check(r, { 'catalog page 200': (x) => x.status === 200 });
    const b = jsonOf(r);
    pick = firstInStock(productsOf(b));
    next = b && b.next ? b.next : null;
  }
  return pick;
}

// ---------- challenge ----------
function getGrant(st) {
  const f = call(st, 'GET', '/v2/challenge-form', null, null, 'GET /v2/challenge-form');
  if (f.status !== 200) return null;
  const html = f.body || '';
  let action = null;
  try {
    const doc = parseHTML(html);
    const forms = doc.find('form');
    for (let i = 0; i < forms.size(); i++) {
      const a = forms.eq(i).attr('action');
      if (a && /\/v2\/challenges\/[^\/?#]+/.test(a)) {
        action = a;
        break;
      }
    }
  } catch (e) {}
  if (!action) {
    const m = html.match(/action\s*=\s*["']?(\/v2\/challenges\/[^"'\s>]+)/i);
    if (m) action = m[1];
  }
  const challenge = pickInput(html, 'challenge', '/v2/challenges/');
  if (!action || !challenge) return null;
  const p = call(st, 'POST', pathOf(resolveUrl(action)), { challenge: challenge }, null, 'POST /v2/challenges/{id}');
  let loc = null;
  if (p.status === 302) loc = resolveUrl(hdr(p, 'Location'));
  if (!loc) return null;
  const g = call(st, 'GET', loc, null, null, 'GET challenge-location');
  const gb = jsonOf(g);
  if (!gb || !gb.grant_id) return null;
  if (gb.csrf) st.csrf = gb.csrf;
  return gb.grant_id;
}

// ---------- reservation ----------
function reserve(st) {
  const r = call(st, 'POST', '/v2/reservations', { cart_id: st.cartId }, null, 'POST /v2/reservations');
  if (r.status !== 202 && r.status !== 200 && r.status !== 201) return null;
  const b = jsonOf(r);
  if (!b || !b.status_url) return null;
  const url = resolveUrl(b.status_url);
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const s = call(st, 'GET', url, null, null, 'GET reservation status');
    const sb = jsonOf(s);
    if (sb && sb.status === 'ready') {
      return sb.reservation_id || sb.id || null;
    }
    if (sb && sb.status === 'failed') return null;
  }
  return null;
}

// ---------- journey ----------
export default function () {
  const st = newState();

  // 1. login with token extracted from HTML form
  login(st);

  // 2. catalog
  const pick = chooseProduct(st);
  check(pick, { 'in-stock variant found': (p) => !!p });
  if (!pick) fail('no in-stock variant found');

  // 3. create the single cart
  let payload = { product_id: pick.product_id, variant_id: pick.variant_id };
  let cres = call(st, 'POST', '/v2/carts', payload, null, 'POST /v2/carts');
  if (cres.status !== 201 && /challenge|grant/i.test(errOf(cres) + ' ' + (cres.body || '').substring(0, 200))) {
    const grant = getGrant(st);
    if (grant) {
      payload = { product_id: pick.product_id, variant_id: pick.variant_id, grant_id: grant };
      cres = call(st, 'POST', '/v2/carts', payload, null, 'POST /v2/carts');
    }
  }
  check(cres, { 'cart created 201': (r) => r.status === 201 });
  const cbody = jsonOf(cres);
  if (cres.status !== 201 || !cbody || !cbody.id) fail('cart creation failed status=' + cres.status);
  st.cartId = cbody.id;
  st.etag = hdr(cres, 'ETag');
  if (!st.etag) refreshEtag(st);

  // 4. patch quantity with If-Match; on 412 re-read and retry once
  const patchBody = { quantity: 2 };
  let pres = call(st, 'PATCH', '/v2/carts/' + st.cartId, patchBody, { 'If-Match': st.etag }, 'PATCH /v2/carts/{id}');
  if (pres.status === 412) {
    refreshEtag(st);
    pres = call(st, 'PATCH', '/v2/carts/' + st.cartId, patchBody, { 'If-Match': st.etag }, 'PATCH /v2/carts/{id}');
  }
  check(pres, { 'cart patched 200': (r) => r.status === 200 });
  if (pres.status !== 200) fail('patch failed status=' + pres.status);
  const pe = hdr(pres, 'ETag');
  if (pe) st.etag = pe;
  else refreshEtag(st);

  // 5. order with stable idempotency key
  const idemKey = 'idem-' + st.cartId;
  let reservationId = null;
  let reread = false;
  let reserved = false;
  let ores = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    const ob = { cart_id: st.cartId };
    if (reservationId) ob.reservation_id = reservationId;
    const h = { 'Idempotency-Key': idemKey };
    if (st.etag) h['If-Match'] = st.etag;
    ores = call(st, 'POST', '/v2/orders', ob, h, 'POST /v2/orders');
    if (ores.status === 201) break;
    if (ores.status === 412 && !reread) {
      reread = true;
      refreshEtag(st);
      continue;
    }
    if (!reserved && /reservation/i.test(errOf(ores) + ' ' + (ores.body || '').substring(0, 200))) {
      reserved = true;
      reservationId = reserve(st);
      if (!reservationId) break; // never reach checkout without ready reservation
      continue;
    }
    break;
  }
  const obody = jsonOf(ores);
  check(ores, {
    'order committed 201': (r) => r.status === 201,
    'order accepted': () => !!obody && obody.accepted === true,
  });
}
