class JourneyAbort(Exception):
    pass


# ---------------------------------------------------------------- helpers
class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []
        self.cur = None

    def handle_starttag(self, tag, attrs):
        a = {(k or "").lower(): (v if v is not None else "") for k, v in attrs}
        if tag == "form":
            self.cur = {"action": a.get("action", "")}
            self.forms.append(self.cur)
        elif tag == "input":
            self.inputs.append({"a": a, "form": self.cur})

    def handle_endtag(self, tag):
        if tag == "form":
            self.cur = None


def parse_html(text):
    p = FormParser()
    try:
        p.feed(text or "")
        p.close()
    except Exception:
        pass
    return p


def pick_csrf(text):
    p = parse_html(text)
    best, best_score = None, None
    for inp in p.inputs:
        a = inp["a"]
        if a.get("name", "").strip() != "csrf" or "value" not in a:
            continue
        if "disabled" in a:
            continue
        score = 0
        if a.get("type", "").strip().lower() == "hidden":
            score += 4
        form = inp["form"]
        if form and "login" in form["action"].lower():
            score += 2
        if a.get("value"):
            score += 1
        if any("decoy" in str(v).lower() for k, v in a.items() if k != "value"):
            score -= 3
        if best_score is None or score > best_score:
            best, best_score = a["value"], score
    return best


def pick_challenge(text):
    p = parse_html(text)
    pat = re.compile(r"/v2/challenges/[^/?#\s]+")
    for inp in p.inputs:
        a = inp["a"]
        if a.get("name", "").strip() != "challenge" or "disabled" in a:
            continue
        form = inp["form"]
        if form and pat.search(form["action"]):
            return form["action"], a.get("value", "")
    for inp in p.inputs:
        if inp["a"].get("name", "").strip() == "challenge":
            for f in p.forms:
                if pat.search(f["action"]):
                    return f["action"], inp["a"].get("value", "")
    return None, None


def js(r):
    try:
        d = r.json()
        return d if isinstance(d, dict) else {}
    except Exception:
