            r = self.req("GET", norm_path(url), "/v2/reservations/[status]", ok=(200,))
            d = js(r)
            st = d.get("status")
            if st == "ready":
                rid = d.get("reservation_id") or d.get("id")
                if rid:
                    return rid
                break
            if st == "failed" or r.status_code != 200:
                break
        raise JourneyAbort("reservation not ready")

    # ---- order
    def place_order(self):
        key = "%s-%s" % (self.cart_id, uuid.uuid4().hex[:12])
        body = {"cart_id": self.cart_id}
        state = {"retried412": False, "reserved": False}

        def soft(r):
            if r.status_code == 412 and not state["retried412"]:
                return True
            return (not state["reserved"]) and needs(r, ("reservation",))

        def chk(r):
            if r.status_code == 201 and js(r).get("accepted") is True:
                return None
            return "order not accepted (%s)" % r.status_code

        for _ in range(3):
            h = {"Idempotency-Key": key}
            if self.etag:
                h["If-Match"] = self.etag
            r = self.req("POST", "/v2/orders", "/v2/orders", ok=(200, 201), body=body,
                         headers=h, soft=soft, check=chk)
            if r.status_code == 201 and js(r).get("accepted") is True:
                return True
            if r.status_code == 412 and not state["retried412"]:
                state["retried412"] = True
                self.refresh_cart()
                continue
            if not state["reserved"] and needs(r, ("reservation",)):
                body["reservation_id"] = self.reserve()
                state["reserved"] = True
                continue
            return False
        return False

    # ---- journey
    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.login()
        pid, vid = self.pick_product()
        self.create_cart(pid, vid)
        self.patch_quantity(2)
        self.place_order()

    @task
    def flow(self):
        try:
            self.journey()
        except JourneyAbort:
            pass
        except StopUser:
            raise
        except Exception:
            pass
        self.done += 1
        if self.done >= ITERATIONS:
            ShopUser.finished += 1
            raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        if ShopUser.finished >= USERS or self.get_run_time() > 240:
            return None
        return (USERS, USERS)
