    List<CheckBuilder> cs = new ArrayList<>();
    cs.add(status().in(allowed));
    cs.add(status().saveAs("lastStatus"));
    cs.add(
        checkIf((r, s) -> r.status().code() == 401 && r.body().string().contains("\"error\""))
            .then(jmesPath("error").saveAs("err")));
    if (!retry) {
      // 401 that is neither expired nor revoked (e.g. denied) must fail
      final int expected = ok.get(0);
      cs.add(
          checkIf(
                  (r, s) ->
                      r.status().code() == 401
                          && !r.body().string().contains("expired")
                          && !r.body().string().contains("\"session\""))
              .then(status().is(expected)));
    }
    cs.add(csrfCheck());
    cs.add(header("ETag").optional().saveAs("etag"));
    if (extra.length > 0) {
      cs.add(checkIf((r, s) -> r.status().code() / 100 == 2).then(extra));
    }
    return b.check(cs.toArray(new CheckBuilder[0]));
  }

  private ChainBuilder loginChain() {
    return exec(s -> s.remove("loc").remove("csrf").remove("formCsrf"))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(status().is(200), css("input[name=csrf]", "value").find(0).saveAs("formCsrf")))
        .exec(
            http("login")
