  public ModelSimulation() {
    HttpProtocolBuilder proto =
        http.baseUrl(BASE)
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

    ChainBuilder journey =
        exec(flushCookieJar())
            .exec(
