                        .remove("err")
                        .remove("cartId")
                        .remove("etag")
                        .remove("lastStatus"))
            .exec(loginChain())
            // catalog: pick an in-stock variant belonging to the same parent product
            .exec(
                http("catalog")
                    .get("/v2/catalog")
                    .check(
                        status().is(200),
                        jmesPath("data.products[?variants[?in_stock]] | [0].id").saveAs("productId"),
                        jmesPath("data.products[?variants[?in_stock]] | [0].variants[?in_stock] | [0].id")
                            .saveAs("variantId")))
            // cart
            .exec(guarded(this::createCart, false))
            // quantity update, with one re-read/retry on 412
            .exec(guarded(r -> patchCart(r, true), true))
            .doIf(s -> s.contains("lastStatus") && s.getInt("lastStatus") == 412)
            .then(
                exec(
                    http("re-read cart")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200), header("ETag").optional().saveAs("etag"))),
                exec(patchCart(true, false)))
            // refresh ETag
            .exec(guarded(this::getCart, true))
            // order
            .exec(
