                                .check(
                                    status().in(List.of(200, 401)),
                                    status().saveAs("rst"),
                                    regex(CSRF_RE).optional().saveAs("csrf"))),
                        doIf(s -> s.contains("rst") && s.getInt("rst") == 401)
                            .then(loginChain())));
    if (hasCart) {
      c =
          c.exec(
              auth(http("recover cart").post("/v2/carts/#{cartId}/recover"))
                  .header("Content-Type", CT)
                  .body(StringBody("{}"))
                  .check(
                      status().in(List.of(200, 201, 202, 204)),
                      regex(CSRF_RE).optional().saveAs("csrf"),
                      header("ETag").optional().saveAs("etag")));
    }
    return c;
  }

  private ChainBuilder guarded(Function<Boolean, HttpRequestActionBuilder> req, boolean hasCart) {
    return exec(s -> s.remove("err"))
        .exec(req.apply(false))
        .doIf(s -> errIs(s, "expired") || errIs(s, "session"))
        .then(exec(recovery(hasCart)), exec(s -> s.remove("err")), exec(req.apply(true)));
  }

  private HttpRequestActionBuilder createCart(boolean retry) {
    List<CheckBuilder> cs = base(retry, List.of(201));
    if (retry) {
      cs.add(jmesPath("id").saveAs("cartId"));
    } else {
      cs.add(jmesPath("id").optional().saveAs("cartId"));
    }
    return withChecks(
        auth(http(retry ? "create cart retry" : "create cart").post("/v2/carts"))
            .header("Content-Type", CT)
            .body(
                StringBody(
                    s ->
                        "{\"product_id\":"
                            + jv(s.get("productId"))
                            + ",\"variant_id\":"
                            + jv(s.get("variantId"))
                            + "}")),
        cs);
  }

  private HttpRequestActionBuilder getCart(boolean retry) {
    return withChecks(
        http(retry ? "get cart retry" : "get cart").get("/v2/carts/#{cartId}"),
        base(retry, List.of(200)));
  }

  private HttpRequestActionBuilder patchCart(boolean retry, boolean allow412) {
    return withChecks(
        auth(http(retry ? "patch cart retry" : "patch cart").patch("/v2/carts/#{cartId}"))
            .header("Content-Type", CT)
            .header("If-Match", "#{etag}")
            .body(StringBody("{\"quantity\":1}")),
        base(retry, allow412 ? List.of(200, 204, 412) : List.of(200, 204)));
  }

  private HttpRequestActionBuilder placeOrder(boolean retry) {
    List<CheckBuilder> cs = base(retry, List.of(201));
    cs.add(regex("\"accepted\"\\s*:\\s*false").notExists());
    if (retry) {
      cs.add(regex("\"accepted\"\\s*:\\s*true").exists().saveAs("accepted"));
      cs.add(jmesPath("id").saveAs("orderId"));
    } else {
      cs.add(regex("\"accepted\"\\s*:\\s*true").optional().saveAs("accepted"));
      cs.add(jmesPath("id").optional().saveAs("orderId"));
    }
    return withChecks(
        auth(http(retry ? "create order retry" : "create order").post("/v2/orders"))
            .header("Content-Type", CT)
            .header("Idempotency-Key", "#{idemKey}")
            .header("If-Match", "#{etag}")
            .body(StringBody(s -> "{\"cart_id\":" + jv(s.get("cartId")) + "}")),
        cs);
  }

  public ModelSimulation() {
    HttpProtocolBuilder proto =
        http.baseUrl(BASE)
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

    ChainBuilder journey =
        exec(flushCookieJar())
            .exec(
                s ->
                    s.set("user", "bench-" + ((s.userId() % 16) + 1))
                        .remove("err")
                        .remove("cartId")
                        .remove("etag")
                        .remove("lastStatus")
                        .remove("accepted")
                        .remove("orderId")
                        .remove("productId")
                        .remove("variantId"))
            .exec(loginChain())
            // pick the first product with an in-stock variant, and the variant from that same product
            .exec(
                http("catalog")
                    .get("/v2/catalog")
                    .check(
                        status().is(200),
                        jmesPath("data.products[?variants[?in_stock]] | [0].id")
                            .saveAs("productId"),
                        jmesPath(
                                "data.products[?variants[?in_stock]] | [0].variants[?in_stock] | [0].id")
                            .saveAs("variantId")))
            // cart
            .exec(guarded(this::createCart, false))
            .exec(s -> s.contains("cartId") ? s : s.markAsFailed())
            .exec(guarded(this::getCart, true))
            // quantity update; on 412 re-read and retry the same payload once
            .exec(guarded(r -> patchCart(r, true), true))
            .doIf(s -> s.contains("lastStatus") && s.getInt("lastStatus") == 412)
            .then(exec(getCart(true)), exec(patchCart(true, false)))
            // refresh ETag before ordering
            .exec(guarded(this::getCart, true))
            // order, with a key stable for this cart
            .exec(s -> s.set("idemKey", "idem-" + s.get("cartId") + "-u" + s.userId()))
            .exec(guarded(this::placeOrder, true))
            .exec(s -> s.contains("accepted") ? s : s.markAsFailed());

    ScenarioBuilder scn =
        scenario("checkout flow")
            .repeat(2)
            .on(exec(exitBlockOnFail().on(journey)).exec(s -> s.markAsSucceeded()));

    setUp(scn.injectOpen(atOnceUsers(2))).protocols(proto);
  }
}
