```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
};

// ---------- helpers ----------
function url(p) {
  if (/^https?:\/\//i.test(p)) {
    const m = p.match(/^https?:\/\/[^\/]+(\/.*)?$/);
    p = (m && m[1]) || '/';
  }
  return BASE + (p.charAt(0) === '/' ? '' : '/') + p;
}

function jsonOf(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  const want = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === want) return res.headers[k];
  }
  return null;
}

function raw(S, method, path, body, extraHeaders, name) {
  const h = Object.assign({ 'Content-Type': 'application/json' }, extraHeaders || {});
  if (method !== 'GET' && S.csrf) h['X-CSRF-Token'] = S.csrf;
  const payload = body === undefined || body === null ? null : JSON.stringify(body);
  return http.request(method, url(path), payload, {
    headers: h,
    redirects: 0,
    tags: { name: name || (method + ' ' + path) },
  });
}

function absorb(S, res) {
  if (res.status >= 200 && res.status < 400) {
    const j = jsonOf(res);
    if (j && typeof j === 'object' && j.csrf) S.csrf = j.csrf;
    const et = hdr(res, 'ETag');
    if (et && /\/v2\/carts\//.test(res.url || '')) S.etag = et;
  }
}

// ---------- login ----------
function parseCsrf(f) {
  let val = null;
  try {
    const els = f.html().find('input[name="csrf"]').toArray();
    for (let i = 0; i < els.length; i++) {
      const e = els[i];
      const v = e.attr('value');
      if (v && e.attr('disabled') === undefined) {
        val = v;
        break;
      }
    }
  } catch (e) {
    // fall through to regex
  }
  if (!val) {
    const re = /<input\b[^>]*\bname\s*=\s*["']?csrf["']?(?=[\s>\/])[^>]*>/gi;
    const tags = f.body.match(re) || [];
    for (let i = 0; i < tags.length; i++) {
      const m = tags[i].match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      if (m) {
        val = m[1] || m[2] || m[3];
        if (val) break;
      }
    }
  }
  return val;
}

function login(S) {
  const f = http.get(url('/v2/login-form'), { redirects: 0, tags: { name: 'login-form' } });
  const formCsrf = parseCsrf(f);
  const ok = check(f, { 'login form has csrf': () => !!formCsrf });
  if (!ok) return false;

  let r = http.post(
    url('/v2/login'),
    JSON.stringify({ username: S.user, password: 'bench', csrf: formCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0, tags: { name: 'login' } }
  );
  if (r.status >= 300 && r.status < 400) {
    const loc = hdr(r, 'Location');
    if (loc) {
      r = http.get(url(loc), { redirects: 0, tags: { name: 'login-redirect' } });
    }
  }
  const j = jsonOf(r);
  const good = check(r, {
    'login ok': (x) => x.status === 200 && !!j && !!j.csrf,
  });
  if (good) S.csrf = j.csrf;
  return good;
}

// ---------- recovery ----------
function recoverCart(S) {
  if (!S.cartId) return;
  const r = raw(S, 'POST', '/v2/carts/' + S.cartId + '/recover', {}, null, 'POST /v2/carts/{id}/recover');
  check(r, { 'cart recovered': (x) => x.status >= 200 && x.status < 300 });
  absorb(S, r);
  const et = hdr(r, 'ETag');
  if (et) S.etag = et;
}

function renewOrRelogin(S) {
  const r = raw(S, 'POST', '/v2/session/renew', {}, null, 'POST /v2/session/renew');
  const j = jsonOf(r);
  if (r.status === 200 && j && j.csrf) {
    S.csrf = j.csrf;
    return true;
  }
  return login(S);
}

// request wrapper: bounded 401 recovery and scheduled 429 handling
function send(S, method, path, body, extraHeaders, name) {
  let recovered = false;
  let throttled = 0;
  for (;;) {
    const res = raw(S, method, path, body, extraHeaders, name);
    if (res.status === 401) {
      const j = jsonOf(res);
      const err = j && j.error;
      if (!recovered && err === 'expired') {
        recovered = true;
        if (!renewOrRelogin(S)) return res;
        recoverCart(S);
        continue;
      }
      if (!recovered && err === 'session') {
        recovered = true;
        if (!login(S)) return res;
        recoverCart(S);
        continue;
      }
      return res; // denied or recovery exhausted
    }
    if (res.status === 429 && throttled < 4) {
      throttled++;
      const ra = parseFloat(hdr(res, 'Retry-After'));
      sleep(ra > 0 ? ra : 1);
      continue;
    }
    absorb(S, res);
    return res;
  }
}

// ---------- catalog selection ----------
function collectProducts(node, out) {
  if (Array.isArray(node)) {
    node.forEach((n) => collectProducts(n, out));
    return;
  }
  if (node && typeof node === 'object') {
    if (Array.isArray(node.variants) && node.id !== undefined && node.id !== null) out.push(node);
    for (const k in node) {
      if (node[k] && typeof node[k] === 'object') collectProducts(node[k], out);
    }
  }
}

function inStock(v) {
  return v && (v.in_stock === true || v.in_stock === 'true' || v.in_stock === 1);
}

function findPick(j) {
  if (!j) return null;
  const prods = [];
  collectProducts(j, prods);
  for (let i = 0; i < prods.length; i++) {
    const p = prods[i];
    const vs = p.variants || [];
    for (let k = 0; k < vs.length; k++) {
      if (inStock(vs[k]) && vs[k].id !== undefined) {
        return { product_id: p.id, variant_id: vs[k].id };
      }
    }
  }
  return null;
}

function selectProduct(S) {
  let r = send(S, 'GET', '/v2/catalog', undefined, null, 'GET /v2/catalog');
  let j = jsonOf(r);
  let pick = findPick(j);
  let next = j && j.next ? j.next : null;
  if (!pick && !next) next = '/v2/catalog/page';
  let pages = 0;
  while (!pick && next && pages < 3) {
    r = send(S, 'GET', next, undefined, null, 'GET /v2/catalog/page');
    j = jsonOf(r);
    pick = findPick(j);
    next = j && j.next ? j.next : null;
    pages++;
  }
  check(pick, { 'in-stock product/variant selected': (p) => !!p });
  return pick;
}

// ---------- challenge ----------
function getGrant(S) {
  const f = send(S, 'GET', '/v2/challenge-form', undefined, null, 'GET /v2/challenge-form');
  let action = null;
  let challenge = null;
  try {
    const doc = f.html();
    doc.find('form').toArray().forEach((fm) => {
      const a = fm.attr('action');
      if (!action && a && /\/v2\/challenges\//.test(a)) action = a;
    });
    const inp = doc.find('input[name="challenge"]').first();
    challenge = inp.attr('value');
  } catch (e) {
    // ignore
  }
  if (!action) {
    const m = f.body.match(/\/v2\/challenges\/[A-Za-z0-9_\-]+/);
    if (m) action = m[0];
  }
  if (!challenge) {
    const m = f.body.match(/name\s*=\s*["']?challenge["']?[^>]*value\s*=\s*["']?([^"'\s>]+)/i);
    if (m) challenge = m[1];
  }
  if (!check(f, { 'challenge form parsed': () => !!action && !!challenge })) return null;

  const p = send(S, 'POST', action, { challenge: challenge }, null, 'POST /v2/challenges/{id}');
  const loc = hdr(p, 'Location');
  if (!check(p, { 'challenge redirect': (x) => x.status >= 300 && x.status < 400 && !!loc })) return null;
  const g = send(S, 'GET', loc, undefined, null, 'GET challenge-location');
  const gj = jsonOf(g);
  if (!check(g, { 'grant obtained': () => !!gj && !!gj.grant_id })) return null;
  return gj.grant_id;
}

// ---------- cart ----------
function createCart(S, pick) {
  const body = { product_id: pick.product_id, variant_id: pick.variant_id };
  let r = send(S, 'POST', '/v2/carts', body, null, 'POST /v2/carts');
  if (r.status !== 201 && r.status !== 401 && /challenge|grant/i.test(r.body || '')) {
    const grant = getGrant(S);
    if (!grant) return false;
    body.grant_id = grant;
    r = send(S, 'POST', '/v2/carts', body, null, 'POST /v2/carts');
  }
  const j = jsonOf(r);
  const ok = check(r, { 'cart created': (x) => x.status === 201 && !!j && !!j.id });
  if (!ok) return false;
  S.cartId = j.id;
  S.etag = hdr(r, 'ETag') || S.etag;
  return true;
}

function findKey(node, key) {
  if (!node || typeof node !== 'object') return undefined;
  if (node[key] !== undefined && typeof node[key] !== 'object') return node[key];
  for (const k in node) {
    const v = findKey(node[k], key);
    if (v !== undefined) return v;
  }
  return undefined;
}

function readCart(S, pick) {
  const r = send(S, 'GET', '/v2/carts/' + S.cartId, undefined, null, 'GET /v2/carts/{id}');
  const et = hdr(r, 'ETag');
  if (et) S.etag = et;
  const j = jsonOf(r);
  const vid = j ? findKey(j, 'variant_id') : undefined;
  const pid = j ? findKey(j, 'product_id') : undefined;
  check(r, {
    'cart readable': (x) => x.status === 200,
    'cart keeps variant/product link': () =>
      (vid === undefined || String(vid) === String(pick.variant_id)) &&
      (pid === undefined || String(pid) === String(pick.product_id)),
  });
  return r.status === 200;
}

// ---------- reservation ----------
function reserve(S) {
  const r = send(S, 'POST', '/v2/reservations', { cart_id: S.cartId }, null, 'POST /v2/reservations');
  const j = jsonOf(r);
  if (!check(r, { 'reservation accepted': (x) => x.status === 202 && !!j && !!j.status_url })) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const s = send(S, 'GET', j.status_url, undefined, null, 'GET reservation-status');
    const sj = jsonOf(s);
    if (sj && sj.status === 'ready') {
      const rid = sj.reservation_id || sj.id;
      if (rid) return rid;
      return null;
    }
    if (sj && sj.status === 'failed') break;
  }
  check(null, { 'reservation ready': () => false });
  return null;
}

// ---------- order ----------
function placeOrder(S, pick) {
  const idemKey = 'k6-' + S.user + '-' + __ITER + '-' + S.cartId + '-' + Date.now();
  let reservationId = null;
  let reserved = false;
  let reread = false;
  let res = null;

  for (let attempt = 0; attempt < 3; attempt++) {
    const body = { cart_id: S.cartId };
    if (reservationId) body.reservation_id = reservationId;
    const h = { 'Idempotency-Key': idemKey };
    if (S.etag) h['If-Match'] = S.etag;
    res = send(S, 'POST', '/v2/orders', body, h, 'POST /v2/orders');

    if (res.status === 201) break;
    if (res.status === 412 && !reread) {
      reread = true;
      readCart(S, pick);
      continue;
    }
    if (!reserved && res.status !== 401 && res.status !== 412 && /reserv/i.test(res.body || '')) {
      reserved = true;
      reservationId = reserve(S);
      if (!reservationId) return false; // pending/failed must never reach checkout
      continue;
    }
    break;
  }

  const j = jsonOf(res);
  return check(res, {
    'order committed': (x) => x.status === 201 && !!j && j.accepted === true && !!j.id,
  });
}

// ---------- journey ----------
export default function () {
  const S = { user: 'bench-' + (((__VU - 1) % 16) + 1), csrf: null, cartId: null, etag: null };

  if (!login(S)) return;
  const pick = selectProduct(S);
  if (!pick) return;
  if (!createCart(S, pick)) return;
  if (!readCart(S, pick)) return;
  placeOrder(S, pick);
}
