import json
import os
import re
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse
from uuid import uuid4

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

ITERATIONS = 2
BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class Abort(Exception):
    pass


class Res:
    def __init__(self, ok, status, js, text, headers):
        self.ok = ok
        self.status = status
        self.js = js
        self.text = text
        self.headers = headers


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.forms = []

    def handle_starttag(self, tag, attrs):
        d = {k.lower(): (v if v is not None else "") for k, v in attrs}
        if tag == "input":
            self.inputs.append(d)
        elif tag == "form":
            self.forms.append(d)


def parse_html(text):
    p = FormParser()
    try:
        p.feed(text or "")
        p.close()
    except Exception:
        pass
    return p


def input_value(parser, name):
    cands = []
    for d in parser.inputs:
        if d.get("name", "").strip() != name or "disabled" in d:
            continue
        val = d.get("value", "").strip()
        if not val:
            continue
        cands.append(d)
    for d in cands:
        if d.get("type", "hidden").lower() == "hidden":
            return d["value"].strip()
    return cands[0]["value"].strip() if cands else None


def parse_json(r):
    try:
        t = r.text
        if t and t.strip():
            return json.loads(t)
    except Exception:
        pass
    return None


def norm(u, base="/v2/"):
    p = urlparse(u)
    if p.scheme:
        return p.path + ("?" + p.query if p.query else "")
    if u.startswith("/"):
        return u
    return urljoin(base, u)


def find_products(obj, out=None):
    if out is None:
        out = []
    if isinstance(obj, dict):
        if "id" in obj and isinstance(obj.get("variants"), list):
            out.append(obj)
            return out
        for v in obj.values():
            find_products(v, out)
    elif isinstance(obj, list):
        for v in obj:
            find_products(v, out)
    return out


def truthy(v):
    if v is True:
        return True
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return v == 1
    if isinstance(v, str):
        return v.strip().lower() in ("true", "1", "yes")
    return False


def eligible_product(p):
    if p.get("active") is False or p.get("archived") is True or p.get("available") is False:
        return False
    if str(p.get("status", "")).lower() in ("archived", "disabled", "discontinued", "inactive", "hidden"):
        return False
    return True


def pick(js):
    for p in find_products(js):
        if not eligible_product(p):
            continue
        for v in p["variants"]:
            if isinstance(v, dict) and v.get("id") is not None and truthy(v.get("in_stock")):
                return p["id"], v["id"]
    return None


def next_of(js):
    if isinstance(js, dict):
        n = js.get("next")
        if n:
            return n
        d = js.get("data")
        if isinstance(d, dict) and d.get("next"):
            return d["next"]
    return None


class ShopUser(HttpUser):
    host = BASE
    wait_time = constant(0)
    _counter = 0

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        ShopUser._counter += 1
        self.username = "bench-%d" % (((ShopUser._counter - 1) % 16) + 1)
        self.done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.grant_enabled = True
        self.pid = None
        self.vid = None

    # ---------- generic request wrapper ----------
    def api(self, method, path, name, body=None, body_fn=None, headers=None, headers_fn=None,
            expect=(200,), check=None, auth=True, recover=True, soft=(), on_412=None):
        recovered = False
        did412 = False
        n429 = 0
        while True:
            h = {}
            if headers_fn:
                h.update(headers_fn())
            if headers:
                h.update(headers)
            if auth and method != "GET" and self.csrf:
                h["X-CSRF-Token"] = self.csrf
            payload = body_fn() if body_fn else body
            action = None
            wait = 0
            with self.client.request(method, path, name=name, json=payload, headers=h,
                                     allow_redirects=False, catch_response=True) as r:
                sc = r.status_code
                js = parse_json(r)
                res = Res(False, sc, js, r.text, r.headers)
                err_code = js.get("error") if isinstance(js, dict) else None
                if sc == 401 and recover and not recovered and err_code in ("expired", "session"):
                    r.success()
                    action = ("rec", err_code)
                elif sc == 429 and n429 < 4:
                    r.success()
                    try:
                        wait = float(r.headers.get("Retry-After", "1"))
                    except Exception:
                        wait = 1.0
                    action = ("429",)
                elif sc == 412 and on_412 and not did412:
                    r.success()
                    action = ("412",)
                elif sc in expect:
                    err = check(res) if check else None
                    if err:
                        r.failure(err)
                    else:
                        r.success()
                        res.ok = True
                elif sc in soft:
                    r.success()
                else:
                    r.failure("unexpected status %s: %s" % (sc, (r.text or "")[:120]))
            if action is None:
                if res.ok and isinstance(js, dict) and isinstance(js.get("csrf"), str) and js["csrf"]:
                    self.csrf = js["csrf"]
                return res
            if action[0] == "429":
                n429 += 1
                time.sleep(max(wait, 1.0))
            elif action[0] == "412":
                did412 = True
                on_412()
            else:
                recovered = True
                self.recover_session(action[1])

    def recover_session(self, kind):
        rr = self.api("POST", "/v2/session/renew", "/v2/session/renew", body={}, recover=False,
                      soft=(400, 401, 403) if kind == "session" else ())
        if not rr.ok:
            if kind == "session":
                self.grant_id = None
                self.login()
            else:
                raise Abort()
        if self.cart_id:
            rc = self.api("POST", "/v2/carts/%s/recover" % self.cart_id, "/v2/carts/[id]/recover",
                          body={}, expect=(200, 201, 204), recover=False)
            if not rc.ok:
                raise Abort()
            et = rc.headers.get("ETag")
            if et:
                self.etag = et

    # ---------- login ----------
    def login(self):
        def chk_form(res):
            if not input_value(parse_html(res.text), "csrf"):
                return "csrf input not found"
            return None

        f = self.api("GET", "/v2/login-form", "/v2/login-form", auth=False, recover=False, check=chk_form)
        if not f.ok:
            raise Abort()
        form_csrf = input_value(parse_html(f.text), "csrf")
        self.csrf = form_csrf
        lr = self.api("POST", "/v2/login", "/v2/login",
                      body={"username": self.username, "password": "bench", "csrf": form_csrf},
                      auth=False, recover=False, expect=(200, 302))
        if not lr.ok:
            raise Abort()
        if lr.status == 302:
            loc = lr.headers.get("Location")
            if not loc:
                raise Abort()
            g = self.api("GET", norm(loc), "/v2/login [redirect]", auth=False, recover=False)
            if not g.ok:
                raise Abort()
        if not self.csrf:
            self.csrf = form_csrf

    # ---------- challenge / grant ----------
    def fetch_grant(self):
        self.grant_id = None
        f = self.api("GET", "/v2/challenge-form", "/v2/challenge-form", expect=(200, 404))
        if f.status == 404:
            self.grant_enabled = False
            return
        if not f.ok:
            raise Abort()
        parser = parse_html(f.text)
        action = None
        for fm in parser.forms:
            m = re.search(r"/v2/challenges/[^/\s\"'?#]+", fm.get("action", ""))
            if m:
                action = m.group(0)
                break
        challenge = input_value(parser, "challenge")
        if not action or not challenge:
            raise Abort()
        pr = self.api("POST", action, "/v2/challenges/[id]", body={"challenge": challenge}, expect=(302,))
        if not pr.ok:
            raise Abort()
        loc = pr.headers.get("Location")
        if not loc:
            raise Abort()

        def chk(res):
            if not isinstance(res.js, dict) or not res.js.get("grant_id"):
                return "grant_id missing"
            return None

        g = self.api("GET", norm(loc), "/v2/challenges/[id] [claim]", check=chk)
        if not g.ok:
            raise Abort()
        self.grant_id = g.js["grant_id"]

    # ---------- catalog ----------
    def select_product(self):
        c = self.api("GET", "/v2/catalog", "/v2/catalog")
        if not c.ok:
            raise Abort()
        sel = pick(c.js)
        if sel:
            return sel
        url = norm(next_of(c.js)) if next_of(c.js) else "/v2/catalog/page"
        for _ in range(3):
            pg = self.api("GET", url, "/v2/catalog/page")
            if not pg.ok:
                raise Abort()
            sel = pick(pg.js)
            if sel:
                return sel
            nxt = next_of(pg.js)
            if not nxt:
                break
            url = norm(nxt, "/v2/catalog/")
        raise Abort()

    # ---------- cart ----------
    def linked(self, res):
        js = res.js
        if not isinstance(js, dict):
            return "no json body"
        if "variant_id" in js and str(js["variant_id"]) != str(self.vid):
            return "variant mismatch"
        if "product_id" in js and str(js["product_id"]) != str(self.pid):
            return "product mismatch"
        return None

    def create_cart(self):
        def body():
            if self.grant_enabled and self.grant_id is None:
                self.fetch_grant()
            b = {"product_id": self.pid, "variant_id": self.vid}
            if self.grant_id:
                b["grant_id"] = self.grant_id
            return b

        def chk(res):
            if not isinstance(res.js, dict) or res.js.get("id") is None:
                return "cart id missing"
            return self.linked(res)

        r = self.api("POST", "/v2/carts", "/v2/carts", body_fn=body, expect=(201,), check=chk)
        if not r.ok:
            raise Abort()
        self.grant_id = None
        self.cart_id = r.js["id"]
        et = r.headers.get("ETag")
        if et:
            self.etag = et

    def refresh_cart(self):
        r = self.api("GET", "/v2/carts/%s" % self.cart_id, "/v2/carts/[id]", check=self.linked)
        if not r.ok:
            raise Abort()
        et = r.headers.get("ETag")
        if et:
            self.etag = et

    # ---------- reservation ----------
    def reserve(self):
        def chk(res):
            if not isinstance(res.js, dict) or not res.js.get("status_url"):
                return "status_url missing"
            return None

        r = self.api("POST", "/v2/reservations", "/v2/reservations", body={"cart_id": self.cart_id},
                     expect=(202,), check=chk, soft=(404,))
        if r.status == 404:
            return None
        if not r.ok:
            raise Abort()
        url = norm(r.js["status_url"], "/v2/reservations/")
        for _ in range(5):
            time.sleep(0.12)
            p = self.api("GET", url, "/v2/reservations/[status]", expect=(200, 202))
            if not p.ok or not isinstance(p.js, dict):
                raise Abort()
            st = p.js.get("status")
            if st == "ready":
                rid = p.js.get("reservation_id") or p.js.get("id")
                if not rid:
                    raise Abort()
                return rid
            if st == "failed":
                raise Abort()
        raise Abort()

    # ---------- order ----------
    def place_order(self, rid):
        key = "idem-%s-%s" % (self.cart_id, uuid4().hex[:12])
        body = {"cart_id": self.cart_id}
        if rid:
            body["reservation_id"] = rid

        def hdr():
            h = {"Idempotency-Key": key}
            if self.etag:
                h["If-Match"] = self.etag
            return h

        def chk(res):
            if not isinstance(res.js, dict) or res.js.get("accepted") is not True:
                return "order not accepted"
            if "cart_id" in res.js and str(res.js["cart_id"]) != str(self.cart_id):
                return "cart mismatch"
            return None

        def reread():
            r = self.api("GET", "/v2/carts/%s" % self.cart_id, "/v2/carts/[id]")
            if r.ok and r.headers.get("ETag"):
                self.etag = r.headers.get("ETag")

        self.api("POST", "/v2/orders", "/v2/orders", body=body, headers_fn=hdr,
                 expect=(201,), check=chk, on_412=reread)

    # ---------- journey ----------
    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.grant_enabled = True
        self.login()
        self.pid, self.vid = self.select_product()
        self.create_cart()
        self.refresh_cart()
        rid = self.reserve()
        self.refresh_cart()
        self.place_order(rid)

    @task
    def flow(self):
        try:
            self.journey()
        except Abort:
            pass
        except Exception:
            pass
        self.done += 1
        if self.done >= ITERATIONS:
            raise StopUser()


class FlowShape(LoadTestShape):
    seen = False

    def tick(self):
        if self.get_run_time() > 180:
            return None
        n = self.runner.user_count if self.runner else 0
        if n > 0:
            self.seen = True
        if self.seen and n == 0:
            return None
        return (2, 2)
