import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.math.BigDecimal;
import java.util.*;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null
      ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  // ---------- minimal JSON parser (no extra libs) ----------
  static final class JP {
    final String s;
    int i = 0;
    JP(String s) { this.s = s; }
    void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
    Object val() {
      ws();
      char c = s.charAt(i);
      if (c == '{') {
        i++;
        Map<String, Object> m = new LinkedHashMap<>();
        ws();
        if (s.charAt(i) == '}') { i++; return m; }
        while (true) {
          ws(); String k = string(); ws(); i++;
          m.put(k, val());
          ws();
          char d = s.charAt(i++);
          if (d == '}') return m;
        }
      }
      if (c == '[') {
        i++;
        List<Object> l = new ArrayList<>();
        ws();
        if (s.charAt(i) == ']') { i++; return l; }
        while (true) {
          l.add(val());
          ws();
          char d = s.charAt(i++);
          if (d == ']') return l;
        }
      }
      if (c == '"') return string();
      if (s.startsWith("true", i)) { i += 4; return Boolean.TRUE; }
      if (s.startsWith("false", i)) { i += 5; return Boolean.FALSE; }
      if (s.startsWith("null", i)) { i += 4; return null; }
      int st = i;
      while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) i++;
      return new BigDecimal(s.substring(st, i));
    }
    String string() {
      i++;
      StringBuilder b = new StringBuilder();
      while (true) {
        char c = s.charAt(i++);
        if (c == '"') return b.toString();
        if (c == '\\') {
          char e = s.charAt(i++);
          switch (e) {
            case 'n': b.append('\n'); break;
            case 't': b.append('\t'); break;
            case 'r': b.append('\r'); break;
            case 'b': b.append('\b'); break;
            case 'f': b.append('\f'); break;
            case 'u': b.append((char) Integer.parseInt(s.substring(i, i + 4), 16)); i += 4; break;
            default: b.append(e);
          }
        } else b.append(c);
      }
    }
  }

  static Object parse(String t) {
    if (t == null) return null;
    try { return new JP(t.trim()).val(); } catch (Exception e) { return null; }
  }

  static String str(Session s, String k) {
    if (!s.contains(k)) return null;
    Object o = s.get(k);
    return o == null ? null : String.valueOf(o);
  }

  static String esc(String v) {
    if (v == null) return "";
    return v.replace("\\", "\\\\").replace("\"", "\\\"");
  }

  static String raw(Object o) {
    if (o instanceof BigDecimal) return ((BigDecimal) o).toPlainString();
    return String.valueOf(o);
  }

  static String lit(Object o) {
    if (o instanceof String) return "\"" + esc((String) o) + "\"";
    return raw(o);
  }

  static boolean truthy(Object o) {
    return Boolean.TRUE.equals(o) || "true".equals(String.valueOf(o));
  }

  // find first product with an in-stock variant: {productLit, variantLit}
  @SuppressWarnings("unchecked")
  static String[] find(Object o) {
    if (o instanceof Map) {
      Map<String, Object> m = (Map<String, Object>) o;
      Object vs = m.get("variants");
      if (vs instanceof List && m.get("id") != null) {
        for (Object v : (List<Object>) vs) {
          if (v instanceof Map) {
            Map<String, Object> vm = (Map<String, Object>) v;
            if (truthy(vm.get("in_stock")) && vm.get("id") != null) {
              return new String[] {lit(m.get("id")), lit(vm.get("id"))};
            }
          }
        }
      }
      for (Object v : m.values()) {
        String[] r = find(v);
        if (r != null) return r;
      }
    } else if (o instanceof List) {
      for (Object v : (List<Object>) o) {
        String[] r = find(v);
        if (r != null) return r;
      }
    }
    return null;
  }

  static String norm(String n) {
    if (n == null || n.isEmpty()) return "";
    if (n.startsWith("/")) return n;
    if (n.startsWith(BASE)) return n;
    return "";
  }

  static Session absorb(Session s) {
    Object o = parse(str(s, "body"));
    if (o instanceof Map) {
      Object c = ((Map<?, ?>) o).get("csrf");
      if (c instanceof String && !((String) c).isEmpty()) return s.set("csrf", c);
    }
    return s;
  }

  static String errKind(Session s) {
    if (!"401".equals(str(s, "st"))) return "";
    Object o = parse(str(s, "body"));
    if (o instanceof Map) {
      Object e = ((Map<?, ?>) o).get("error");
      if ("expired".equals(e)) return "expired";
      if ("session".equals(e)) return "session";
    }
    return "";
  }

  // ---------- chains ----------
  static ChainBuilder login() {
    return exec(s -> s.remove("loc").remove("csrf"))
        .exec(http("login form").get("/v2/login-form")
            .check(status().is(200),
                css("input[name='csrf']", "value").saveAs("formCsrf")))
        .exec(http("login").post("/v2/login")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"username\":\"" + esc(str(s, "user"))
                + "\",\"password\":\"bench\",\"csrf\":\"" + esc(str(s, "formCsrf")) + "\"}"))
            .check(status().in(200, 302),
                header("Location").optional().saveAs("loc"),
                bodyString().saveAs("body")))
        .exec(s -> absorb(s))
        .doIf(s -> s.contains("loc")).then(
            exec(http("login redirect").get("#{loc}")
                .check(status().is(200), bodyString().saveAs("body")))
                .exec(s -> absorb(s)))
        .exec(s -> s.contains("csrf") ? s : s.set("csrf", str(s, "formCsrf")));
  }

  static ChainBuilder recovery() {
    return exec(http("renew session").post("/v2/session/renew")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody("{}"))
        .check(status().in(200, 401), status().saveAs("rst"), bodyString().saveAs("body")))
        .exec(s -> "200".equals(str(s, "rst")) ? absorb(s) : s)
        .doIf(s -> !"200".equals(str(s, "rst"))).then(login())
        .doIf(s -> s.contains("cartId")).then(
            exec(http("recover cart").post("/v2/carts/#{cartId}/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 201, 202, 204),
                    bodyString().saveAs("body"),
                    header("ETag").optional().saveAs("etag")))
                .exec(s -> absorb(s)));
  }

  // first attempt tolerates expiry 401; recovery + one retry of the same op only
  static ChainBuilder guarded(Function<Boolean, HttpRequestActionBuilder> mk) {
    return exec(mk.apply(true))
        .doIf(s -> !errKind(s).isEmpty()).then(
            recovery().exec(mk.apply(false)));
  }

  static HttpRequestActionBuilder withCommon(HttpRequestActionBuilder r, boolean first) {
    if (first) {
      return r.check(status().in(201, 401, 200),
          status().saveAs("st"),
          bodyString().saveAs("body"),
          regex("\"error\"\\s*:\\s*\"denied\"").notExists());
    }
    return r.check(status().saveAs("st"), bodyString().saveAs("body"));
  }

  static HttpRequestActionBuilder createCart(boolean first) {
    HttpRequestActionBuilder r = http("create cart").post("/v2/carts")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(s -> "{\"product_id\":" + str(s, "pid")
            + ",\"variant_id\":" + str(s, "vid") + "}"))
        .check(header("ETag").optional().saveAs("etag"));
    r = first ? r.check(status().in(201, 401)) : r.check(status().is(201));
    return withCommon(r, false).check(
        regex("\"error\"\\s*:\\s*\"denied\"").notExists());
  }

  static HttpRequestActionBuilder getCart(boolean first) {
    HttpRequestActionBuilder r = http("get cart").get("/v2/carts/#{cartId}");
    if (first) {
      r = r.check(status().in(200, 401), header("ETag").optional().saveAs("etag"));
    } else {
      r = r.check(status().is(200), header("ETag").saveAs("etag"));
    }
    return withCommon(r, false).check(
        regex("\"error\"\\s*:\\s*\"denied\"").notExists());
  }

  static HttpRequestActionBuilder placeOrder(boolean first) {
    HttpRequestActionBuilder r = http("create order").post("/v2/orders")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "#{idem}")
        .header("If-Match", s -> str(s, "etag") == null ? "*" : str(s, "etag"))
        .body(StringBody(s -> "{\"cart_id\":" + str(s, "cartLit") + "}"))
        .check(regex("\"accepted\"\\s*:\\s*false").notExists(),
            regex("\"error\"\\s*:\\s*\"denied\"").notExists());
    r = first ? r.check(status().in(201, 401)) : r.check(status().is(201));
    return withCommon(r, false);
  }

  ChainBuilder journey = exec(flushCookieJar())
      .exec(s -> s.remove("cartId").remove("cartLit").remove("etag")
          .remove("orderId").remove("idem").remove("pid").remove("vid").remove("st")
          .set("user", "bench-" + (int) ((s.userId() - 1) % 16 + 1))
          .set("found", false)
          .set("page", "/v2/catalog/page"))
      .exec(login())
      // bounded cursor traversal: at most 3 pages
      .repeat(3).on(
          doIf(s -> !s.getBoolean("found") && !str(s, "page").isEmpty()).then(
              exec(http("catalog page").get(s -> str(s, "page"))
                  .check(status().is(200), bodyString().saveAs("body")))
                  .exec(s -> {
                    Object root = parse(str(s, "body"));
                    Session n = s;
                    String next = "";
                    if (root instanceof Map) {
                      Object nx = ((Map<?, ?>) root).get("next");
                      if (nx instanceof String) next = norm((String) nx);
                    }
                    String[] f = find(root);
                    if (f != null) {
                      n = n.set("found", true).set("pid", f[0]).set("vid", f[1]);
                    }
                    return n.set("page", next);
                  })))
      .doIf(s -> s.getBoolean("found")).then(
          guarded(ModelSimulation::createCart)
              .exec(s -> {
                Object o = parse(str(s, "body"));
                Session n = s;
                if (o instanceof Map && "201".equals(str(s, "st"))) {
                  Object id = ((Map<?, ?>) o).get("id");
                  if (id != null) n = n.set("cartId", raw(id)).set("cartLit", lit(id));
                }
                return absorb(n);
              })
              .doIf(s -> s.contains("cartId")).then(
                  guarded(ModelSimulation::getCart)
                      .exec(s -> s.set("idem", "idem-" + str(s, "user") + "-" + str(s, "cartId")))
                      .exec(s -> absorb(s))
                      .exec(guarded(ModelSimulation::placeOrder))
                      .exec(s -> {
                        Object o = parse(str(s, "body"));
                        Session n = s;
                        if (o instanceof Map && "201".equals(str(s, "st"))) {
                          Object id = ((Map<?, ?>) o).get("id");
                          if (id != null) n = n.set("orderId", raw(id));
                        }
                        return absorb(n);
                      })));

  HttpProtocolBuilder httpProtocol = http.baseUrl(BASE)
      .disableFollowRedirect()
      .disableCaching()
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

  ScenarioBuilder scn = scenario("pagination checkout").repeat(2).on(journey);

  {
    setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
