import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const MAX_PAGES = 3;

export const options = {
  scenarios: {
    pagination: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
};

// ---------- helpers ----------
function J(res) {
  try { return res.json(); } catch (e) { return null; }
}
function hdr(res, name) {
  const l = name.toLowerCase();
  for (const k in res.headers) if (k.toLowerCase() === l) return res.headers[k];
  return null;
}
function errOf(res) {
  const b = J(res);
  if (!b || b.error === undefined || b.error === null) return '';
  if (typeof b.error === 'string') return b.error;
  return String(b.error.code || b.error.error || b.error.message || '');
}
function abs(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  if (u.charAt(0) === '/') return BASE + u;
  return BASE + '/' + u;
}
function parseCsrf(html) {
  try {
    const els = parseHTML(html).find('input[name=csrf]');
    let first = null;
    for (let i = 0; i < els.size(); i++) {
      const e = els.eq(i);
      const v = e.attr('value');
      if (!v) continue;
      if (e.attr('disabled') !== undefined) continue;
      const t = (e.attr('type') || 'hidden').toLowerCase();
      if (t === 'hidden') return v;
      if (!first) first = v;
    }
    if (first) return first;
  } catch (e) { /* fall through */ }
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const t of tags) {
    if (/\bname\s*=\s*["']?csrf["'\s>\/]/i.test(t)) {
      const m = t.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      if (m) return m[1] || m[2] || m[3];
    }
  }
  return null;
}

function raw(ctx, method, path, body, extra, name) {
  const headers = Object.assign({}, extra || {});
  let payload = null;
  if (body !== null && body !== undefined) {
    headers['Content-Type'] = 'application/json';
    payload = JSON.stringify(body);
  }
  if (method !== 'GET' && ctx.csrf) headers['X-CSRF-Token'] = ctx.csrf;
  const url = /^https?:/i.test(path) ? path : BASE + path;
  return http.request(method, url, payload, {
    headers,
    redirects: 0,
    tags: { name: name || path },
  });
}
function absorbCsrf(ctx, res) {
  const b = J(res);
  if (b && typeof b.csrf === 'string' && b.csrf) ctx.csrf = b.csrf;
}

// ---------- login ----------
function login(ctx) {
  const form = http.get(BASE + '/v2/login-form', { redirects: 0, tags: { name: 'login-form' } });
  check(form, { 'login form 200': (r) => r.status === 200 });
  const formCsrf = parseCsrf(form.body || '');
  check(formCsrf, { 'login csrf found': (c) => !!c });
  let res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: ctx.user, password: 'bench', csrf: formCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0, tags: { name: 'login' } }
  );
  let body = J(res);
  if (res.status === 301 || res.status === 302 || res.status === 303 || res.status === 307) {
    const loc = hdr(res, 'Location');
    if (loc) {
      const r2 = http.get(abs(loc), { redirects: 0, tags: { name: 'login-redirect' } });
      const b2 = J(r2);
      if (b2) body = Object.assign({}, body || {}, b2);
      res = r2;
    }
  }
  const ok = check(res, { 'login ok': (r) => r.status >= 200 && r.status < 300 });
  if (!ok) fail('login failed ' + res.status);
  ctx.csrf = (body && body.csrf) || formCsrf;
}

// ---------- session recovery ----------
function renew(ctx) {
  const r = raw(ctx, 'POST', '/v2/session/renew', {}, null, 'session-renew');
  if (r.status >= 200 && r.status < 300) { absorbCsrf(ctx, r); return true; }
  return false;
}
function recoverCart(ctx) {
  if (!ctx.cartId) return;
  const r = raw(ctx, 'POST', '/v2/carts/' + ctx.cartId + '/recover', {}, null, 'cart-recover');
  check(r, { 'cart recover ok': (x) => x.status >= 200 && x.status < 300 });
  absorbCsrf(ctx, r);
}

// generic call: bounded 401 recovery (once), scheduled 429 retry (<=4)
function call(ctx, method, path, body, extra, name) {
  let recovered = false;
  let retries429 = 0;
  for (;;) {
    const res = raw(ctx, method, path, body, extra, name);
    if (res.status === 429 && retries429 < 4) {
      retries429++;
      const ra = parseFloat(hdr(res, 'Retry-After') || '1');
      sleep(isNaN(ra) ? 1 : ra);
      continue;
    }
    if (res.status === 401 && !recovered) {
      const e = errOf(res);
      if (e === 'expired') {
        recovered = true;
        const ok = renew(ctx);
        if (!ok) login(ctx);
        recoverCart(ctx);
        continue;
      }
      if (e === 'session') {
        recovered = true;
        if (!renew(ctx)) login(ctx);
        recoverCart(ctx);
        continue;
      }
      check(res, { 'not denied': () => e !== 'denied' });
    }
    return res;
  }
}

// ---------- catalog traversal ----------
function extractProducts(b) {
  if (!b) return [];
  const d = b.data !== undefined ? b.data : b;
  if (d && Array.isArray(d.products)) return d.products;
  if (d && d.product) return [d.product];
  if (b.product) return [b.product];
  if (Array.isArray(d)) return d;
  if (d && d.id !== undefined && d.variants) return [d];
  return [];
}
function inStock(v) {
  return v && (v.in_stock === true || v.in_stock === 1 || v.in_stock === 'true');
}
function findEligible(ctx) {
  let url = '/v2/catalog/page';
  const seen = {};
  for (let page = 0; page < MAX_PAGES && url; page++) {
    if (seen[url]) break;
    seen[url] = true;
    const res = call(ctx, 'GET', url, null, null, 'catalog-page');
    if (!check(res, { 'catalog page 200': (r) => r.status === 200 })) return null;
    const b = J(res);
    const prods = extractProducts(b);
    for (const p of prods) {
      const vs = (p && p.variants) || [];
      for (const v of vs) {
        if (inStock(v)) return { product_id: p.id, variant_id: v.id };
      }
    }
    url = b && b.next ? b.next : null;
  }
  return null;
}

// ---------- optional flows ----------
function getGrant(ctx) {
  const f = call(ctx, 'GET', '/v2/challenge-form', null, null, 'challenge-form');
  if (f.status !== 200) return null;
  const html = f.body || '';
  const am = html.match(/\/v2\/challenges\/[A-Za-z0-9_\-]+/);
  let chal = null;
  try {
    const el = parseHTML(html).find('input[name=challenge]');
    if (el.size() > 0) chal = el.first().attr('value');
  } catch (e) { /* ignore */ }
  if (!chal) {
    const m = html.match(/<input[^>]*name=["']?challenge["']?[^>]*value=["']?([^"'\s>]+)/i);
    if (m) chal = m[1];
  }
  if (!am || !chal) return null;
  const p = raw(ctx, 'POST', am[0], { challenge: chal }, null, 'challenge-post');
  const loc = hdr(p, 'Location');
  if (!loc) return null;
  const g = call(ctx, 'GET', abs(loc), null, null, 'challenge-claim');
  const gb = J(g);
  if (!gb || !gb.grant_id) return null;
  absorbCsrf(ctx, g);
  return gb.grant_id;
}

function reserve(ctx) {
  const r = call(ctx, 'POST', '/v2/reservations', { cart_id: ctx.cartId }, null, 'reservations');
  const b = J(r);
  if (r.status !== 202 || !b || !b.status_url) return null;
  absorbCsrf(ctx, r);
  for (let i = 0; i < 5; i++) {
    sleep(0.1);
    const s = call(ctx, 'GET', b.status_url, null, null, 'reservation-status');
    const sb = J(s);
    if (sb && sb.status === 'ready') return sb.reservation_id || sb.id || null;
    if (sb && sb.status === 'failed') return null;
  }
  return null;
}

function refreshEtag(ctx) {
  const r = call(ctx, 'GET', '/v2/carts/' + ctx.cartId, null, null, 'cart-get');
  const e = hdr(r, 'ETag');
  if (e) ctx.etag = e;
  return r;
}

// ---------- journey ----------
export default function () {
  const n = ((__VU - 1) % 16) + 1;
  const ctx = { user: 'bench-' + n, csrf: null, cartId: null, etag: null };

  login(ctx);

  const item = findEligible(ctx);
  if (!check(item, { 'eligible item found within page bound': (x) => !!x })) return;

  // create cart (exactly once; challenge grant only if server demands it)
  let payload = { product_id: item.product_id, variant_id: item.variant_id };
  let cres = call(ctx, 'POST', '/v2/carts', payload, null, 'cart-create');
  if (cres.status !== 201) {
    const e = errOf(cres).toLowerCase();
    if (e.indexOf('challenge') >= 0 || e.indexOf('grant') >= 0) {
      const gid = getGrant(ctx);
      if (gid) {
        payload = { product_id: item.product_id, variant_id: item.variant_id, grant_id: gid };
        cres = call(ctx, 'POST', '/v2/carts', payload, null, 'cart-create');
      }
    }
  }
  const cb = J(cres);
  if (!check(cres, {
    'cart created 201': (r) => r.status === 201,
    'cart id present': () => !!(cb && cb.id),
  })) return;
  ctx.cartId = cb.id;
  absorbCsrf(ctx, cres);
  ctx.etag = hdr(cres, 'ETag');
  refreshEtag(ctx);

  // order
  const key = 'ord-' + __VU + '-' + __ITER + '-' + ctx.cartId + '-' + Date.now();
  let reservationId = null;
  let ores = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    const h = { 'Idempotency-Key': key };
    if (ctx.etag) h['If-Match'] = ctx.etag;
    const body = { cart_id: ctx.cartId };
    if (reservationId) body.reservation_id = reservationId;
    ores = call(ctx, 'POST', '/v2/orders', body, h, 'order-create');
    if (ores.status === 412 && attempt < 2) {
      refreshEtag(ctx);
      continue;
    }
    if (ores.status !== 201 && !reservationId && attempt < 2 &&
        errOf(ores).toLowerCase().indexOf('reservation') >= 0) {
      reservationId = reserve(ctx);
      if (!reservationId) break;
      continue;
    }
    break;
  }
  const ob = J(ores);
  check(ores, {
    'order created 201': (r) => r.status === 201,
    'order accepted': () => !!(ob && ob.accepted === true),
    'order id present': () => !!(ob && ob.id),
  });
  if (ob && ob.accepted === true && ob.id) {
    absorbCsrf(ctx, ores);
    check(ob, { 'cart/order ids extracted': () => !!ctx.cartId && !!ob.id });
  }
}
