import os
import re
import time
import uuid
import html as htmllib
from urllib.parse import urlparse

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS = 2
USERS = 2
MAX_PAGES = 3

_user_counter = [0]

_TAG_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"([\w:\-]+)\s*(?:=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>\"']+)))?", re.S)
_FORM_RE = re.compile(r"<form\b([^>]*)>(.*?)</form>", re.I | re.S)
_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)


def _attrs(tag):
    out = {}
    body = tag[6:] if tag.lower().startswith("<input") else tag
    for m in _ATTR_RE.finditer(body):
        k = m.group(1).lower()
        v = m.group(2) if m.group(2) is not None else (
            m.group(3) if m.group(3) is not None else (m.group(4) or ""))
        out[k] = htmllib.unescape(v)
    return out


def _find_input(doc, name):
    cands = []
    for m in _TAG_RE.finditer(doc):
        a = _attrs(m.group(0))
        if a.get("name") == name and "value" in a:
            cands.append(a)
    good = [a for a in cands
            if "disabled" not in a
            and not any(k.startswith("data-decoy") for k in a)
            and "decoy" not in a.get("class", "").lower()
            and "decoy" not in a.get("id", "").lower()]
    if good:
        return good[0]["value"]
    if cands:
        return cands[0]["value"]
    return None


def _clean(text):
    return _COMMENT_RE.sub("", text or "")


def _path_of(loc):
    if not loc:
        return None
    if loc.startswith("http://") or loc.startswith("https://"):
        p = urlparse(loc)
        return p.path + (("?" + p.query) if p.query else "")
    return loc


def _json(r):
    try:
        j = r.json()
        return j if isinstance(j, dict) else {}
    except Exception:
        return {}


def _truthy(v):
    if isinstance(v, str):
        return v.strip().lower() in ("true", "1", "yes")
    return v is True or v == 1


def _products(j):
    d = j.get("data", j)
    if isinstance(d, list):
        return [p for p in d if isinstance(p, dict)]
    if isinstance(d, dict):
        if isinstance(d.get("products"), list):
            return [p for p in d["products"] if isinstance(p, dict)]
        if isinstance(d.get("product"), dict):
            return [d["product"]]
        if "id" in d and "variants" in d:
            return [d]
    if isinstance(j.get("product"), dict):
        return [j["product"]]
    return []


def _next_of(j):
    n = j.get("next")
    if n is None and isinstance(j.get("data"), dict):
        n = j["data"].get("next")
    return n or None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        _user_counter[0] += 1
        self.username = "bench-%d" % (((_user_counter[0] - 1) % 16) + 1)
        self.done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.results = []

    # ---------- helpers ----------
    def _upd(self, r):
        j = _json(r)
        if j.get("csrf"):
            self.csrf = j["csrf"]
        et = r.headers.get("ETag")
        if et:
            self.etag = et
        return j

    @staticmethod
    def _err_of(r):
        j = _json(r)
        e = j.get("error")
        if isinstance(e, dict):
            e = e.get("code") or e.get("error")
        if not e:
            e = j.get("code")
        return str(e) if e else ""

    def call(self, method, url, name, ok=(200,), build=None, validate=None,
             on412=None):
        recovered = False
        refreshed = False
        throttled = 0
        while True:
            kw = build() if build else {}
            headers = dict(kw.pop("headers", {}) or {})
            if method != "GET" and self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            action = None
            with self.client.request(method, url, name=name, headers=headers,
                                     allow_redirects=False,
                                     catch_response=True, **kw) as r:
                sc = r.status_code
                if sc == 401:
                    err = self._err_of(r)
                    if err in ("expired", "session") and not recovered:
                        r.success()
                        recovered = True
                        action = ("rec", err)
                    else:
                        r.failure("401 error=%s" % err)
                        return None
                elif sc == 412 and on412 and not refreshed:
                    r.success()
                    refreshed = True
                    action = ("412", None)
                elif sc == 429 and throttled < 4:
                    r.success()
                    throttled += 1
                    try:
                        wait = float(r.headers.get("Retry-After", "1"))
                    except Exception:
                        wait = 1.0
                    action = ("429", max(wait, 1.0))
                elif sc in ok:
                    if validate:
                        msg = validate(r)
                        if msg:
                            r.failure(msg)
                            return None
                    r.success()
                    return r
                else:
                    r.failure("unexpected status %s" % sc)
                    return None
            kind, val = action
            if kind == "rec":
                if not self.recover(val):
                    return None
            elif kind == "412":
                if not on412():
                    return None
            elif kind == "429":
                time.sleep(val)

    # ---------- session ----------
    def login(self):
        self.client.cookies.clear()
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            doc = _clean(r.text)
            form_csrf = None
            for m in _FORM_RE.finditer(doc):
                if "login" in m.group(1).lower():
                    form_csrf = _find_input(m.group(2), "csrf")
                    if form_csrf:
                        break
            if not form_csrf:
                form_csrf = _find_input(doc, "csrf")
            if not form_csrf:
                r.failure("csrf input not found")
                return False
            r.success()
        payload = {"username": self.username, "password": "bench",
                   "csrf": form_csrf}
        csrf = None
        loc = None
        with self.client.post("/v2/login", json=payload, name="/v2/login",
                              allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code == 200:
                csrf = _json(r).get("csrf")
                r.success()
            elif r.status_code in (301, 302, 303, 307, 308):
                loc = _path_of(r.headers.get("Location"))
                if not loc:
                    r.failure("redirect without Location")
                    return False
                r.success()
            else:
                r.failure("login status %s" % r.status_code)
                return False
        if loc:
            with self.client.get(loc, name="/v2/login [redirect]",
                                 catch_response=True) as r2:
                if r2.status_code != 200:
                    r2.failure("login redirect status %s" % r2.status_code)
                    return False
                csrf = _json(r2).get("csrf") or csrf
                r2.success()
        self.csrf = csrf or form_csrf
        return True

    def recover(self, err):
        renewed = False
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="/v2/session/renew",
                              allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code == 200:
                c = _json(r).get("csrf")
                if c:
                    self.csrf = c
                renewed = True
                r.success()
            elif r.status_code == 401 and err == "session":
                r.success()  # expected: revoked session cannot be renewed
            elif r.status_code == 401:
                r.success()
            else:
                r.failure("renew status %s" % r.status_code)
                return False
        if not renewed:
            if not self.login():
                return False
        if self.cart_id:
            with self.client.post("/v2/carts/%s/recover" % self.cart_id,
                                  json={},
                                  headers={"X-CSRF-Token": self.csrf or ""},
                                  name="/v2/carts/[id]/recover",
                                  allow_redirects=False,
                                  catch_response=True) as r:
                if r.status_code in (200, 201, 202, 204):
                    c = _json(r).get("csrf")
                    if c:
                        self.csrf = c
                    et = r.headers.get("ETag")
                    if et:
                        self.etag = et
                    r.success()
                else:
                    r.failure("recover status %s" % r.status_code)
                    return False
        return True

    # ---------- steps ----------
    def find_item(self):
        url = "/v2/catalog/page"
        seen = set()
        for page in range(1, MAX_PAGES + 1):
            if url in seen:
                return None
            seen.add(url)
            state = {}

            def validate(r, page=page, state=state):
                j = _json(r)
                nxt = _next_of(j)
                found = None
                for p in _products(j):
                    for v in (p.get("variants") or []):
                        if isinstance(v, dict) and _truthy(v.get("in_stock")):
                            found = (p.get("id"), v.get("id"))
                            break
                    if found:
                        break
                state["found"] = found
                state["next"] = nxt
                if not found and (nxt is None or page >= MAX_PAGES):
                    return "no eligible in-stock variant within bounded traversal"
                return None

            r = self.call("GET", url, "/v2/catalog/page", ok=(200,),
                          validate=validate)
            if r is None:
                return None
            if state.get("found"):
                return state["found"]
            nxt = state.get("next")
            if not nxt:
                return None
            url = _path_of(nxt)
        return None

    def get_grant(self):
        st = {}

        def v_form(r):
            doc = _clean(r.text)
            m = re.search(r"""action\s*=\s*["']?(/v2/challenges/[^"'\s>]+)""",
                          doc, re.I)
            ch = _find_input(doc, "challenge")
            if not m or not ch:
                return "challenge form incomplete"
            st["action"] = htmllib.unescape(m.group(1))
            st["challenge"] = ch
            return None

        r = self.call("GET", "/v2/challenge-form", "/v2/challenge-form",
                      ok=(200,), validate=v_form)
        if r is None:
            return None
        r = self.call("POST", st["action"], "/v2/challenges/[id]",
                      ok=(302, 303),
                      build=lambda: {"json": {"challenge": st["challenge"]}})
        if r is None:
            return None
        loc = _path_of(r.headers.get("Location"))
        if not loc:
            return None
        r = self.call("GET", loc, "/v2/challenges/[id] [redirect]",
                      ok=(200,))
        if r is None:
            return None
        j = self._upd(r)
        return j.get("grant_id")

    def read_cart(self):
        r = self.call("GET", "/v2/carts/%s" % self.cart_id,
                      "/v2/carts/[id]", ok=(200,))
        if r is None:
            return False
        self._upd(r)
        return True

    def create_cart(self, product_id, variant_id):
        def build():
            payload = {"product_id": product_id, "variant_id": variant_id}
            grant = self.get_grant()
            if grant:
                payload["grant_id"] = grant
            return {"json": payload}

        def validate(r):
            if not _json(r).get("id"):
                return "cart id missing"
            return None

        r = self.call("POST", "/v2/carts", "/v2/carts", ok=(201,),
                      build=build, validate=validate)
        if r is None:
            return False
        j = self._upd(r)
        self.cart_id = j["id"]
        return True

    def patch_cart(self, qty):
        r = self.call("PATCH", "/v2/carts/%s" % self.cart_id,
                      "/v2/carts/[id] PATCH", ok=(200, 204),
                      build=lambda: {"json": {"quantity": qty},
                                     "headers": {"If-Match": self.etag or "*"}},
                      on412=self.read_cart)
        if r is None:
            return False
        self._upd(r)
        return True

    def reserve(self):
        r = self.call("POST", "/v2/reservations", "/v2/reservations",
                      ok=(202, 200, 201),
                      build=lambda: {"json": {"cart_id": self.cart_id}})
        if r is None:
            return None
        j = self._upd(r)
        status_url = _path_of(j.get("status_url"))
        if not status_url:
            return None
        for _ in range(5):
            time.sleep(0.07)
            st = {}

            def validate(rr, st=st):
                jj = _json(rr)
                st["status"] = jj.get("status")
                st["rid"] = jj.get("reservation_id") or jj.get("id")
                if st["status"] == "failed":
                    return "reservation failed"
                return None

            rr = self.call("GET", status_url, "/v2/reservations/[status]",
                           ok=(200,), validate=validate)
            if rr is None:
                return None
            self._upd(rr)
            if st.get("status") == "ready" and st.get("rid"):
                return st["rid"]
        return None

    def place_order(self, reservation_id):
        key = "order-%s-%s" % (self.cart_id, uuid.uuid4().hex)

        def build():
            body = {"cart_id": self.cart_id}
            if reservation_id:
                body["reservation_id"] = reservation_id
            return {"json": body,
                    "headers": {"Idempotency-Key": key,
                                "If-Match": self.etag or "*"}}

        def validate(r):
            j = _json(r)
            if r.status_code != 201:
                return "order status %s accepted=%s" % (r.status_code,
                                                         j.get("accepted"))
            if j.get("accepted") is not True or not j.get("id"):
                return "order not accepted"
            return None

        r = self.call("POST", "/v2/orders", "/v2/orders", ok=(200, 201),
                      build=build, validate=validate, on412=self.read_cart)
        if r is None:
            return None
        j = self._upd(r)
        return j.get("id")

    # ---------- journey ----------
    def journey(self):
        self.cart_id = None
        self.etag = None
        if not self.login():
            return
        item = self.find_item()
        if not item:
            return
        if not self.create_cart(item[0], item[1]):
            return
        if not self.read_cart():
            return
        if not self.patch_cart(2):
            return
        rid = self.reserve()
        if not rid:
            return
        if not self.read_cart():
            return
        oid = self.place_order(rid)
        if oid:
            self.results.append((self.cart_id, oid))

    @task
    def run_journey(self):
        try:
            self.journey()
        finally:
            self.done += 1
        if self.done >= ITERATIONS:
            raise StopUser()


class Shape(LoadTestShape):
    max_time = 240

    def tick(self):
        t = self.get_run_time()
        if t > self.max_time:
            return None
        if t > 5 and self.runner is not None and self.runner.user_count == 0:
            return None
        return (USERS, USERS)
