import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";
  static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
  static final String QTY_BODY = "{\"quantity\":2}";

  HttpProtocolBuilder protocol = http
      .baseUrl(BASE)
      .disableFollowRedirect()
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

  ChainBuilder journey =
      exec(flushCookieJar())
          .exec(session -> {
            long id = session.userId();
            int n = (int) Math.floorMod(id - 1, 16L) + 1;
            return session.remove("loc").remove("newCsrf").remove("csrf").remove("etag")
                .remove("cartId").remove("patchStatus")
                .set("username", "bench-" + n);
          })
          // login form + csrf
          .exec(http("login form")
              .get("/v2/login-form")
              .header("Accept", "text/html")
              .check(status().is(200))
              .check(css("input[name=csrf]:not([disabled])", "value").saveAs("csrf")))
          // login
          .exec(http("login")
              .post("/v2/login")
              .asJson()
              .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
              .check(status().in(200, 302))
              .check(header("Location").optional().saveAs("loc"))
              .check(regex(CSRF_RE).optional().saveAs("csrf")))
          .doIf(session -> session.contains("loc")).then(
              exec(http("login redirect")
                  .get("#{loc}")
                  .check(status().is(200))
                  .check(regex(CSRF_RE).optional().saveAs("csrf"))))
          // catalog
          .exec(http("catalog")
              .get("/v2/catalog")
              .check(status().is(200))
              .check(jmesPath("data.products[?variants[?in_stock]] | [0].id").saveAs("productId"))
              .check(jmesPath("data.products[?variants[?in_stock]] | [0].variants[?in_stock] | [0].id").saveAs("variantId")))
          // create cart
          .exec(http("create cart")
              .post("/v2/carts")
              .asJson()
              .header("X-CSRF-Token", "#{csrf}")
              .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
              .check(status().is(201))
              .check(jmesPath("id").saveAs("cartId"))
              .check(regex(CSRF_RE).optional().saveAs("csrf")))
          // read initial revision
          .exec(http("read cart initial etag")
              .get("/v2/carts/#{cartId}")
              .check(status().is(200))
              .check(header("ETag").saveAs("etag")))
          // conditional update (scheduled conflict possible)
          .exec(session -> session.remove("newCsrf"))
          .exec(http("patch cart")
              .patch("/v2/carts/#{cartId}")
              .asJson()
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .body(StringBody(QTY_BODY))
              .check(status().in(200, 204, 412).saveAs("patchStatus"))
              .check(regex(CSRF_RE).optional().saveAs("newCsrf")))
          .exec(session -> {
            int st = session.getInt("patchStatus");
            if (st != 412 && session.contains("newCsrf")) {
              return session.set("csrf", session.getString("newCsrf")).remove("newCsrf");
            }
            return session.remove("newCsrf");
          })
          .doIf(session -> session.getInt("patchStatus") == 412).then(
              exec(http("re-read cart after 412")
                  .get("/v2/carts/#{cartId}")
                  .check(status().is(200))
                  .check(header("ETag").saveAs("etag")))
              .exec(http("patch cart retry")
                  .patch("/v2/carts/#{cartId}")
                  .asJson()
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("If-Match", "#{etag}")
                  .body(StringBody(QTY_BODY))
                  .check(status().in(200, 204))
                  .check(regex(CSRF_RE).optional().saveAs("csrf"))))
          // current revision for checkout
          .exec(http("read cart final etag")
              .get("/v2/carts/#{cartId}")
              .check(status().is(200))
              .check(header("ETag").saveAs("etag")))
          // order
          .exec(http("create order")
              .post("/v2/orders")
              .asJson()
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .header("Idempotency-Key", "order-#{cartId}")
              .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
              .check(status().is(201))
              .check(regex("\"accepted\"\\s*:\\s*true").exists())
              .check(regex(CSRF_RE).optional().saveAs("csrf")));

  ScenarioBuilder scn = scenario("etag cart journey").repeat(2).on(journey);

  {
    setUp(scn.injectOpen(atOnceUsers(2)))
        .protocols(protocol)
        .assertions(global().failedRequests().count().is(0L));
  }
}
