```javascript
import http from 'k6/http';
import { check, sleep, fail } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const QUANTITY = 2;
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
  thresholds: {
    checks: ['rate>=0.99'],
  },
};

http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 412, 429));

// ---------- helpers ----------
function jsonBody(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  const want = name.toLowerCase();
  for (const k of Object.keys(res.headers || {})) {
    if (k.toLowerCase() === want) return res.headers[k];
  }
  return null;
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  return BASE + '/v2/' + loc;
}

function tagAttr(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return null;
  return m[1] !== undefined ? m[1] : m[2] !== undefined ? m[2] : m[3];
}

function extractInput(html, inputName) {
  const clean = (html || '').replace(/<!--[\s\S]*?-->/g, '');
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  for (const t of tags) {
    const n = tagAttr(t, 'name');
    if (n === inputName) {
      const v = tagAttr(t, 'value');
      if (v !== null && v !== '') return v;
    }
  }
  return null;
}

function newCtx() {
  const n = ((__VU - 1) % 16) + 1;
  return { user: 'bench-' + n, csrf: null, cartId: null, etag: null };
}

function login(ctx) {
  const form = http.get(BASE + '/v2/login-form', { redirects: 0, tags: { name: 'login-form' } });
  const formCsrf = extractInput(form.body, 'csrf');
  check(form, { 'login form has csrf': () => !!formCsrf });
  if (!formCsrf) fail('no login csrf');
  const res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: ctx.user, password: PASSWORD, csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-CSRF-Token': formCsrf },
      redirects: 0,
      tags: { name: 'login' },
    }
  );
  let body = null;
  if ([301, 302, 303, 307, 308].indexOf(res.status) >= 0) {
    const loc = resolveUrl(hdr(res, 'Location'));
    check(res, { 'login redirect has location': () => !!loc });
    if (loc) {
      const r2 = http.get(loc, { redirects: 0, headers: { Accept: 'application/json' }, tags: { name: 'login-redirect' } });
      body = jsonBody(r2);
    }
  } else {
    check(res, { 'login 200': (r) => r.status === 200 });
    body = jsonBody(res);
  }
  if (body && body.csrf) ctx.csrf = body.csrf;
  else if (!ctx.csrf) ctx.csrf = formCsrf;
  check(null, { 'login produced csrf': () => !!ctx.csrf });
}

function recoverCart(ctx) {
  if (!ctx.cartId) return;
  const r = http.post(BASE + '/v2/carts/' + ctx.cartId + '/recover', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf },
    redirects: 0,
    tags: { name: 'recover' },
  });
  const b = jsonBody(r);
  if (b && b.csrf) ctx.csrf = b.csrf;
  const et = hdr(r, 'ETag');
  if (et) ctx.etag = et;
}

function refreshEtag(ctx) {
  const r = http.get(BASE + '/v2/carts/' + ctx.cartId, {
    headers: { Accept: 'application/json' },
    redirects: 0,
    tags: { name: 'cart-get' },
  });
  const et = hdr(r, 'ETag');
  if (et) ctx.etag = et;
  return r;
}

// Generic request with bounded 401 / 429 handling.
// spec: {method, path, body, ifMatch, name, extra}
function send(ctx, spec) {
  const headers = { 'Content-Type': 'application/json', Accept: 'application/json' };
  if (spec.method !== 'GET' && ctx.csrf) headers['X-CSRF-Token'] = ctx.csrf;
  if (spec.ifMatch && ctx.etag) headers['If-Match'] = ctx.etag;
  if (spec.extra) Object.keys(spec.extra).forEach((k) => (headers[k] = spec.extra[k]));
  const payload = spec.body !== undefined && spec.body !== null ? JSON.stringify(spec.body) : null;
  return http.request(spec.method, BASE + spec.path, payload, {
    headers,
    redirects: 0,
    tags: { name: spec.name || spec.path },
  });
}

function req(ctx, spec) {
  let res = send(ctx, spec);
  let recovered = false;
  let retries429 = 0;
  for (let guard = 0; guard < 8; guard++) {
    if (res.status === 429 && retries429 < 4) {
      retries429++;
      const ra = parseFloat(hdr(res, 'Retry-After') || '1');
      sleep(ra > 0 ? ra : 1);
      res = send(ctx, spec);
      continue;
    }
    if (res.status === 401 && !recovered) {
      const b = jsonBody(res) || {};
      if (b.error === 'expired') {
        recovered = true;
        const rn = http.post(BASE + '/v2/session/renew', '{}', {
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf },
          redirects: 0,
          tags: { name: 'renew' },
        });
        const rb = jsonBody(rn);
        check(rn, { 'renew ok': (r) => r.status === 200 });
        if (rb && rb.csrf) ctx.csrf = rb.csrf;
        recoverCart(ctx);
        if (spec.ifMatch && ctx.cartId) refreshEtag(ctx);
        res = send(ctx, spec);
        continue;
      } else if (b.error === 'session') {
        recovered = true;
        const rn = http.post(BASE + '/v2/session/renew', '{}', {
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf },
          redirects: 0,
          tags: { name: 'renew' },
        });
        if (rn.status === 200) {
          const rb = jsonBody(rn);
          if (rb && rb.csrf) ctx.csrf = rb.csrf;
        } else {
          login(ctx);
        }
        recoverCart(ctx);
        if (spec.ifMatch && ctx.cartId) refreshEtag(ctx);
        res = send(ctx, spec);
        continue;
      } else {
        check(res, { 'auth not denied': () => false });
        return res;
      }
    }
    break;
  }
  const b = jsonBody(res);
  if (b && b.csrf && spec.method !== 'GET') ctx.csrf = b.csrf;
  return res;
}

function findInStock(products) {
  for (const p of products || []) {
    for (const v of p.variants || []) {
      if (v.in_stock === true || v.in_stock === 1 || v.in_stock === 'true') {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  return null;
}

function chooseVariant(ctx) {
  const res = req(ctx, { method: 'GET', path: '/v2/catalog', name: 'catalog' });
  check(res, { 'catalog 200': (r) => r.status === 200 });
  const b = jsonBody(res);
  let pick = b && b.data ? findInStock(b.data.products) : null;
  if (pick) return pick;
  // paged traversal, at most 3 pages, following only server-provided next
  let url = '/v2/catalog/page';
  for (let i = 0; i < 3 && url; i++) {
    const r = req(ctx, { method: 'GET', path: url.replace(BASE, ''), name: 'catalog-page' });
    const pb = jsonBody(r);
    if (!pb) break;
    let prods = [];
    if (pb.data) {
      if (Array.isArray(pb.data.products)) prods = pb.data.products;
      else if (pb.data.product) prods = [pb.data.product];
      else if (pb.data.id) prods = [pb.data];
    }
    pick = findInStock(prods);
    if (pick) return pick;
    url = pb.next ? resolveUrl(pb.next).replace(BASE, '') : null;
  }
  return null;
}

function getGrant(ctx) {
  const f = req(ctx, { method: 'GET', path: '/v2/challenge-form', name: 'challenge-form' });
  const body = f.body || '';
  const am = body.replace(/<!--[\s\S]*?-->/g, '').match(/action\s*=\s*["']?(\/v2\/challenges\/[^"'\s>]+)/i);
  const ch = extractInput(body, 'challenge');
  if (!am || !ch) return null;
  const p = http.post(BASE + am[1], JSON.stringify({ challenge: ch }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': ctx.csrf },
    redirects: 0,
    tags: { name: 'challenge-post' },
  });
  const loc = resolveUrl(hdr(p, 'Location'));
  if (!loc) return null;
  const g = http.get(loc, { redirects: 0, headers: { Accept: 'application/json' }, tags: { name: 'challenge-claim' } });
  const gb = jsonBody(g);
  if (gb && gb.csrf) ctx.csrf = gb.csrf;
  return gb && gb.grant_id ? gb.grant_id : null;
}

// ---------- journey ----------
export default function () {
  const ctx = newCtx();
  login(ctx);

  const pick = chooseVariant(ctx);
  check(null, { 'in-stock variant found': () => !!pick });
  if (!pick) return;

  // create exactly one cart (retry only if the server demands a grant and nothing was created)
  let cartRes = req(ctx, {
    method: 'POST',
    path: '/v2/carts',
    body: { product_id: pick.product_id, variant_id: pick.variant_id },
    name: 'cart-create',
  });
  if (cartRes.status !== 201 && [400, 403, 409, 412, 428].indexOf(cartRes.status) >= 0) {
    const eb = jsonBody(cartRes) || {};
    if (/grant|challenge/i.test(JSON.stringify(eb))) {
      const grant = getGrant(ctx);
      if (grant) {
        cartRes = req(ctx, {
          method: 'POST',
          path: '/v2/carts',
          body: { product_id: pick.product_id, variant_id: pick.variant_id, grant_id: grant },
          name: 'cart-create',
        });
      }
    }
  }
  const cb = jsonBody(cartRes);
  const created = check(cartRes, {
    'cart created 201': (r) => r.status === 201,
    'cart has id': () => !!(cb && cb.id),
  });
  if (!created || !cb || !cb.id) return;
  ctx.cartId = cb.id;
  const createEtag = hdr(cartRes, 'ETag');
  if (createEtag) ctx.etag = createEtag;

  // read initial revision
  const g = req(ctx, { method: 'GET', path: '/v2/carts/' + ctx.cartId, name: 'cart-get' });
  const getEtag = hdr(g, 'ETag');
  check(g, {
    'cart get 200': (r) => r.status === 200,
    'initial etag extracted': () => !!getEtag,
  });
  if (getEtag) ctx.etag = getEtag;
  if (!ctx.etag) return;

  // conditional update; on 412 re-read and retry same payload once
  const patchBody = { quantity: QUANTITY };
  let p = req(ctx, {
    method: 'PATCH',
    path: '/v2/carts/' + ctx.cartId,
    body: patchBody,
    ifMatch: true,
    name: 'cart-patch',
  });
  if (p.status === 412) {
    const stale = ctx.etag;
    const rr = req(ctx, { method: 'GET', path: '/v2/carts/' + ctx.cartId, name: 'cart-get' });
    const fresh = hdr(rr, 'ETag');
    check(rr, {
      're-read after 412 ok': (r) => r.status === 200,
      'fresh etag after 412': () => !!fresh,
    });
    if (fresh) ctx.etag = fresh;
    p = req(ctx, {
      method: 'PATCH',
      path: '/v2/carts/' + ctx.cartId,
      body: patchBody,
      ifMatch: true,
      name: 'cart-patch-retry',
    });
  }
  const patched = check(p, { 'patch succeeded': (r) => r.status === 200 || r.status === 204 });
  if (!patched) return;
  const pe = hdr(p, 'ETag');
  if (pe) ctx.etag = pe;

  // fresh revision for order
  const g2 = req(ctx, { method: 'GET', path: '/v2/carts/' + ctx.cartId, name: 'cart-get' });
  const e2 = hdr(g2, 'ETag');
  if (e2) ctx.etag = e2;
  const gb2 = jsonBody(g2);
  if (gb2) {
    const q = gb2.quantity !== undefined ? gb2.quantity : gb2.data && gb2.data.quantity !== undefined ? gb2.data.quantity : undefined;
    if (q !== undefined) check(null, { 'quantity preserved': () => Number(q) === QUANTITY });
  }

  // order, stable idempotency key
  const idem = 'idem-' + ctx.cartId;
  const orderSpec = {
    method: 'POST',
    path: '/v2/orders',
    body: { cart_id: ctx.cartId },
    ifMatch: true,
    extra: { 'Idempotency-Key': idem },
    name: 'order',
  };
  let o = req(ctx, orderSpec);
  if (o.status === 412) {
    const rr = req(ctx, { method: 'GET', path: '/v2/carts/' + ctx.cartId, name: 'cart-get' });
    const fresh = hdr(rr, 'ETag');
    if (fresh) ctx.etag = fresh;
    o = req(ctx, orderSpec);
  }
  const ob = jsonBody(o);
  check(o, {
    'order 201': (r) => r.status === 201,
    'order accepted': () => !!(ob && ob.accepted === true),
  });
}
