import os
from html.parser import HTMLParser
from urllib.parse import urlparse

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS = 2
QUANTITY = 2
USERS = 2


class _CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.form_action = ""
        self.cands = []

    def handle_starttag(self, tag, attrs):
        a = {(k or "").lower(): v for k, v in attrs}
        if tag == "form":
            self.form_action = a.get("action") or ""
        elif tag == "input":
            if a.get("name") == "csrf" and "disabled" not in a and a.get("value"):
                score = (
                    1 if "login" in self.form_action else 0,
                    1 if (a.get("type") or "").lower() == "hidden" else 0,
                )
                self.cands.append((score, a["value"]))

    def handle_endtag(self, tag):
        if tag == "form":
            self.form_action = ""


def parse_csrf(html):
    p = _CsrfParser()
    try:
        p.feed(html or "")
    except Exception:
        return None
    if not p.cands:
        return None
    best = None
    for score, val in p.cands:
        if best is None or score > best[0]:
            best = (score, val)
    return best[1]


def rel(loc):
    if loc.startswith("/"):
        return loc
    u = urlparse(loc)
    if u.scheme:
        return u.path + (("?" + u.query) if u.query else "")
    return "/" + loc


def jget(r):
    try:
        j = r.json()
        return j if isinstance(j, dict) else {}
    except Exception:
        return {}


def err_of(r):
    j = jget(r)
    e = j.get("error")
    if isinstance(e, dict):
        e = e.get("code") or e.get("error") or e.get("type")
    return e


def products_of(body):
    data = body.get("data")
    if isinstance(data, dict):
        if isinstance(data.get("products"), list):
            return data["products"]
        if isinstance(data.get("product"), dict):
            return [data["product"]]
        if "variants" in data:
            return [data]
    if isinstance(body.get("products"), list):
        return body["products"]
    if isinstance(body.get("product"), dict):
        return [body["product"]]
    return []


def first_in_stock(products):
    for p in products:
        if not isinstance(p, dict):
            continue
        for v in p.get("variants") or []:
            if isinstance(v, dict) and v.get("in_stock"):
                return p.get("id"), v.get("id")
    return None


class BenchUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)
    _counter = 0

    def on_start(self):
        BenchUser._counter += 1
        self.idx = BenchUser._counter
        self.username = "bench-%d" % ((self.idx - 1) % 16 + 1)
        self.done = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None

    # ---------- helpers ----------
    def _login(self):
        self.client.cookies.clear()
        form_csrf = None
        with self.client.get("/v2/login-form", name="GET /v2/login-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure("login form status %s" % r.status_code)
                return False
            form_csrf = parse_csrf(r.text)
            if not form_csrf:
                r.failure("csrf input not found")
                return False
            r.success()
        loc = None
        new_csrf = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form_csrf},
            name="POST /v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return False
                r.success()
            elif r.status_code == 200:
                new_csrf = jget(r).get("csrf")
                r.success()
            else:
                r.failure("login status %s" % r.status_code)
                return False
        if loc:
            with self.client.get(rel(loc), name="GET /v2/login-redirect", catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure("login redirect status %s" % r.status_code)
                    return False
                new_csrf = jget(r).get("csrf")
                r.success()
        self.csrf = new_csrf or form_csrf
        return True

    def _recover_cart(self):
        if self.cart_id is None:
            return
        with self.client.post(
            "/v2/carts/%s/recover" % self.cart_id,
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/carts/{id}/recover",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 201, 204):
                c = jget(r).get("csrf")
                if c:
                    self.csrf = c
                if r.headers.get("ETag"):
                    self.etag = r.headers.get("ETag")
                r.success()
            else:
                r.failure("recover status %s" % r.status_code)

    def _recover(self, kind):
        renewed = False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="POST /v2/session/renew",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                c = jget(r).get("csrf")
                if c:
                    self.csrf = c
                renewed = True
                r.success()
            elif kind == "session":
                r.success()  # renew may legitimately fail after revocation
            else:
                r.failure("renew status %s" % r.status_code)
        if not renewed:
            if kind == "session":
                if not self._login():
                    return False
            else:
                return False
        self._recover_cart()
        return True

    def _call(self, method, path, name, body=None, headers=None, ok=(200,), check=None):
        for attempt in range(2):
            h = {}
            if method != "GET":
                h["X-CSRF-Token"] = self.csrf
            if headers:
                h.update(headers() if callable(headers) else headers)
            retry = None
            good = False
            with self.client.request(
                method,
                path,
                json=body,
                headers=h,
                name=name,
                catch_response=True,
                allow_redirects=False,
            ) as r:
                code = r.status_code
                if code == 401:
                    e = err_of(r)
                    if e in ("expired", "session") and attempt == 0:
