            return None if r.headers.get("ETag") else "missing ETag"

        r = self._call("GET", "/v2/carts/%s" % self.cart_id, "GET /v2/carts/{id}", ok=(200,), check=chk)
        if r is None:
            return False
        self.etag = r.headers.get("ETag")
        return True

    def _pick_variant(self):
        r = self._call("GET", "/v2/catalog", "GET /v2/catalog", ok=(200,))
        if r is not None:
            pick = first_in_stock(products_of(jget(r)))
            if pick and pick[0] is not None and pick[1] is not None:
                return pick
        # fallback: traverse pages, at most 3, only via returned next links
        path = "/v2/catalog/page"
        for _ in range(3):
            r = self._call("GET", path, "GET /v2/catalog/page", ok=(200,))
            if r is None:
                return None
            body = jget(r)
            pick = first_in_stock(products_of(body))
            if pick and pick[0] is not None and pick[1] is not None:
                return pick
            nxt = body.get("next")
            if not nxt:
                return None
            path = rel(nxt)
        return None

    # ---------- journey ----------
    def journey(self):
        self.cart_id = None
        self.etag = None
        if not self._login():
            return
        pick = self._pick_variant()
        if not pick:
            return

        def chk_cart(r):
            return None if jget(r).get("id") is not None else "cart id missing"

        r = self._call(
            "POST",
            "/v2/carts",
            "POST /v2/carts",
            body={"product_id": pick[0], "variant_id": pick[1]},
            ok=(201,),
            check=chk_cart,
        )
        if r is None:
            return
        self.cart_id = jget(r)["id"]

        # initial revision
        if not self._read_cart():
            return

        payload = {"quantity": QUANTITY}

        def chk_patch(r):
            j = jget(r)
            if r.status_code != 412 and "quantity" in j and j["quantity"] != QUANTITY:
                return "quantity not preserved"
            return None

        r = self._call(
            "PATCH",
            "/v2/carts/%s" % self.cart_id,
            "PATCH /v2/carts/{id}",
            body=payload,
            headers=lambda: {"If-Match": self.etag},
            ok=(200, 204, 412),
            check=chk_patch,
        )
        if r is None:
            return
        if r.status_code == 412:
            # stale: re-read and retry same payload once
            if not self._read_cart():
                return
            r = self._call(
                "PATCH",
                "/v2/carts/%s" % self.cart_id,
                "PATCH /v2/carts/{id} (retry)",
                body=payload,
                headers=lambda: {"If-Match": self.etag},
                ok=(200, 204),
                check=chk_patch,
            )
            if r is None:
                return

        # current revision for the order
        if not self._read_cart():
            return

        key = "order-%s" % self.cart_id

        def chk_order(r):
            if r.status_code == 412:
                return None
            j = jget(r)
            if j.get("accepted") is not True:
                return "order not accepted"
            return None

        r = self._call(
            "POST",
            "/v2/orders",
            "POST /v2/orders",
            body={"cart_id": self.cart_id},
            headers=lambda: {"Idempotency-Key": key, "If-Match": self.etag},
            ok=(201, 412),
            check=chk_order,
        )
        if r is not None and r.status_code == 412:
            if not self._read_cart():
                return
            self._call(
                "POST",
                "/v2/orders",
                "POST /v2/orders (retry)",
                body={"cart_id": self.cart_id},
                headers=lambda: {"Idempotency-Key": key, "If-Match": self.etag},
                ok=(201,),
                check=chk_order,
            )

    @task
    def run_journey(self):
        try:
            self.journey()
        finally:
            self.done += 1
        if self.done >= ITERATIONS:
            raise StopUser()


class Shape(LoadTestShape):
    seen = False

    def tick(self):
        t = self.get_run_time()
        if t > 240:
            return None
        n = 0
        try:
            n = self.runner.user_count if self.runner else 0
        except Exception:
            n = 0
        if n > 0:
            self.seen = True
        if self.seen and n == 0 and t > 2:
            return None
        return (USERS, USERS)
