import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.util.*;
import java.util.function.*;

public class ModelSimulation extends Simulation {

  private static final String BASE =
      System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  private static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
  private static final String ERR_RE = "\"error\"\\s*:\\s*\"([^\"]*)\"";
  private static final String RECOVERABLE_RE = "\"error\"\\s*:\\s*\"(?:expired|session)\"";

  // ---------- tiny JSON helpers (no external libs) ----------
  private static final class Jp {
    final String s;
    int i = 0;

    Jp(String s) {
      this.s = s;
    }

    void ws() {
      while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
    }

    Object val() {
      ws();
      char c = s.charAt(i);
      if (c == '{') {
        i++;
        Map<String, Object> m = new LinkedHashMap<>();
        ws();
        if (s.charAt(i) == '}') {
          i++;
          return m;
        }
        while (true) {
          ws();
          String k = str();
          ws();
          i++; // colon
          m.put(k, val());
          ws();
          char d = s.charAt(i++);
          if (d == '}') return m;
        }
      }
      if (c == '[') {
        i++;
        List<Object> l = new ArrayList<>();
        ws();
        if (s.charAt(i) == ']') {
          i++;
          return l;
        }
        while (true) {
          l.add(val());
          ws();
          char d = s.charAt(i++);
          if (d == ']') return l;
        }
      }
      if (c == '"') return str();
      if (s.startsWith("true", i)) {
        i += 4;
        return Boolean.TRUE;
      }
      if (s.startsWith("false", i)) {
        i += 5;
        return Boolean.FALSE;
      }
      if (s.startsWith("null", i)) {
        i += 4;
        return null;
      }
      int st = i;
      while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) i++;
      String n = s.substring(st, i);
      if (n.isEmpty()) throw new IllegalStateException("bad json");
      if (n.contains(".") || n.contains("e") || n.contains("E")) return Double.valueOf(n);
      return Long.valueOf(n);
    }

    String str() {
      i++; // opening quote
      StringBuilder b = new StringBuilder();
      while (true) {
        char c = s.charAt(i++);
        if (c == '"') break;
        if (c == '\\') {
          char e = s.charAt(i++);
          switch (e) {
            case 'n': b.append('\n'); break;
            case 't': b.append('\t'); break;
            case 'r': b.append('\r'); break;
            case 'b': b.append('\b'); break;
            case 'f': b.append('\f'); break;
            case 'u':
              b.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
              i += 4;
              break;
            default: b.append(e);
          }
        } else {
          b.append(c);
        }
      }
      return b.toString();
    }
  }

  private static Object parseJson(String body) {
    if (body == null) return null;
    try {
      return new Jp(body).val();
    } catch (Exception e) {
      return null;
    }
  }

  private static Object field(Object o, String k) {
    if (o instanceof Map) return ((Map<?, ?>) o).get(k);
    return null;
  }

  private static String quote(String v) {
    StringBuilder b = new StringBuilder("\"");
    for (char c : v.toCharArray()) {
      if (c == '"' || c == '\\') b.append('\\');
      b.append(c);
    }
    return b.append('"').toString();
  }

  private static String jv(Object o) {
    if (o instanceof Number || o instanceof Boolean) return o.toString();
    return quote(String.valueOf(o));
  }

  private static boolean truthy(Object o) {
    if (o instanceof Boolean) return (Boolean) o;
    if (o instanceof Number) return ((Number) o).doubleValue() != 0;
    return o != null && "true".equalsIgnoreCase(String.valueOf(o));
  }

  private static Session pickVariant(Session s) {
    Object root = parseJson(s.getString("catalogBody"));
    Object prods = field(field(root, "data"), "products");
    if (prods instanceof List) {
      for (Object p : (List<?>) prods) {
        Object vs = field(p, "variants");
        if (!(vs instanceof List)) continue;
        for (Object v : (List<?>) vs) {
          if (truthy(field(v, "in_stock"))) {
            Object pid = field(p, "id");
            Object vid = field(v, "id");
            if (pid != null && vid != null) {
              return s.set("productJson", jv(pid)).set("variantJson", jv(vid));
            }
          }
        }
      }
    }
    return s.markAsFailed();
  }

  private static Session parseCart(Session s) {
    Object root = parseJson(s.getString("createBody"));
    Object id = field(root, "id");
    if (id == null) return s.markAsFailed();
    return s.set("cartId", String.valueOf(id))
        .set("cartJson", jv(id))
        .set("idem", "idem-" + s.getString("user") + "-" + String.valueOf(id));
  }

  // ---------- check helpers ----------
  private static List<CheckBuilder> cl(CheckBuilder... a) {
    return new ArrayList<>(Arrays.asList(a));
  }

  private static CheckBuilder csrfOpt() {
    return regex(CSRF_RE).optional().saveAs("csrf");
  }

  private static CheckBuilder etagOpt() {
    return header("ETag").optional().saveAs("etag");
  }

  private static CheckBuilder[] checksFirst(Supplier<List<CheckBuilder>> okc, boolean h412) {
    List<CheckBuilder> l = new ArrayList<>();
    l.add(status().saveAs("st"));
    l.add(checkIf((r, s) -> r.status().code() == 401).then(regex(ERR_RE).saveAs("err")));
    // 401 denied (or anything other than expired/session) fails this check
    l.add(checkIf((r, s) -> r.status().code() == 401).then(regex(RECOVERABLE_RE).exists()));
    CheckBuilder[] ok = okc.get().toArray(new CheckBuilder[0]);
    l.add(
        checkIf(
                (r, s) -> {
                  int c = r.status().code();
                  return c != 401 && !(h412 && c == 412);
                })
            .then(ok));
    return l.toArray(new CheckBuilder[0]);
  }

  private static CheckBuilder[] checksRetry(Supplier<List<CheckBuilder>> okc, boolean h412) {
    List<CheckBuilder> l = new ArrayList<>();
    l.add(status().saveAs("st"));
    CheckBuilder[] ok = okc.get().toArray(new CheckBuilder[0]);
    l.add(checkIf((r, s) -> !(h412 && r.status().code() == 412)).then(ok));
    return l.toArray(new CheckBuilder[0]);
  }

  private static CheckBuilder[] checksStrict(Supplier<List<CheckBuilder>> okc) {
    return okc.get().toArray(new CheckBuilder[0]);
  }

  // ---------- auth ----------
  private static ChainBuilder loginChain() {
    return exec(s -> s.remove("loginLoc"))
        .exec(
            http("GET login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")))
        .exec(
            http("POST login")
                .post("/v2/login")
                .asJson()
                .body(
                    StringBody(
                        s ->
                            "{\"username\":" + quote(s.getString("user"))
                                + ",\"password\":\"bench\",\"csrf\":"
                                + quote(s.getString("formCsrf")) + "}"))
                .check(
                    status().in(200, 302),
                    header("Location").optional().saveAs("loginLoc"),
                    checkIf((r, s) -> r.status().code() == 200)
                        .then(regex(CSRF_RE).saveAs("csrf"))))
        .doIf(s -> s.contains("loginLoc"))
        .then(
            exec(
                http("GET login redirect")
                    .get(s -> s.getString("loginLoc"))
                    .check(status().is(200), regex(CSRF_RE).saveAs("csrf"))));
  }

  private static ChainBuilder renewChain() {
    return exec(
        http("POST session renew")
            .post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .asJson()
            .body(StringBody("{}"))
            .check(status().in(200, 201, 204), csrfOpt()));
  }

  private static ChainBuilder recoverChain() {
    return exec(
        http("POST cart recover")
            .post("/v2/carts/#{cartId}/recover")
            .header("X-CSRF-Token", "#{csrf}")
            .asJson()
            .body(StringBody("{}"))
            .check(status().in(200, 201, 202, 204), csrfOpt(), etagOpt()));
  }

  private static ChainBuilder recovery() {
    return exec(
            doIfOrElse(s -> "session".equals(s.getString("err")))
                .then(loginChain())
                .orElse(renewChain()))
        .exec(doIf(s -> s.contains("cartId")).then(recoverChain()));
  }

  private static boolean recoverable(String err) {
    return "expired".equals(err) || "session".equals(err);
  }

  // ---------- guarded operation: one bounded recovery, one 412 re-read ----------
  private static ChainBuilder guarded(
      String name,
      Function<String, HttpRequestActionBuilder> req,
      Supplier<List<CheckBuilder>> okc,
      ChainBuilder on412) {
    boolean h412 = on412 != null;
    ChainBuilder c =
        exec(s -> s.set("st", 0).set("err", ""))
            .exec(req.apply(name).check(checksFirst(okc, h412)))
            .doIf(s -> s.getInt("st") == 401 && recoverable(s.getString("err")))
            .then(
                recovery()
                    .exec(
                        req.apply(name + " (after recovery)").check(checksRetry(okc, h412))));
    if (h412) {
      c =
          c.doIf(s -> s.getInt("st") == 412)
              .then(
                  on412.exec(
                      req.apply(name + " (after 412)").check(checksStrict(okc))));
    }
    return c;
  }

  // ---------- requests ----------
  private static HttpRequestActionBuilder getCart(String name) {
    return http(name).get("/v2/carts/#{cartId}");
  }

  private static Supplier<List<CheckBuilder>> getCartOk() {
    return () -> cl(status().is(200), header("ETag").saveAs("etag"), csrfOpt());
  }

  private static ChainBuilder journey() {
    ChainBuilder catalog =
        guarded(
            "GET catalog",
            n -> http(n).get("/v2/catalog"),
            () -> cl(status().is(200), bodyString().saveAs("catalogBody")),
            null);

    ChainBuilder create =
        guarded(
            "POST cart",
            n ->
                http(n)
                    .post("/v2/carts")
                    .header("X-CSRF-Token", "#{csrf}")
                    .asJson()
                    .body(
                        StringBody(
                            s ->
                                "{\"product_id\":" + s.getString("productJson")
                                    + ",\"variant_id\":" + s.getString("variantJson") + "}")),
            () ->
                cl(
                    status().is(201),
                    bodyString().saveAs("createBody"),
                    regex("\"id\"\\s*:\\s*(\"[^\"]+\"|\\d+)").exists(),
                    etagOpt(),
                    csrfOpt()),
            null);

    ChainBuilder readCart = guarded("GET cart", ModelSimulation::getCart, getCartOk(), null);

    ChainBuilder reread =
        guarded("GET cart (reread)", ModelSimulation::getCart, getCartOk(), null);

    ChainBuilder patch =
        guarded(
            "PATCH cart",
            n ->
                http(n)
                    .patch("/v2/carts/#{cartId}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .asJson()
                    .body(StringBody("{\"quantity\":2}")),
            () -> cl(status().in(200, 204), etagOpt(), csrfOpt()),
            reread);

    ChainBuilder reread2 =
        guarded("GET cart (reread for order)", ModelSimulation::getCart, getCartOk(), null);

    ChainBuilder order =
        guarded(
            "POST order",
            n ->
                http(n)
                    .post("/v2/orders")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Idempotency-Key", "#{idem}")
                    .header("If-Match", "#{etag}")
                    .asJson()
                    .body(StringBody(s -> "{\"cart_id\":" + s.getString("cartJson") + "}")),
            () ->
                cl(
                    status().is(201),
                    regex("\"accepted\"\\s*:\\s*true").exists(),
                    csrfOpt()),
            reread2);

    return exec(
            s ->
                s.markAsSucceeded()
                    .removeAll(
                        "cartId", "cartJson", "etag", "idem", "productJson", "variantJson",
                        "catalogBody", "createBody", "csrf", "loginLoc", "st", "err"))
        .exec(flushCookieJar())
        .exec(
            exitBlockOnFail()
                .on(
                    loginChain()
                        .exec(catalog)
                        .exec(ModelSimulation::pickVariant)
                        .exec(create)
                        .exec(ModelSimulation::parseCart)
                        .exec(readCart)
                        .exec(patch)
                        .exec(order)));
  }

  {
    HttpProtocolBuilder proto =
        http.baseUrl(BASE)
            .disableFollowRedirect()
            .disableWarmUp()
            .disableCaching()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

    List<Map<String, Object>> accounts = new ArrayList<>();
    for (int i = 1; i <= 2; i++) {
      Map<String, Object> m = new HashMap<>();
      m.put("user", "bench-" + i);
      accounts.add(m);
    }

    ScenarioBuilder scn =
        scenario("expiry-recovery").feed(listFeeder(accounts).circular()).repeat(2).on(journey());

    setUp(scn.injectOpen(atOnceUsers(2)))
        .protocols(proto)
        .assertions(global().failedRequests().count().is(0L));
  }
}
