function fullUrl(path) {
  if (/^https?:\/\//i.test(path)) {
    if (path.indexOf(BASE) !== 0) throw new Error('refusing off-target url ' + path);
    return path;
  }
  return BASE + (path.charAt(0) === '/' ? '' : '/') + path;
