function findInput(html, name) {
  const src = stripComments(html);
  const tags = src.match(TAG_RE('input')) || [];
  const cands = [];
  for (const t of tags) {
    const a = parseAttrs(t);
    if (a.name === name && a.value !== undefined) cands.push(a);
  }
  cands.sort((x, y) => score(y) - score(x));
  function score(a) {
    let s = 0;
    if ((a.type || 'text').toLowerCase() === 'hidden') s += 2;
    if (a.disabled === undefined) s += 1;
    return s;
  }
  return cands.length ? decodeEntities(cands[0].value) : null;
