function raw(ctx, spec) {
  const headers = { Accept: spec.html ? 'text/html,application/xhtml+xml,*/*' : 'application/json' };
  if (spec.json !== undefined) headers['Content-Type'] = 'application/json';
  if (spec.mutating && ctx.csrf) headers['X-CSRF-Token'] = ctx.csrf;
