// ---------- session handling ----------
function login(ctx) {
  ctx.csrf = null;
  const f = raw(ctx, { name: 'login_form', method: 'GET', path: '/v2/login-form', html: true });
  check(f, { 'login form 200': (r) => r.status === 200 });
  const formCsrf = findInput(f.body, 'csrf');
  check(formCsrf, { 'login form csrf found': (v) => !!v });
  if (!formCsrf) return false;

  let r = raw(ctx, {
    name: 'login', method: 'POST', path: '/v2/login',
    json: { username: ctx.user, password: 'bench', csrf: formCsrf },
  });
  if (r.status >= 300 && r.status < 400) {
    const loc = header(r, 'Location');
    check(loc, { 'login redirect has Location': (v) => !!v });
    if (!loc) return false;
    r = raw(ctx, { name: 'login_redirect', method: 'GET', path: loc });
  }
  const ok = check(r, { 'login succeeded': (x) => x.status >= 200 && x.status < 300 });
  if (!ok) return false;
  absorb(ctx, r);
  check(ctx.csrf, { 'login yielded csrf': (v) => !!v });
