function renew(ctx) {
  const r = raw(ctx, { name: 'renew', method: 'POST', path: '/v2/session/renew', json: {}, mutating: true });
  if (r.status >= 200 && r.status < 300) {
    absorb(ctx, r);
    check(r, { 'renew returned csrf': () => !!ctx.csrf });
    return 'ok';
  }
  if (r.status === 401 && errKind(r) === 'session') return 'revoked';
  check(r, { 'renew succeeded': () => false });
  return 'fail';
}

function recoverCart(ctx) {
  if (!ctx.cartId) return true;
  const spec = { name: 'cart_recover', method: 'POST', path: `/v2/carts/${ctx.cartId}/recover`, json: {}, mutating: true };
  let r = raw(ctx, spec);
  if (r.status === 401 && errKind(r) === 'expired' && ctx.reauths < MAX_REAUTH) {
    ctx.reauths++;
    reauth_count.add(1);
    if (renew(ctx) === 'ok') r = raw(ctx, spec);
  }
  const ok = check(r, { 'cart recovered': (x) => x.status >= 200 && x.status < 300 });
  if (ok) {
    absorb(ctx, r);
    const et = header(r, 'ETag');
    if (et) ctx.etag = et;
