function recoverSession(ctx, kind) {
  let needLogin = kind === 'session';
  if (!needLogin) {
    const rn = renew(ctx);
    if (rn === 'fail') return false;
    if (rn === 'revoked') needLogin = true;
  }
  if (needLogin) {
    if (!login(ctx)) return false;
