    const ra = parseFloat(header(res, 'Retry-After'));
    sleep(isFinite(ra) && ra > 0 ? ra : 1);
    retries429++;
    res = raw(ctx, spec);
  }

  if (res.status === 401) {
    const kind = errKind(res);
    if (kind === 'expired' || kind === 'session') {
      if (ctx.reauths < MAX_REAUTH) {
        ctx.reauths++;
        reauth_count.add(1);
        if (recoverSession(ctx, kind)) {
          res = raw(ctx, spec); // interrupted operation retried exactly once
        }
      } else {
        check(res, { 'reauth bound respected': () => false });
      }
    } else {
      check(res, { 'not denied (401 denied is not expiry)': () => false });
    }
