  if (pick) return pick;

  let next = '/v2/catalog/page';
  for (let page = 0; page < 3 && next && !pick; page++) {
    const pr = call(ctx, { name: 'catalog_page', method: 'GET', path: next });
    if (!check(pr, { 'catalog page 200': (x) => x.status === 200 })) break;
