// ---------- challenge (only reactively, if cart creation demands a grant) ----------
function getGrant(ctx) {
  const f = call(ctx, { name: 'challenge_form', method: 'GET', path: '/v2/challenge-form', html: true });
  if (!check(f, { 'challenge form 200': (x) => x.status === 200 })) return null;
  const html = stripComments(f.body);
  const forms = html.match(TAG_RE('form')) || [];
  let action = null;
  let formStart = -1;
  for (const t of forms) {
    const a = parseAttrs(t);
    if (a.action && /\/v2\/challenges\/[^\/?#\s]+/.test(a.action)) {
      action = decodeEntities(a.action);
      formStart = html.indexOf(t);
      break;
    }
  }
  if (!action) { check(null, { 'challenge action found': () => false }); return null; }
  let section = html.slice(formStart);
  const end = section.search(/<\/form>/i);
  if (end >= 0) section = section.slice(0, end);
  const challenge = findInput(section, 'challenge') || findInput(html, 'challenge');
  if (!challenge) { check(null, { 'challenge value found': () => false }); return null; }

  const p = call(ctx, { name: 'challenge_post', method: 'POST', path: action, json: { challenge }, mutating: true });
  const loc = header(p, 'Location');
  if (!check(p, { 'challenge redirect': (x) => x.status >= 300 && x.status < 400 && !!loc })) return null;
  const g = call(ctx, { name: 'challenge_claim', method: 'GET', path: loc });
  if (!check(g, { 'grant claimed': (x) => x.status === 200 })) return null;
  absorb(ctx, g);
  const gb = j(g);
  return gb && gb.grant_id ? gb.grant_id : null;
