// ---------- cart ----------
function createCart(ctx, pick) {
  const mk = (grant) => {
    const payload = { product_id: pick.product_id, variant_id: pick.variant_id };
    if (grant) payload.grant_id = grant;
    return { name: 'cart_create', method: 'POST', path: '/v2/carts', json: payload, mutating: true };
  };
  let r = call(ctx, mk(null));
  if (r.status !== 201 && [400, 403, 409, 422, 428].indexOf(r.status) >= 0 &&
      /challenge|grant/i.test(String(r.body))) {
    const grant = getGrant(ctx);
    if (grant) r = call(ctx, mk(grant)); // grant passed once
  }
  const ok = check(r, {
    'cart created 201': (x) => x.status === 201,
    'cart has id': (x) => { const b = j(x); return !!(b && b.id); },
  });
  if (!ok) abortJourney('cart creation failed');
  const b = j(r);
  ctx.cartId = b.id;
  absorb(ctx, r);
  const et = header(r, 'ETag');
  if (et) ctx.etag = et;
}

function readCart(ctx) {
  const r = call(ctx, { name: 'cart_get', method: 'GET', path: `/v2/carts/${ctx.cartId}` });
  check(r, { 'cart read 200': (x) => x.status === 200 });
  const et = header(r, 'ETag');
  if (et) ctx.etag = et;
  absorb(ctx, r);
  return r;
}

function patchCart(ctx, quantity) {
  const mk = () => ({
    name: 'cart_patch', method: 'PATCH', path: `/v2/carts/${ctx.cartId}`,
    json: { quantity }, mutating: true,
    headers: (c) => ({ 'If-Match': c.etag || undefined }),
  });
  let r = call(ctx, mk());
  if (r.status === 412) {
    readCart(ctx);
    r = call(ctx, mk()); // same payload, once
  }
  const ok = check(r, { 'cart patched': (x) => x.status >= 200 && x.status < 300 });
  if (!ok) abortJourney('cart patch failed');
  absorb(ctx, r);
  const et = header(r, 'ETag');
  if (et) ctx.etag = et; else readCart(ctx);
}

// ---------- reservation (only reactively, if checkout requires one) ----------
function reserve(ctx) {
  const r = call(ctx, {
    name: 'reservation_create', method: 'POST', path: '/v2/reservations',
    json: { cart_id: ctx.cartId }, mutating: true,
  });
  if (!check(r, { 'reservation accepted 202': (x) => x.status === 202 })) return null;
  absorb(ctx, r);
  const b = j(r);
  if (!b || !b.status_url) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.1);
    const s = call(ctx, { name: 'reservation_status', method: 'GET', path: b.status_url });
    const sb = j(s);
    if (s.status === 200 && sb && sb.status === 'ready') {
      const id = sb.reservation_id || sb.id;
      check(id, { 'reservation ready has id': (v) => !!v });
      return id || null;
    }
    if (sb && sb.status === 'failed') break;
  }
  check(null, { 'reservation became ready': () => false });
  return null;
}

// ---------- order ----------
function placeOrder(ctx) {
  const key = `order-${ctx.cartId}`; // unique per cart, stable across retries
  let reservationId = null;
  const mk = () => ({
    name: 'order_create', method: 'POST', path: '/v2/orders', mutating: true,
    json: reservationId ? { cart_id: ctx.cartId, reservation_id: reservationId } : { cart_id: ctx.cartId },
    headers: (c) => ({ 'Idempotency-Key': key, 'If-Match': c.etag || undefined }),
  });

  let res = call(ctx, mk());
  let reread = false;
  let reserved = false;
  for (let guard = 0; guard < 2; guard++) {
    if (res.status === 201 || res.status === 200) break;
    if (res.status === 412 && !reread) {
      reread = true;
      readCart(ctx);
      res = call(ctx, mk());
      continue;
    }
    if (!reserved && [409, 412, 422, 428].indexOf(res.status) >= 0 && /reserv/i.test(String(res.body))) {
      reserved = true;
      reservationId = reserve(ctx);
      if (!reservationId) break;
      res = call(ctx, mk());
      continue;
    }
    break;
  }

  const ob = j(res);
  const ok = check(res, {
    'order committed 201': (x) => x.status === 201,
    'order accepted true': () => !!(ob && ob.accepted === true),
    'order has id': () => !!(ob && ob.id),
  });
  if (ok) {
    absorb(ctx, res);
    orders_committed.add(1);
  }
  return ok;
}

// ---------- journey ----------
export default function () {
  const n = ((exec.vu.idInTest - 1) % 16) + 1;
  const ctx = { user: `bench-${n}`, csrf: null, etag: null, cartId: null, reauths: 0 };

  if (!login(ctx)) abortJourney('login failed');

  const pick = chooseVariant(ctx);
  if (!pick) abortJourney('no purchasable variant');

  createCart(ctx, pick);
  if (!ctx.etag) readCart(ctx);
  patchCart(ctx, 2);
  placeOrder(ctx);
}
