        ok = False
        if kind == "expired":
            r = self.raw("POST", "/v2/session/renew", "/v2/session/renew",
                         body={}, accept=(200,), expected_401=True)
            if r.status_code == 200:
                self.take(r)
                ok = True
        if not ok:
            self.login()
        if cart_id:
            r = self.raw("POST", "/v2/carts/%s/recover" % cart_id,
                         "/v2/carts/[id]/recover", body={},
                         accept=(200, 201, 202, 204), expected_401=False)
            if r.status_code not in (200, 201, 202, 204):
                return False
            self.take(r)
            self.take_etag(r)
            self.refresh(cart_id)
        return True

    # ------------------------------------------------------------ steps
    def choose(self):
        r = self.call("GET", "/v2/catalog", "/v2/catalog")
        found = pick(products_of(jget(r))) if r.status_code == 200 else None
        if found and found[0] is not None and found[1] is not None:
            return found
        path = "/v2/catalog/page"
        for _ in range(3):
            r = self.call("GET", path, "/v2/catalog/page")
            if r.status_code != 200:
                break
            j = jget(r)
            found = pick(products_of(j))
            if found and found[0] is not None and found[1] is not None:
                return found
            nxt = j.get("next")
            if not nxt:
                break
            path = nxt
        raise Abort()

    def solve_challenge(self):
        r = self.call("GET", "/v2/challenge-form", "/v2/challenge-form",
                      judge=lambda r: None if all(parse_challenge(r.text)) else "challenge form incomplete")
        action, value = parse_challenge(r.text)
        if not action or not value:
            raise Abort()
        pr = self.call("POST", action, "/v2/challenges/[id]",
                       body={"challenge": value}, accept=(200, 302, 303))
        loc = pr.headers.get("Location")
        if not loc:
            raise Abort()
        gr = self.call("GET", loc, "/v2/challenges/[id] [grant]")
        grant = jget(gr).get("grant_id")
        if not grant:
            raise Abort()
        return grant

    def create_cart(self, pid, vid):
        grant = [None]

        def body():
            b = {"product_id": pid, "variant_id": vid}
            if grant[0]:
                b["grant_id"] = grant[0]
            return b

        def needs_challenge(r):
            t = (r.text or "").lower()
            return "challenge" in t or "grant" in t

        def judge(r):
            if r.status_code == 201:
                return None
            if grant[0] is None and needs_challenge(r):
                return None
            return "cart creation failed %s" % r.status_code

        r = self.call("POST", "/v2/carts", "/v2/carts", body=body,
                      accept=(201, 400, 403, 409, 422, 428), judge=judge)
        if r.status_code != 201:
            if grant[0] is None and needs_challenge(r):
                grant[0] = self.solve_challenge()
                r = self.call("POST", "/v2/carts", "/v2/carts", body=body,
                              accept=(201,))
            if r.status_code != 201:
                raise Abort()
        self.take_etag(r)
        cid = jget(r).get("id")
        if cid is None:
            raise Abort()
        return cid

    def reserve(self, cid):
        r = self.call("POST", "/v2/reservations", "/v2/reservations",
                      body={"cart_id": cid}, accept=(202,), cart_id=cid)
        if r.status_code != 202:
            raise Abort()
        su = jget(r).get("status_url")
        if not su:
            raise Abort()
        for _ in range(5):
            time.sleep(0.1)
            pr = self.call("GET", su, "/v2/reservations/[status]", cart_id=cid)
            if pr.status_code != 200:
                raise Abort()
            j = jget(pr)
            st = j.get("status")
            if st == "ready":
                rid = j.get("reservation_id") or j.get("id")
                if rid:
                    return rid
                raise Abort()
            if st == "failed":
                raise Abort()
        raise Abort()

    def do_work(self, cid):
        recovered = False
        retries = 0

        def judge(r):
            if r.status_code == 429:
                return None
            return None if jget(r).get("ok") is True else "work ok not true"

        while True:
            r = self.raw("POST", "/v2/work", "/v2/work", body={},
                         accept=(200, 429), judge=judge,
                         expected_401=not recovered)
            sc = r.status_code
            if sc == 200:
                self.take(r)
                return
            if sc == 429:
                if retries >= 4:
                    return
                retries += 1
                try:
                    ra = float(r.headers.get("Retry-After", "1"))
                except Exception:
                    ra = 1.0
                time.sleep(max(ra, 0.0))
                continue
            if sc == 401:
                k = self.kind(r)
                if recovered or k == "denied":
                    raise Abort()
                if not self.recover(k, cid):
                    raise Abort()
                recovered = True
                continue
            return

    def checkout(self, cid):
        key = "order-%s" % cid
        res = [None]
        for k, v in (self.cart or {}).items():
            if "reserv" in str(k).lower() and "requir" in str(k).lower() and v:
                res[0] = self.reserve(cid)
                break

        def body():
            b = {"cart_id": cid}
            if res[0]:
                b["reservation_id"] = res[0]
            return b

        def extra():
            h = {"Idempotency-Key": key}
            h.update(self.if_match())
            return h

        def need_res(r):
            return res[0] is None and "reservation" in (r.text or "").lower()

        def judge(r):
            sc = r.status_code
            if sc == 201:
                return None if jget(r).get("accepted") is True else "order accepted not true"
            if sc == 200:
                return "business failure: accepted:false"
            if need_res(r):
                return None
            return "order failed %s" % sc

        for _ in range(2):
            r = self.call("POST", "/v2/orders", "/v2/orders", body=body,
                          extra=extra, accept=(200, 201, 400, 409, 422, 428),
                          judge=judge, cart_id=cid, retry412=True)
            if r.status_code == 201 and jget(r).get("accepted") is True:
                return
            if r.status_code in (400, 409, 422, 428) and need_res(r):
                res[0] = self.reserve(cid)
                continue
            raise Abort()
        raise Abort()

    # ------------------------------------------------------------ journey
    def journey(self):
        self.reauth = 0
        self.etag = None
        self.cart = {}
        self.login()
        pid, vid = self.choose()
        cid = self.create_cart(pid, vid)

        r = self.call("GET", "/v2/carts/%s" % cid, "/v2/carts/[id]", cart_id=cid)
        if r.status_code != 200:
            raise Abort()
        self.take_etag(r)
        self.cart = jget(r)

        pr = self.call("PATCH", "/v2/carts/%s" % cid, "/v2/carts/[id] PATCH",
                       body={"quantity": 2}, extra=self.if_match,
                       accept=(200, 204), cart_id=cid, retry412=True)
        if pr.status_code not in (200, 204):
            raise Abort()
        if pr.headers.get("ETag"):
            self.take_etag(pr)
        else:
            self.refresh(cid)

        time.sleep(EXPIRY_PAUSE)
        self.do_work(cid)
        self.checkout(cid)

    @task
    def run_journey(self):
        try:
            self.journey()
        except Exception:
            pass
        self.done += 1
        if self.done >= ITERATIONS:
            raise StopUser()


class ExpiryShape(LoadTestShape):
    seen = False

    def tick(self):
        t = self.get_run_time()
        if t > 240:
            return None
        n = self.runner.user_count if self.runner else 0
        if n > 0:
            self.seen = True
        if self.seen and n == 0 and t > 1:
            return None
        return (USERS, USERS)
