import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  // ---------- tiny JSON helpers (plain Java, no extra libraries) ----------
  static final class Raw {
    final String t;
    Raw(String t) { this.t = t; }
  }

  static final class JP {
    final String s;
    int i = 0;
    JP(String s) { this.s = s; }

    void ws() {
      while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
    }

    String str() {
      StringBuilder sb = new StringBuilder();
      i++; // opening quote
      while (true) {
        char c = s.charAt(i++);
        if (c == '"') break;
        if (c == '\\') {
          char e = s.charAt(i++);
          switch (e) {
            case 'n': sb.append('\n'); break;
            case 't': sb.append('\t'); break;
            case 'r': sb.append('\r'); break;
            case 'b': sb.append('\b'); break;
            case 'f': sb.append('\f'); break;
            case 'u':
              sb.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
              i += 4;
              break;
            default: sb.append(e);
          }
        } else {
          sb.append(c);
        }
      }
      return sb.toString();
    }

    Object val() {
      ws();
      char c = s.charAt(i);
      if (c == '{') {
        i++;
        Map<String, Object> m = new LinkedHashMap<>();
        ws();
        if (s.charAt(i) == '}') { i++; return m; }
        while (true) {
          ws();
          String k = str();
          ws();
          i++; // colon
          m.put(k, val());
          ws();
          char d = s.charAt(i++);
          if (d == '}') return m;
        }
      }
      if (c == '[') {
        i++;
        List<Object> l = new ArrayList<>();
        ws();
        if (s.charAt(i) == ']') { i++; return l; }
        while (true) {
          l.add(val());
          ws();
          char d = s.charAt(i++);
          if (d == ']') return l;
        }
      }
      if (c == '"') return str();
      int st = i;
      while (i < s.length() && ",}] \t\r\n".indexOf(s.charAt(i)) < 0) i++;
      String t = s.substring(st, i);
      if (t.equals("true")) return Boolean.TRUE;
      if (t.equals("false")) return Boolean.FALSE;
      return new Raw(t);
    }
  }

  static String jstr(String v) {
    return "\"" + v.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }

  static String lit(Object o) {
    if (o instanceof String) return jstr((String) o);
    if (o instanceof Raw) return ((Raw) o).t;
    return String.valueOf(o);
  }

  static boolean truthy(Object o) {
    if (o instanceof Boolean) return (Boolean) o;
    if (o instanceof String) return ((String) o).equalsIgnoreCase("true") || o.equals("1");
    if (o instanceof Raw) return ((Raw) o).t.equals("1") || ((Raw) o).t.equals("true");
    return false;
  }

  static String[] pick(String body) {
    try {
      Object root = new JP(body).val();
      Object prods = null;
      if (root instanceof Map) {
        Object d = ((Map<?, ?>) root).get("data");
        if (d instanceof Map) prods = ((Map<?, ?>) d).get("products");
        if (prods == null) prods = ((Map<?, ?>) root).get("products");
      }
      if (prods instanceof List) {
        for (Object p : (List<?>) prods) {
          if (!(p instanceof Map)) continue;
          Map<?, ?> pm = (Map<?, ?>) p;
          Object vs = pm.get("variants");
          if (!(vs instanceof List)) continue;
          for (Object v : (List<?>) vs) {
            if (!(v instanceof Map)) continue;
            Map<?, ?> vm = (Map<?, ?>) v;
            if (truthy(vm.get("in_stock")) && pm.get("id") != null && vm.get("id") != null) {
              return new String[] {lit(pm.get("id")), lit(vm.get("id"))};
            }
          }
        }
      }
    } catch (Exception e) {
      // fall through
    }
    return null;
  }

  // ---------- request / check helpers ----------
  static CheckBuilder csrfSave() {
    return regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf");
  }

  static HttpRequestActionBuilder withCsrf(HttpRequestActionBuilder b) {
    return b.header("X-CSRF-Token", "#{csrf}");
  }

  static HttpRequestActionBuilder decorate(HttpRequestActionBuilder b, List<Integer> codes,
      List<CheckBuilder> extra, boolean first) {
    b = b.check(status().in(codes.toArray(new Integer[0])))
        .check(status().saveAs("lastSt"))
        .check(regex("\"error\"\\s*:\\s*\"(denied)\"").notExists());
    if (first) {
      b = b.check(regex("\"error\"\\s*:\\s*\"(\\w+)\"").optional().saveAs("err"));
    }
    for (CheckBuilder c : extra) b = b.check(c);
    return b;
  }

  static ChainBuilder loginChain() {
    return exec(s -> s.remove("formCsrf").set("loc", ""))
        .exec(http("login form").get("/v2/login-form")
            .check(status().is(200))
            .check(css("input[name=csrf]", "value").saveAs("formCsrf")))
        .doIf(s -> s.contains("formCsrf")).then(
            exec(s -> s.set("csrf", s.getString("formCsrf")))
                .exec(http("login").post("/v2/login").asJson()
                    .body(StringBody(s -> "{\"username\":" + jstr("bench-" + ((int) (s.userId() % 16) + 1))
                        + ",\"password\":\"bench\",\"csrf\":" + jstr(s.getString("formCsrf")) + "}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("loc"))
                    .check(csrfSave()))
                .doIf(s -> !s.getString("loc").isEmpty()).then(
                    exec(http("login redirect").get(s -> s.getString("loc"))
                        .check(status().is(200))
                        .check(csrfSave()))));
  }

  // One operation with bounded (single) recovery for 401 expired / revoked session.
  static ChainBuilder guarded(String name, Supplier<HttpRequestActionBuilder> req, List<Integer> ok,
      Supplier<List<CheckBuilder>> extra) {
    List<Integer> lenient = new ArrayList<>(ok);
    lenient.add(401);
    return exec(s -> s.set("err", "").set("retried", false))
        .exec(decorate(req.get(), lenient, extra.get(), true))
        .doIf(s -> {
          String e = s.getString("err");
          return "expired".equals(e) || "session".equals(e);
        }).then(
            exec(s -> s.set("renewSt", 0))
                .exec(withCsrf(http("session renew").post("/v2/session/renew").asJson().body(StringBody("{}")))
                    .check(status().in(200, 401, 403))
                    .check(status().saveAs("renewSt"))
                    .check(csrfSave()))
                .doIf(s -> s.getInt("renewSt") != 200).then(loginChain())
                .doIf(s -> s.contains("cartId")).then(
                    exec(withCsrf(http("recover cart")
                        .post(s -> "/v2/carts/" + s.getString("cartId") + "/recover")
                        .asJson().body(StringBody("{}")))
                        .check(status().in(200, 201, 202, 204))
                        .check(csrfSave())))
                .pause(Duration.ofMillis(60))
                .exec(s -> s.set("err", "").set("retried", true))
                .exec(decorate(req.get(), ok, extra.get(), false)));
  }

  static HttpRequestActionBuilder orderReq() {
    return withCsrf(http("checkout").post("/v2/orders").asJson()
        .header("Idempotency-Key", s -> s.getString("idem"))
        .header("If-Match", s -> s.contains("etag") ? s.getString("etag") : "*")
        .body(StringBody(s -> "{\"cart_id\":" + s.getString("cartRaw")
            + ",\"reservation_id\":" + s.getString("resRaw") + "}")));
  }

  static List<CheckBuilder> orderChecks() {
    List<CheckBuilder> l = new ArrayList<>();
    l.add(csrfSave());
    l.add(regex("\"accepted\"\\s*:\\s*(false)").notExists());
    return l;
  }

  static final String[] RESET_KEYS = {"formCsrf", "loc", "pidJson", "vidJson", "cartRaw", "cartId", "etag",
      "statusUrl", "resRaw", "rawRes", "pst", "idem", "lastSt", "renewSt", "err", "catBody"};

  static ChainBuilder journey() {
    ChainBuilder start = exec(s -> {
      Session n = s.markAsSucceeded();
      for (String k : RESET_KEYS) n = n.remove(k);
      return n.set("abort", false).set("ready", false).set("jobDone", false).set("pollN", 0)
          .set("retried", false).set("err", "");
    });

    ChainBuilder abortCheck = exec(s -> s.isFailed() ? s.set("abort", true) : s);

    ChainBuilder catalog = exec(http("catalog").get("/v2/catalog")
        .check(status().is(200))
        .check(bodyString().saveAs("catBody")))
        .exec(s -> {
          if (!s.contains("catBody")) return s.set("abort", true);
          String[] p = pick(s.getString("catBody"));
          if (p == null) return s.markAsFailed().set("abort", true);
          return s.set("pidJson", p[0]).set("vidJson", p[1]);
        });

    ChainBuilder cart = guarded("create cart",
        () -> withCsrf(http("create cart").post("/v2/carts").asJson()
            .body(StringBody(s -> "{\"product_id\":" + s.getString("pidJson")
                + ",\"variant_id\":" + s.getString("vidJson") + "}"))),
        List.of(201),
        () -> {
          List<CheckBuilder> l = new ArrayList<>();
          l.add(csrfSave());
          l.add(regex("\"id\"\\s*:\\s*(\"[^\"]*\"|\\d+)").optional().saveAs("cartRaw"));
          l.add(header("ETag").optional().saveAs("etag"));
          return l;
        })
        .exec(s -> {
          if (!s.contains("cartRaw")) return s.markAsFailed().set("abort", true);
          String raw = s.getString("cartRaw");
          String id = raw.startsWith("\"") ? raw.substring(1, raw.length() - 1) : raw;
          return s.set("cartId", id);
        });

    ChainBuilder reserve = guarded("create reservation",
        () -> withCsrf(http("create reservation").post("/v2/reservations").asJson()
            .body(StringBody(s -> "{\"cart_id\":" + s.getString("cartRaw") + "}"))),
        List.of(202),
        () -> {
          List<CheckBuilder> l = new ArrayList<>();
          l.add(csrfSave());
          l.add(regex("\"status_url\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("statusUrl"));
          return l;
        })
        .exec(s -> {
          if (!s.contains("statusUrl")) return s.markAsFailed().set("abort", true);
          return s.set("statusUrl", s.getString("statusUrl").replace("\\/", "/"));
        });

    ChainBuilder poll = asLongAs(s -> !s.getBoolean("jobDone") && s.getInt("pollN") < 5).on(
        pause(Duration.ofMillis(60))
            .exec(s -> s.set("pst", "").set("rawRes", ""))
            .exec(guarded("poll job",
                () -> http("poll job").get(s -> s.getString("statusUrl")),
                List.of(200, 202),
                () -> {
                  List<CheckBuilder> l = new ArrayList<>();
                  l.add(csrfSave());
                  l.add(regex("\"status\"\\s*:\\s*\"(\\w+)\"").optional().saveAs("pst"));
                  l.add(regex("\"reservation_id\"\\s*:\\s*(\"[^\"]*\"|\\d+)").optional().saveAs("rawRes"));
                  l.add(regex("\"status\"\\s*:\\s*\"(failed)\"").notExists());
                  return l;
                }))
            .exec(s -> {
              int n = s.getInt("pollN") + 1 + (s.getBoolean("retried") ? 1 : 0);
              Session r = s.set("pollN", n);
              String pst = s.getString("pst");
              String raw = s.getString("rawRes");
              if ("ready".equals(pst) && raw != null && !raw.isEmpty() && !s.isFailed()) {
                return r.set("ready", true).set("resRaw", raw).set("jobDone", true);
              }
              if ("failed".equals(pst) || s.isFailed()) {
                return r.set("jobDone", true);
              }
              return r;
            }));

    ChainBuilder checkout = exec(s -> s.set("idem", "idem-" + s.userId() + "-" + s.getString("cartId")))
        .exec(guarded("get cart",
            () -> http("get cart").get(s -> "/v2/carts/" + s.getString("cartId")),
            List.of(200),
            () -> {
              List<CheckBuilder> l = new ArrayList<>();
              l.add(csrfSave());
              l.add(header("ETag").optional().saveAs("etag"));
              return l;
            }))
        .exec(guarded("checkout", () -> orderReq(), List.of(201, 412), () -> orderChecks()))
        .doIf(s -> s.contains("lastSt") && s.getInt("lastSt") == 412).then(
            exec(http("get cart").get(s -> "/v2/carts/" + s.getString("cartId"))
                .check(status().is(200))
                .check(csrfSave())
                .check(header("ETag").optional().saveAs("etag")))
                .exec(decorate(orderReq(), List.of(201), orderChecks(), false)));

    return start
        .exec(loginChain())
        .exec(abortCheck)
        .doIf(s -> !s.getBoolean("abort")).then(catalog)
        .doIf(s -> !s.getBoolean("abort")).then(cart)
        .doIf(s -> !s.getBoolean("abort")).then(reserve)
        .doIf(s -> !s.getBoolean("abort")).then(poll)
        .doIf(s -> !s.getBoolean("abort") && s.getBoolean("ready")).then(checkout);
  }

  {
    HttpProtocolBuilder protocol = http.baseUrl(BASE)
        .disableFollowRedirect()
        .acceptHeader("*/*");

    ScenarioBuilder scn = scenario("reservation").repeat(2).on(journey());

    setUp(scn.injectOpen(atOnceUsers(2))).protocols(protocol);
  }
}
