import http from 'k6/http';
import { check, sleep } from 'k6';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const POLL_SLEEP = 0.06; // >= profile poll_interval (0.02) and >= protocol 50ms
const MAX_POLLS = 5;

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
};

http.setResponseCallback(
  http.expectedStatuses({ min: 200, max: 399 }, 401, 412, 429)
);

function jbody(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function abs(loc) {
  if (!loc) return null;
  if (/^https?:\/\//.test(loc)) return loc;
  return BASE + (loc.charAt(0) === '/' ? '' : '/') + loc;
}

function pathOf(url) {
  return url.indexOf(BASE) === 0 ? url.slice(BASE.length) : url;
}

function api(st, method, path, body, o) {
  o = o || {};
  let retries429 = 0;
  let recovered = false;
  for (;;) {
    const headers = {};
    if (body !== undefined) headers['Content-Type'] = 'application/json';
    if (method !== 'GET' && st.csrf) headers['X-CSRF-Token'] = st.csrf;
    if (o.headers) Object.keys(o.headers).forEach((k) => (headers[k] = o.headers[k]));
    const url = abs(path);
    const res = http.request(method, url, body === undefined ? null : JSON.stringify(body), {
      headers: headers,
      redirects: 0,
      tags: { name: o.name || method + ' ' + (o.name ? '' : path.replace(/[0-9a-f-]{6,}/gi, ':id')) },
    });

    if (res.status === 429 && retries429 < 4 && res.headers['Retry-After']) {
      retries429++;
      sleep(Math.max(parseFloat(res.headers['Retry-After']) || 1, 1));
      continue;
    }

    if (res.status === 401 && o.recover !== false && !recovered) {
      const b = jbody(res) || {};
      if (b.error === 'expired') {
        recovered = true;
        if (recoverExpired(st)) continue;
        return res;
      } else if (b.error === 'session') {
        recovered = true;
        if (recoverRevoked(st)) continue;
        return res;
      }
      return res; // denied or unknown: not recoverable
    }

    if (res.status >= 200 && res.status < 300) {
      const b = jbody(res);
      if (b && typeof b.csrf === 'string' && b.csrf) st.csrf = b.csrf;
    }
    return res;
  }
}

function recoverCart(st) {
  if (st.cartId) {
    api(st, 'POST', '/v2/carts/' + st.cartId + '/recover', {}, { recover: false, name: 'POST /v2/carts/:id/recover' });
  }
}

function recoverExpired(st) {
  const r = api(st, 'POST', '/v2/session/renew', {}, { recover: false, name: 'POST /v2/session/renew' });
  if (r.status !== 200) return recoverRevoked(st);
  recoverCart(st);
  return true;
}

function recoverRevoked(st) {
  const r = api(st, 'POST', '/v2/session/renew', {}, { recover: false, name: 'POST /v2/session/renew' });
  if (r.status === 200) {
    recoverCart(st);
    return true;
  }
  if (!login(st)) return false;
  recoverCart(st);
  return true;
}

function extractCsrf(html) {
  try {
    const doc = parseHTML(html);
    const els = doc.find('input[name=csrf]').toArray();
    for (let i = 0; i < els.length; i++) {
      const e = els[i];
      const v = e.attr('value');
      if (v && e.attr('disabled') === undefined) return v;
    }
  } catch (e) {}
  let m = html.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  return m ? m[1] : null;
}

function login(st) {
  const form = api(st, 'GET', '/v2/login-form', undefined, { recover: false, name: 'GET /v2/login-form' });
  const token = extractCsrf(form.body || '');
  const ok1 = check(form, { 'login form ok': (r) => r.status === 200 && !!token });
  if (!ok1) return false;
  st.csrf = token;
  let res = api(st, 'POST', '/v2/login', { username: st.user, password: 'bench', csrf: token }, { recover: false, name: 'POST /v2/login' });
  if (res.status >= 300 && res.status < 400) {
    const loc = abs(res.headers['Location']);
    if (loc) {
      res = api(st, 'GET', loc, undefined, { recover: false, name: 'GET login redirect' });
    }
  }
  const b = jbody(res);
  if (b && b.csrf) st.csrf = b.csrf;
  return check(res, { 'login ok': (r) => r.status === 200 });
}

function findInStock(products) {
  for (let i = 0; i < (products || []).length; i++) {
    const p = products[i];
    const vs = p.variants || [];
    for (let j = 0; j < vs.length; j++) {
      if (vs[j].in_stock) return { product_id: p.id, variant_id: vs[j].id };
    }
  }
  return null;
}

function pickProduct(st) {
  const res = api(st, 'GET', '/v2/catalog', undefined, { name: 'GET /v2/catalog' });
  const b = jbody(res);
  let pick = null;
  if (res.status === 200 && b && b.data) pick = findInStock(b.data.products);
  if (pick) return pick;
  let next = '/v2/catalog/page';
  for (let n = 0; n < 3 && next; n++) {
    const r = api(st, 'GET', next, undefined, { name: 'GET /v2/catalog/page' });
    const pb = jbody(r);
    if (r.status !== 200 || !pb) break;
    const d = pb.data || {};
    let prods = d.products || (d.product ? [d.product] : d.id ? [d] : pb.product ? [pb.product] : []);
    pick = findInStock(prods);
    if (pick) return pick;
    next = pb.next || null;
  }
  return null;
}

function doChallenge(st) {
  const f = api(st, 'GET', '/v2/challenge-form', undefined, { name: 'GET /v2/challenge-form' });
  const html = f.body || '';
  const am = html.match(/\/v2\/challenges\/[^"'\s>?#]+/);
  let challenge = null;
  try {
    const els = parseHTML(html).find('input[name=challenge]').toArray();
    if (els.length) challenge = els[0].attr('value');
  } catch (e) {}
  if (!challenge) {
    const m = html.match(/<input[^>]*name=["']challenge["'][^>]*value=["']([^"']+)["']/i) ||
      html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']challenge["']/i);
    if (m) challenge = m[1];
  }
  if (!am || !challenge) return null;
  const p = api(st, 'POST', am[0], { challenge: challenge }, { name: 'POST /v2/challenges/:id' });
  const loc = abs(p.headers['Location']);
  if (!loc) return null;
  const g = api(st, 'GET', loc, undefined, { name: 'GET challenge claim' });
  const gb = jbody(g);
  return gb && gb.grant_id ? gb.grant_id : null;
}

function createCart(st, pick) {
  const payload = { product_id: pick.product_id, variant_id: pick.variant_id };
  let res = api(st, 'POST', '/v2/carts', payload, { name: 'POST /v2/carts' });
  if (res.status !== 201 && [400, 403, 409, 422, 428].indexOf(res.status) >= 0 &&
      /grant|challenge/i.test(res.body || '')) {
    const grant = doChallenge(st);
    if (grant) {
      payload.grant_id = grant;
      res = api(st, 'POST', '/v2/carts', payload, { name: 'POST /v2/carts' });
    }
  }
  return res;
}

export default function () {
  const st = {
    user: 'bench-' + (((__VU - 1) % 16) + 1),
    csrf: null,
    cartId: null,
  };
  try {
    http.cookieJar().clear(BASE);
  } catch (e) {}

  if (!login(st)) return;

  const pick = pickProduct(st);
  if (!check(pick, { 'in-stock variant found': (p) => !!p })) return;

  const cartRes = createCart(st, pick);
  const cartBody = jbody(cartRes);
  if (!check(cartRes, { 'cart created': (r) => r.status === 201 && !!cartBody && !!cartBody.id })) return;
  st.cartId = cartBody.id;
  let etag = cartRes.headers['Etag'] || cartRes.headers['ETag'] || null;

  // Reserve
  const rr = api(st, 'POST', '/v2/reservations', { cart_id: st.cartId }, { name: 'POST /v2/reservations' });
  const rb = jbody(rr);
  if (!check(rr, { 'reservation accepted (202)': (r) => r.status === 202 && !!rb && !!rb.status_url })) return;
  let statusUrl = abs(rb.status_url);

  // Poll
  let reservationId = null;
  let failed = false;
  for (let polls = 0; polls < MAX_POLLS; polls++) {
    sleep(POLL_SLEEP);
    const pr = api(st, 'GET', statusUrl, undefined, { recover: false, name: 'GET reservation status' });
    if (pr.status === 401) {
      const eb = jbody(pr) || {};
      if (eb.error === 'expired') {
        if (!recoverExpired(st)) break;
        continue;
      } else if (eb.error === 'session') {
        if (!recoverRevoked(st)) break;
        continue;
      }
      break;
    }
    if (pr.status !== 200) break;
    const pb = jbody(pr) || {};
    if (pb.status === 'ready') {
      reservationId = pb.reservation_id || (pb.reservation && pb.reservation.id) || null;
      break;
    }
    if (pb.status === 'failed') {
      failed = true;
      break;
    }
    // pending: continue
  }
  const ready = check(reservationId, {
    'reservation ready': (id) => !!id && !failed,
  });
  if (!ready) return; // never check out pending/failed

  // Refresh ETag for If-Match
  const cg = api(st, 'GET', '/v2/carts/' + st.cartId, undefined, { name: 'GET /v2/carts/:id' });
  if (cg.status === 200) etag = cg.headers['Etag'] || cg.headers['ETag'] || etag;

  const idem = 'k6-' + st.user + '-' + __VU + '-' + __ITER + '-' + st.cartId;
  const orderPayload = { cart_id: st.cartId, reservation_id: reservationId };
  const mkHeaders = () => {
    const h = { 'Idempotency-Key': idem };
    if (etag) h['If-Match'] = etag;
    return h;
  };
  let or = api(st, 'POST', '/v2/orders', orderPayload, { headers: mkHeaders(), name: 'POST /v2/orders' });
  if (or.status === 412) {
    const re = api(st, 'GET', '/v2/carts/' + st.cartId, undefined, { name: 'GET /v2/carts/:id' });
    if (re.status === 200) etag = re.headers['Etag'] || re.headers['ETag'] || etag;
    or = api(st, 'POST', '/v2/orders', orderPayload, { headers: mkHeaders(), name: 'POST /v2/orders' });
  }
  const ob = jbody(or);
  check(or, {
    'order committed': (r) => r.status === 201 && !!ob && ob.accepted === true && !!ob.id,
  });
}
