import os
import re
import time
import html
import itertools

from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2
POLL_SLEEP = 0.06          # >= 50ms protocol minimum and >= profile poll_interval (0.02)
MAX_POLLS = 5

STATE = {"done": 0}
_user_seq = itertools.count(0)

INPUT_RE = re.compile(r"<input\b([^>]*)>", re.I | re.S)
ATTR_RE = re.compile(
    r'([^\s"\'=<>/]+)(?:\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+)))?', re.S)


def parse_inputs(text):
    out = []
    for m in INPUT_RE.finditer(text or ""):
        attrs = {}
        for a in ATTR_RE.finditer(m.group(1)):
            k = a.group(1).lower()
            v = a.group(2) if a.group(2) is not None else (
                a.group(3) if a.group(3) is not None else (a.group(4) or ""))
            attrs[k] = html.unescape(v)
        out.append(attrs)
    return out


def find_input_value(text, name):
    cands = [a for a in parse_inputs(text)
             if a.get("name") == name and "disabled" not in a and a.get("value")]
    if not cands:
        return None
    for a in cands:
        if a.get("type", "").lower() == "hidden":
            return a["value"]
    return cands[0]["value"]


def js(r):
    try:
        d = r.json()
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.idx = next(_user_seq)
        self.username = "bench-%d" % ((self.idx % 16) + 1)
        self.csrf = None
        self.iter_done = 0

    # ---------- generic request helper ----------
    def _err(self, r):
        d = js(r)
        e = d.get("error")
        if isinstance(e, dict):
            e = e.get("code") or e.get("error") or ""
        return str(e or "")

    def _take_csrf(self, r):
        c = js(r).get("csrf")
        if c:
            self.csrf = c

    def call(self, method, path, name=None, body=None, headers=None, ok=(200,),
             redirects=True, cart_id=None, check=None, soft=None, recover=True):
        h = {}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if headers:
            h.update(headers)
        kw = {}
        if body is not None:
            kw["json"] = body
        err = None
        with self.client.request(method, path, name=name or path, headers=h,
                                 allow_redirects=redirects, catch_response=True, **kw) as r:
            if soft and soft(r):
                r.success()
            elif r.status_code == 401:
                err = self._err(r)
                if err in ("expired", "session") and recover:
                    r.success()  # expected expiry
                else:
                    r.failure("401 " + err)
                    err = None
            elif r.status_code in ok:
                msg = check(r) if check else None
                if msg:
                    r.failure(msg)
                else:
                    r.success()
                    self._take_csrf(r)
            else:
                r.failure("HTTP %d" % r.status_code)
        if err in ("expired", "session") and recover:
            self._recover(err, cart_id)
            return self.call(method, path, name=name, body=body, headers=headers, ok=ok,
                             redirects=redirects, cart_id=cart_id, check=check,
                             soft=soft, recover=False)
        return r

    def _renew(self, tolerate):
        soft = (lambda r: r.status_code in (401, 403)) if tolerate else None
        r = self.call("POST", "/v2/session/renew", body={}, ok=(200,), soft=soft, recover=False)
        return r.status_code == 200

    def _recover(self, err, cart_id):
        renewed = self._renew(tolerate=(err == "session"))
        if not renewed:
            self.login()
        if cart_id:
            self.call("POST", "/v2/carts/%s/recover" % cart_id, name="/v2/carts/[id]/recover",
                      body={}, ok=(200, 201, 204), recover=False)

    # ---------- login ----------
    def login(self):
        r = self.call("GET", "/v2/login-form", ok=(200,), recover=False)
        token = find_input_value(r.text, "csrf")
        if not token:
            return False
        self.csrf = None
        r = self.call("POST", "/v2/login",
                      body={"username": self.username, "password": "bench", "csrf": token},
                      headers={"X-CSRF-Token": token}, ok=(200, 302),
                      redirects=False, recover=False)
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if not loc:
                return False
            r = self.call("GET", loc, name="/v2/login [redirect]", ok=(200,), recover=False)
        if r.status_code != 200:
            return False
        if not self.csrf:
            self.csrf = token
        return True

    # ---------- catalog ----------
    @staticmethod
    def _pick(products):
        for p in products or []:
            for v in p.get("variants") or []:
                if v.get("in_stock"):
                    return p.get("id"), v.get("id")
        return None

    def choose_product(self):
        r = self.call("GET", "/v2/catalog", ok=(200,))
        if r.status_code != 200:
            return None
        d = js(r)
        data = d.get("data") or {}
        pick = self._pick(data.get("products"))
        if pick:
            return pick
        # fallback: paged catalog, at most 3 pages
        url = "/v2/catalog/page"
        for _ in range(3):
            r = self.call("GET", url, name="/v2/catalog/page", ok=(200,))
            if r.status_code != 200:
                return None
            d = js(r)
            data = d.get("data") or {}
            prods = data.get("products")
            if not prods:
                p = data.get("product") or (data if data.get("variants") else None)
                prods = [p] if p else []
            pick = self._pick(prods)
            if pick:
                return pick
            url = d.get("next")
            if not url:
                break
        return None

    # ---------- challenge ----------
    def get_grant(self):
        r = self.call("GET", "/v2/challenge-form", ok=(200,))
        if r.status_code != 200:
            return None
        m = re.search(r"/v2/challenges/[^\"'\s>]+", r.text or "")
        val = find_input_value(r.text, "challenge")
        if not m or not val:
            return None
        r = self.call("POST", m.group(0), name="/v2/challenges/[id]",
                      body={"challenge": val}, ok=(302,), redirects=False)
        if r.status_code != 302 or not r.headers.get("Location"):
            return None
        r = self.call("GET", r.headers["Location"], name="/v2/challenges/[claim]", ok=(200,))
        if r.status_code != 200:
            return None
        return js(r).get("grant_id")

    # ---------- journey ----------
    def create_cart(self, pid, vid):
        def needs_challenge(r):
            if r.status_code in (400, 401, 403, 409, 422, 428):
                if r.status_code == 401 and self._err(r) in ("expired", "session", "denied"):
                    return False
                t = (r.text or "").lower()
                return "challenge" in t or "grant" in t
            return False

        r = self.call("POST", "/v2/carts", body={"product_id": pid, "variant_id": vid},
                      ok=(201,), soft=needs_challenge)
        if r.status_code == 201:
            return r
        if needs_challenge(r):
            grant = self.get_grant()
            if not grant:
                return None
            r = self.call("POST", "/v2/carts",
                          body={"product_id": pid, "variant_id": vid, "grant_id": grant},
                          ok=(201,))
            if r.status_code == 201:
                return r
        return None

    def journey(self):
        self.client.cookies.clear()
        self.csrf = None
        if not self.login():
            return
        pick = self.choose_product()
        if not pick or pick[0] is None or pick[1] is None:
            return
        r = self.create_cart(pick[0], pick[1])
        if r is None:
            return
        cart_id = js(r).get("id")
        if cart_id is None:
            return
        cart_name = "/v2/carts/[id]"

        # reservation job
        r = self.call("POST", "/v2/reservations", body={"cart_id": cart_id}, ok=(202,),
                      cart_id=cart_id)
        if r.status_code != 202:
            return
        status_url = js(r).get("status_url") or r.headers.get("Location")
        if not status_url:
            return

        reservation_id = None
        for i in range(MAX_POLLS):
            time.sleep(POLL_SLEEP)
            last = (i == MAX_POLLS - 1)
            holder = {}

            def chk(resp, last=last, holder=holder):
                d = js(resp)
                st = d.get("status")
                holder["status"] = st
                if st == "ready":
                    if d.get("reservation_id") is None:
                        return "ready without reservation_id"
                    holder["rid"] = d.get("reservation_id")
                    return None
                if st == "failed":
                    return "reservation job failed"
                if st == "pending" or st is None:
                    return "reservation still pending after max polls" if last else None
                return "unexpected job status %s" % st

            self.call("GET", status_url, name="/v2/reservations/[status]", ok=(200,),
                      cart_id=cart_id, check=chk)
            st = holder.get("status")
            if st == "ready" and holder.get("rid") is not None:
                reservation_id = holder["rid"]
                break
            if st not in ("pending", None):
                return  # failed / unexpected: never check out
        if reservation_id is None:
            return

        # fresh ETag for the cart
        r = self.call("GET", "/v2/carts/%s" % cart_id, name=cart_name, ok=(200,), cart_id=cart_id)
        if r.status_code != 200:
            return
        etag = r.headers.get("ETag")
        idem = "order-%s-%s" % (cart_id, self.username)

        def order_check(resp):
            if js(resp).get("accepted") is True:
                return None
            return "order not accepted"

        def hdrs():
            h = {"Idempotency-Key": idem}
            if etag:
                h["If-Match"] = etag
            return h

        body = {"cart_id": cart_id, "reservation_id": reservation_id}
        r = self.call("POST", "/v2/orders", body=body, headers=hdrs(), ok=(201,),
                      cart_id=cart_id, check=order_check,
                      soft=lambda x: x.status_code == 412)
        if r.status_code == 412:
            g = self.call("GET", "/v2/carts/%s" % cart_id, name=cart_name, ok=(200,),
                          cart_id=cart_id)
            if g.status_code != 200:
                return
            etag = g.headers.get("ETag") or etag
            self.call("POST", "/v2/orders", body=body, headers=hdrs(), ok=(201,),
                      cart_id=cart_id, check=order_check)

    @task
    def run_journey(self):
        try:
            try:
                self.journey()
            except StopUser:
                raise
            except Exception:
                pass
            self.iter_done += 1
            if self.iter_done >= ITERATIONS:
                STATE["done"] += 1
                raise StopUser()
        finally:
            pass


class Shape(LoadTestShape):
    def tick(self):
        if STATE["done"] >= USERS or self.get_run_time() > 120:
            return None
        return (USERS, USERS)
