import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  static final String ENV_BASE = System.getenv("BASE_URL");
  static final String BASE = (ENV_BASE == null || ENV_BASE.isEmpty()) ? "http://127.0.0.1:8000" : ENV_BASE;

  static final String RECOVER_RE = "\"error\"\\s*:\\s*\"(expired|session)\"";

  HttpProtocolBuilder httpProtocol = http
      .baseUrl(BASE)
      .disableFollowRedirect()
      .acceptHeader("application/json, text/html");

  // ---- login (form -> POST login -> optional single redirect GET) ----
  static ChainBuilder loginFlow() {
    return exec(session -> session.remove("location").remove("form"))
        .exec(
            http("login-form").get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name=csrf]", "value").saveAs("form")))
        .exec(
            http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("location"))
                .check(checkIf((response, session) -> response.status().code() == 200)
                    .then(regex("\"csrf\"\\s*:").exists()))
                .check(jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            doIf(session -> session.contains("location")).then(
                exec(
                    http("login-redirect").get("#{location}")
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.grant_id").optional().saveAs("grant")))));
  }

  // ---- catalog ----
  static ChainBuilder catalogFlow() {
    return exec(
        http("catalog").get("/v2/catalog")
            .check(status().is(200))
            .check(jmesPath("data.products[?variants[0].in_stock == `true`] | [0].id").saveAs("product"))
            .check(jmesPath("data.products[?variants[0].in_stock == `true`] | [0].variants[0].id").saveAs("variant"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf")));
  }

  // ---- cart ----
  static HttpRequestActionBuilder cartReq(String name, boolean first) {
    HttpRequestActionBuilder r = http(name).post("/v2/carts")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(s ->
            "{\"product_id\":\"" + s.getString("product")
                + "\",\"variant_id\":\"" + s.getString("variant") + "\""
                + (s.contains("grant") ? ",\"grant_id\":\"" + s.getString("grant") + "\"" : "")
                + "}"));
    if (first) {
      r = r.check(status().in(201, 401))
          .check(checkIf((response, session) -> response.status().code() == 401)
              .then(regex(RECOVER_RE).exists()))
          .check(regex(RECOVER_RE).optional().saveAs("recErr"));
    } else {
      r = r.check(status().is(201));
    }
    return r
        .check(checkIf((response, session) -> response.status().code() == 201)
            .then(regex("\"id\"\\s*:\\s*\"cart-").exists()))
        .check(checkIf((response, session) -> response.status().code() == 201)
            .then(jsonPath("$.id").saveAs("cart")))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        .check(header("ETag").optional().saveAs("etag"));
  }

  // ---- order ----
  static HttpRequestActionBuilder orderReq(String name, boolean first) {
