// ---------- helpers ----------
function parseJson(res) {
  try {
    if (!res || !res.body) return null;
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  const want = name.toLowerCase();
  const hs = res.headers || {};
  for (const k in hs) {
    if (k.toLowerCase() === want) return hs[k];
  }
  return null;
}

function toPath(loc) {
  let p = String(loc).trim().replace(/^https?:\/\/[^\/]+/i, '');
  if (p.charAt(0) !== '/') p = '/' + p;
  return p;
}

function errorOf(res) {
  const j = parseJson(res);
  if (j && typeof j.error === 'string') return j.error;
  const m = /"error"\s*:\s*"([^"]+)"/.exec(res.body || '');
  return m ? m[1] : null;
}

function extractCsrf(html) {
  if (!html) return null;
  const clean = String(html).replace(/<!--[\s\S]*?-->/g, '');
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  const attrRe = /([^\s=\/>"']+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  const candidates = [];
  for (const tag of tags) {
    const attrs = {};
    const flags = tag.toLowerCase();
    let m;
    attrRe.lastIndex = 0;
    while ((m = attrRe.exec(tag)) !== null) {
      const v = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4];
      attrs[m[1].toLowerCase()] = v;
    }
