ITERATIONS = 2
PASSWORD = "bench"

_user_counter = 0


class Abort(Exception):
    pass


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            self.inputs.append({(k or "").lower(): (v if v is not None else "") for k, v in attrs})


def extract_csrf(html):
    p = _FormParser()
    try:
        p.feed(html or "")
        p.close()
    except Exception:
        pass
    cands = [a for a in p.inputs
             if a.get("name") == "csrf" and a.get("value") and "disabled" not in a]
    hidden = [a for a in cands if a.get("type", "").lower() == "hidden"]
    pick = (hidden or cands)
    return pick[0]["value"] if pick else None


def rel(loc):
    sp = urlsplit(loc)
    if sp.scheme or sp.netloc:
        return sp.path + ("?" + sp.query if sp.query else "")
    return loc


def products_of(data):
    d = data.get("data") if isinstance(data, dict) else None
    if not isinstance(d, dict):
        return []
    if isinstance(d.get("products"), list):
        return d["products"]
    if isinstance(d.get("product"), dict):
        return [d["product"]]
    if "variants" in d:
        return [d]
    return []


def pick_variant(products):
    for p in products:
        vs = p.get("variants") or []
        if vs and vs[0].get("in_stock") is True:
            return p.get("id"), vs[0].get("id")
    for p in products:
        for v in p.get("variants") or []:
            if v.get("in_stock") is True:
                return p.get("id"), v.get("id")
    return None, None


class ShopUser(HttpUser):
    host = HOST
    wait_time = constant(0)

    def on_start(self):
        global _user_counter
        _user_counter += 1
        self.idx = ((_user_counter - 1) % 16) + 1
        self.username = "bench-%d" % self.idx
        self.done = 0
        self._reset()

    def _reset(self):
        self.csrf = None
        self.cart = None
        self.etag = None
        self.grant = None

    # ---------- helpers ----------
    @staticmethod
    def _json(r):
        try:
            d = r.json()
            return d if isinstance(d, dict) else {}
        except Exception:
            return {}

    def _adopt(self, data, r=None):
        if isinstance(data, dict):
            c = data.get("csrf")
            if isinstance(c, str) and c:
                self.csrf = c
        if r is not None:
            et = r.headers.get("ETag")
            if et:
                self.etag = et

    def req(self, method, path, name, body=None, extra=None, auth=True,
            expect=(200,), check=None, max_recover=1):
        attempts = 0
        while True:
            headers = dict(extra or {})
            if auth and method != "GET" and self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            kind = None
            with self.client.request(method, path, name=name, json=body, headers=headers,
                                     allow_redirects=False, catch_response=True) as r:
                data = self._json(r)
                if auth and r.status_code == 401:
                    err = data.get("error")
                    if err in ("expired", "session") and attempts < max_recover:
                        r.success()  # expected expiry, recovered below
                        kind = err
                    else:
                        r.failure("401 error=%s" % err)
                        return False, r, data
                else:
                    ok = r.status_code in expect
                    msg = "unexpected status %s" % r.status_code
                    if ok and check:
                        m = check(r, data)
                        if m:
                            ok, msg = False, m
                    if ok:
                        r.success()
                        self._adopt(data, r)
                    else:
                        r.failure(msg)
                    return ok, r, data
            attempts += 1
            self._recover(kind)

    def _recover(self, kind):
        ok = False
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="/v2/session/renew", catch_response=True) as r:
            d = self._json(r)
            ok = r.status_code == 200
            if ok:
                self._adopt(d, r)
                r.success()
            elif kind == "session":
                r.success()  # renew may legitimately fail when revoked
            else:
                r.failure("renew failed %s" % r.status_code)
