        ok, _, _ = self.req("GET", "/v2/login-form", "/v2/login-form", auth=False, check=chk_form)
        if not ok:
            raise Abort()

        def chk_login(r, d):
            if r.status_code == 200:
                return None if "csrf" in d else "login response lacks csrf"
            if r.status_code == 302:
                return None if r.headers.get("Location") else "302 without Location"
            return None

        ok, r, d = self.req("POST", "/v2/login", "/v2/login", auth=False,
                            body={"username": self.username, "password": PASSWORD,
