        if not self.csrf:
            raise Abort()

    def _catalog(self):
        ok, r, d = self.req("GET", "/v2/catalog", "/v2/catalog")
        if not ok:
            raise Abort()
        pid, vid = pick_variant(products_of(d))
        nxt = d.get("next")
        pages = 0
        while (not pid or not vid) and nxt and pages < 3:
            pages += 1
            ok, r, d = self.req("GET", rel(nxt), "/v2/catalog/page")
            if not ok:
                raise Abort()
            pid, vid = pick_variant(products_of(d))
            nxt = d.get("next")
        if not pid or not vid:
            raise Abort()
        return pid, vid

    def _create_cart(self, pid, vid):
        body = {"product_id": pid, "variant_id": vid}
        if self.grant:
            body["grant_id"] = self.grant
            self.grant = None  # grant is passed once

        def chk(r, d):
            cid = d.get("id")
            return None if isinstance(cid, str) and cid.startswith("cart-") else "cart id missing"

        ok, r, d = self.req("POST", "/v2/carts", "/v2/carts", body=body, expect=(201,), check=chk)
        if not ok:
            raise Abort()
        self.cart = d["id"]

    def _order(self):
        extra = {"Idempotency-Key": self.cart}
        if self.etag:
            extra["If-Match"] = self.etag

        def chk(r, d):
            return None if d.get("accepted") is True else "order not accepted"

        ok, r, d = self.req("POST", "/v2/orders", "/v2/orders", body={"cart_id": self.cart},
                            extra=extra, expect=(201,), check=chk)
        if not ok:
            raise Abort()

    def journey(self):
        self.client.cookies.clear()
        self._reset()
        self._login()
        pid, vid = self._catalog()
        self._create_cart(pid, vid)
        self._order()

    @task
    def run(self):
        try:
            self.journey()
        except Abort:
            pass
        self.done += 1
        if self.done >= ITERATIONS:
            raise StopUser()


class OneShape(LoadTestShape):
    seen = False

    def tick(self):
        t = self.get_run_time()
        if t > 180:
            return None
        uc = self.runner.user_count if self.runner else 0
        if uc > 0:
            self.seen = True
        if self.seen and uc == 0:
            return None
        return (USERS, USERS)
