import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE =
      System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";
  private static final String CSRF = "X-CSRF-Token";
  private static final String PRODUCT_EXPR =
      "data.products[?variants[?in_stock==`true`]] | [0].id";
  private static final String VARIANT_EXPR =
      "data.products[?variants[?in_stock==`true`]] | [0].variants[?in_stock==`true`] | [0].id";

  // ---------- helpers ----------

  private static Session drop(Session s, String... keys) {
    Session t = s;
    for (String k : keys) {
      t = t.remove(k);
    }
    return t;
  }

  private static CheckBuilder csrfOpt() {
    return regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf");
  }

  private static CheckBuilder etagOpt() {
    return header("ETag").optional().saveAs("etag");
  }

  private static boolean needsAuth(Session s) {
    if (!s.contains("authErr")) {
      return false;
    }
    String e = s.getString("authErr");
    return "expired".equals(e) || "session".equals(e);
  }

  private static HttpRequestActionBuilder std(
      HttpRequestActionBuilder r, boolean lenient, int ok, boolean precond) {
    if (lenient) {
      r = r.check(status().saveAs("lastStatus"));
      r = precond ? r.check(status().in(ok, 401, 412)) : r.check(status().in(ok, 401));
    } else {
      r = r.check(status().is(ok));
    }
    return r.check(
        regex("\"error\"\\s*:\\s*\"denied\"").notExists(),
        regex("\"error\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("authErr"));
  }

  // ---------- requests ----------

  private static ChainBuilder loginChain() {
    return exec(s -> drop(s, "form", "location"))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(status().is(200), css("input[name=csrf]", "value").saveAs("form")))
        .exec(
            http("login")
                .post("/v2/login")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{form}\"}"))
                .asJson()
                .check(
                    status().in(200, 302),
                    csrfOpt(),
                    header("Location").optional().saveAs("location")))
        .doIf(s -> s.contains("location"))
        .then(
            exec(
                http("login redirect")
                    .get("#{location}")
                    .check(
                        status().is(200),
                        regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("grant"),
                        csrfOpt())));
  }

  private static HttpRequestActionBuilder catalog(boolean lenient) {
    HttpRequestActionBuilder r = http("catalog").get("/v2/catalog");
    if (lenient) {
      r =
          r.check(
              jmesPath(PRODUCT_EXPR).optional().saveAs("product"),
              jmesPath(VARIANT_EXPR).optional().saveAs("variant"));
    } else {
      r = r.check(jmesPath(PRODUCT_EXPR).saveAs("product"), jmesPath(VARIANT_EXPR).saveAs("variant"));
    }
    return std(r.check(csrfOpt()), lenient, 200, false);
  }

  private static HttpRequestActionBuilder createCart(boolean lenient) {
    HttpRequestActionBuilder r =
        http("create cart")
            .post("/v2/carts")
            .header(CSRF, "#{csrf}")
            .body(
                StringBody(
                    s -> {
                      String b =
                          "{\"product_id\":\""
                              + s.getString("product")
                              + "\",\"variant_id\":\""
                              + s.getString("variant")
                              + "\"";
                      if (s.contains("grant")) {
                        b += ",\"grant_id\":\"" + s.getString("grant") + "\"";
                      }
                      return b + "}";
                    }))
            .asJson();
    if (lenient) {
      r = r.check(jmesPath("id").optional().saveAs("cart"));
    } else {
      r = r.check(jmesPath("id").saveAs("cart"));
    }
    return std(r.check(csrfOpt(), etagOpt()), lenient, 201, false);
  }

  private static HttpRequestActionBuilder patchCart(boolean lenient) {
    HttpRequestActionBuilder r =
        http("update cart quantity")
            .patch("/v2/carts/#{cart}")
            .header(CSRF, "#{csrf}")
            .header("If-Match", "#{etag}")
            .body(StringBody("{\"quantity\":#{quantity}}"))
            .asJson()
            .check(csrfOpt(), etagOpt());
    return std(r, lenient, 200, true);
  }

  private static HttpRequestActionBuilder createOrder(boolean lenient) {
    HttpRequestActionBuilder r =
        http("create order")
            .post("/v2/orders")
            .header(CSRF, "#{csrf}")
            .header("If-Match", "#{etag}")
            .header("Idempotency-Key", "order-#{cart}")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .asJson()
            .check(regex("\"accepted\"\\s*:\\s*false").notExists(), csrfOpt(), etagOpt());
    if (!lenient) {
      r = r.check(regex("\"accepted\"\\s*:\\s*true").exists());
    }
    return std(r, lenient, 201, true);
  }

  // ---------- recovery ----------

  private static ChainBuilder renew(boolean strict) {
    HttpRequestActionBuilder r =
        http("session renew")
            .post("/v2/session/renew")
            .header(CSRF, "#{csrf}")
            .body(StringBody("{}"))
            .asJson()
            .check(status().saveAs("renewStatus"), csrfOpt());
    if (strict) {
      r = r.check(status().in(200, 201, 204));
    }
    return exec(s -> s.remove("renewStatus")).exec(r);
  }

  private static ChainBuilder recoverCart() {
    return exec(
        http("cart recover")
            .post("/v2/carts/#{cart}/recover")
            .header(CSRF, "#{csrf}")
            .body(StringBody("{}"))
            .asJson()
            .check(status().in(200, 201, 202, 204), csrfOpt(), etagOpt()));
  }

  private static ChainBuilder rereadCart() {
    return exec(
        http("cart reread")
            .get("/v2/carts/#{cart}")
            .check(status().is(200), etagOpt(), csrfOpt()));
  }

  private static ChainBuilder authRecovery() {
    return doIfOrElse(s -> "expired".equals(s.getString("authErr")))
        .then(renew(true))
        .orElse(
            renew(false)
                .doIf(s -> s.getInt("renewStatus") / 100 != 2)
                .then(loginChain()))
        .doIf(s -> s.contains("cart"))
        .then(recoverCart());
  }

  private static ChainBuilder guarded(
      Function<Boolean, HttpRequestActionBuilder> req, boolean precond) {
    return exec(s -> drop(s, "lastStatus", "authErr"))
        .exec(req.apply(true))
        .doIf(ModelSimulation::needsAuth)
        .then(
            authRecovery()
                .exec(s -> drop(s, "lastStatus", "authErr"))
                .exec(req.apply(false)))
        .doIf(s -> precond && s.contains("lastStatus") && s.getInt("lastStatus") == 412)
        .then(
            rereadCart()
                .exec(s -> drop(s, "lastStatus", "authErr"))
                .exec(req.apply(false)));
  }

  // ---------- journey ----------

  private static ChainBuilder journey() {
    return exec(
            s -> {
              Session t = drop(s, "csrf", "cart", "etag", "grant", "location", "product",
                  "variant", "form", "lastStatus", "authErr", "renewStatus");
              for (String k : new String[] {"quantity", "delay"}) {
                Object v = s.get(k);
                int n = v instanceof Number ? ((Number) v).intValue()
                    : Integer.parseInt(String.valueOf(v));
                t = t.set(k, n);
              }
              return t;
            })
        .exec(flushCookieJar())
        .doIf(s -> s.getInt("delay") > 0)
        .then(pause(s -> Duration.ofMillis(s.getInt("delay"))))
        .exec(loginChain())
        .exec(guarded(ModelSimulation::catalog, false))
        .exec(guarded(ModelSimulation::createCart, false))
        .exec(guarded(ModelSimulation::patchCart, true))
        .exec(guarded(ModelSimulation::createOrder, true));
  }

  public ModelSimulation() {
    HttpProtocolBuilder protocol = http.baseUrl(BASE).disableFollowRedirect();

    List<Map<String, Object>> rows = new ArrayList<>();
    Iterator<Map<String, Object>> it = jsonFile("/fixtures/accounts.json").get();
    while (it.hasNext()) {
      rows.add(new HashMap<>(it.next()));
    }

    int users = Math.min(2, rows.size());
    List<PopulationBuilder> pops = new ArrayList<>();
    for (int i = 0; i < users; i++) {
      Map<String, Object> row = rows.get(i);
      ScenarioBuilder sc =
          scenario("user-" + (i + 1))
