}

function decodeEntities(s) {
  return String(s)
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function inputsOf(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const out = [];
  const tagRe = /<input\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
  let m;
  while ((m = tagRe.exec(clean)) !== null) {
    const inner = m[1].replace(/\/\s*$/, '');
    const attrs = {};
    const attrRe = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
    let a;
    while ((a = attrRe.exec(inner)) !== null) {
      const key = a[1].toLowerCase();
      let val = a[2] !== undefined ? a[2] : a[3] !== undefined ? a[3] : a[4] !== undefined ? a[4] : '';
      if (!(key in attrs)) attrs[key] = decodeEntities(val);
    }
    out.push(attrs);
  }
  return out;
}

function inputValue(html, name) {
  const c = inputsOf(html).filter(
    (a) => a.name === name && typeof a.value === 'string' && a.value !== '' && !('disabled' in a)
  );
  if (!c.length) return null;
  const hidden = c.filter((a) => (a.type || '').toLowerCase() === 'hidden');
  return (hidden.length ? hidden[0] : c[0]).value;
}

function resolveUrl(loc) {
  if (/^https?:\/\//i.test(loc)) {
    if (loc.indexOf(BASE) !== 0) fail('off-target redirect: ' + loc);
    return loc;
  }
  return BASE + (loc.charAt(0) === '/' ? loc : '/' + loc);
