}

function heal(st, err) {
  let renewed = false;
  if (err === 'expired') {
    const r = http.post(BASE + '/v2/session/renew', '{}', {
      headers: H(st),
      redirects: 0,
      tags: { name: 'POST /v2/session/renew' },
