                return r, j, good
            k = kind[0]
            if k in ("expired", "session"):
                st["auth"] = 1
                self._recover_session(k)
            elif k == "etag":
                st["etag"] = 1
                self._reread()
            elif k == "rate":
                st["rate"] += 1
                try:
                    ra = float(r.headers.get("Retry-After", "1"))
                except Exception:
                    ra = 1.0
                time.sleep(max(ra, 0.0))
            else:
                st["x"] = 1
                if k == "challenge":
                    self._challenge()
                elif k == "reservation":
                    self._reserve()

    # ------------------------------------------------------------ helpers
    def _recover_session(self, kind):
        revoked = kind == "session"
        r, j, good = self._req(
            "POST", "/v2/session/renew", "/v2/session/renew", body={}, ok=(200,),
            tolerate=(lambda c, t, jj: 400 <= c < 500) if revoked else None)
        if not good:
            if not revoked:
                raise Abort()
            self.client.cookies.clear()
            self._login()
        if self.cart:
            r, j, good = self._req(
                "POST", "/v2/carts/%s/recover" % self.cart,
                "/v2/carts/[id]/recover", body={}, ok=(200, 201, 202, 204))
            if not good:
                raise Abort()

    def _reread(self):
        r, j, good = self._op("GET", "/v2/carts/%s" % self.cart, "/v2/carts/[id]", ok=(200,))
        if not good:
            raise Abort()

    def _login(self):
        self.csrf = None
        r, j, good = self._req(
            "GET", "/v2/login-form", "/v2/login-form", ok=(200,),
            validate=lambda rr, jj: None if parse_form(rr.text).csrf else "csrf input not found")
        if not good:
            raise Abort()
        form = parse_form(r.text)
        body = {"username": self.row["username"], "password": self.row["password"],
                "csrf": form.csrf}

        def v(rr, jj):
            if rr.status_code == 302:
                return None if rr.headers.get("Location") else "302 without Location"
            return None if (isinstance(jj.get("csrf"), str) and jj["csrf"]) else "csrf missing"

        r, j, good = self._req("POST", "/v2/login", "/v2/login", body=body,
