                self.grant = jj["grant_id"]
            elif "/v2/challenges/" in (rr.text or ""):
                self._challenge()

    def _challenge(self):
        def v(rr, jj):
            f = parse_form(rr.text)
            return None if (f.action and f.challenge) else "challenge form missing"

        r, j, good = self._op("GET", "/v2/challenge-form", "/v2/challenge-form",
                              ok=(200,), validate=v)
        if not good:
            raise Abort()
        f = parse_form(r.text)
        action = rel(urljoin("/v2/challenge-form", f.action))
        r, j, good = self._op(
            "POST", action, "/v2/challenges/[id]", body={"challenge": f.challenge},
            ok=(302, 303),
            validate=lambda rr, jj: None if rr.headers.get("Location") else "no Location")
        if not good:
            raise Abort()
        loc = rel(urljoin(action, r.headers["Location"]))
        r, j, good = self._op(
            "GET", loc, "/v2/challenge-redirect", ok=(200,),
            validate=lambda rr, jj: None if jj.get("grant_id") else "grant_id missing")
        if not good:
            raise Abort()
        self.grant = j["grant_id"]

    def _reserve(self):
        r, j, good = self._op(
            "POST", "/v2/reservations", "/v2/reservations", body={"cart_id": self.cart},
            ok=(200, 201, 202),
            validate=lambda rr, jj: None if jj.get("status_url") else "status_url missing")
        if not good:
            raise Abort()
        url = rel(urljoin("/v2/reservations", j["status_url"]))
        for _ in range(5):
            time.sleep(0.06)
            r, j, good = self._op("GET", url, "/v2/reservations/[status]", ok=(200, 202))
            if not good:
                raise Abort()
            st = j.get("status")
            if st == "ready":
                rid = j.get("reservation_id") or j.get("id")
                if not rid:
                    raise Abort()
                self.reservation = rid
                return
            if st == "failed":
                raise Abort()
        raise Abort()

    # ------------------------------------------------------------ journey
    def _journey(self):
        self._reset()
        self.client.cookies.clear()
        try:
            d = float(self.row.get("delay", 0) or 0)
        except Exception:
            d = 0.0
        if d > 0:
            time.sleep(d / 1000.0)

        self._login()

        # catalog
        r, j, good = self._op(
            "GET", "/v2/catalog", "/v2/catalog", ok=(200,),
            validate=lambda rr, jj: None if isinstance(jj.get("data"), (dict, list)) else "no catalog data")
        if not good:
            raise Abort()
        found = find_in_stock(j)
        nxt = j.get("next")
        pages = 0
        while not found and nxt and pages < 3:
            r, j, good = self._op("GET", rel(urljoin("/v2/catalog", nxt)),
                                  "/v2/catalog/page", ok=(200,))
            if not good:
                raise Abort()
            found = find_in_stock(j)
            nxt = j.get("next")
            pages += 1
        if not found or found[0] is None or found[1] is None:
            raise Abort()
        pid, vid = found

        # cart (exactly one per journey)
        def cart_body():
            b = {"product_id": pid, "variant_id": vid}
            if self.grant:
                b["grant_id"] = self.grant
            return b

        def xk_cart(code, text, j):
            if code in (400, 403, 409, 422, 428) and not self.grant:
                low = (text or "").lower()
                if "challenge" in low or "grant" in low:
                    return "challenge"
            return None

        r, j, good = self._op(
            "POST", "/v2/carts", "/v2/carts", body=cart_body, ok=(201,),
            validate=lambda rr, jj: None if jj.get("id") else "cart id missing",
            extra_kind=xk_cart)
        if not good:
            raise Abort()
        self.cart = j["id"]
        self.grant = None
        if not self.etag:
            self._reread()

        # quantity update
        qty = self.qty

        def v_patch(rr, jj):
            q = qty_of(jj)
            if q is not None and q != qty:
                return "quantity mismatch %r != %r" % (q, qty)
            return None

        r, j, good = self._op(
            "PATCH", "/v2/carts/%s" % self.cart, "/v2/carts/[id]",
            body={"quantity": qty}, use_etag=True, ok=(200,), validate=v_patch)
        if not good:
            raise Abort()

        # order
        def order_body():
            b = {"cart_id": self.cart}
            if self.reservation:
                b["reservation_id"] = self.reservation
            return b

        def xk_order(code, text, j):
            if code in (400, 402, 409, 422, 428) and not self.reservation:
                if "reservation" in (text or "").lower():
                    return "reservation"
            return None

        self._op(
            "POST", "/v2/orders", "/v2/orders", body=order_body, use_etag=True,
            idem="order-%s" % self.cart, ok=(201,),
            validate=lambda rr, jj: None if jj.get("accepted") is True else "accepted is not true",
            extra_kind=xk_order)

    @task
    def iteration(self):
        self.iters += 1
        try:
            self._journey()
        except StopUser:
            raise
        except Abort:
            pass
        except Exception:
            pass
        if self.iters >= ITERATIONS:
            _DONE[0] += 1
            raise StopUser()


class Shape(LoadTestShape):
    def tick(self):
        if _DONE[0] >= USERS or self.get_run_time() > 300:
            return None
        return (USERS, USERS)
