import http from 'k6/http';
import { check } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

// JMX ConstantThroughputTimer: 121.2/min on the first sampler only = one journey per iteration.
// Execution contract rate is 2/s. The JMX thread group has 4 threads and a 38s duration.
export const options = {
  maxRedirects: 0,
  discardResponseBodies: false,
  scenarios: {
    journey: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
      exec: 'journey',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

const bf = new Rate('business_failure');

let s = { csrf: '', cart: '', etag: '', grant: '' };

function parse(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  const want = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === want) return res.headers[k];
  }
  return '';
}

function relPath(loc) {
  return loc.replace(/^https?:\/\/[^\/]+/i, '');
}

function send(method, path, body, extra, name) {
  const headers = { Accept: 'application/json' };
  let payload = null;
  if (body !== null && body !== undefined) {
    headers['Content-Type'] = 'application/json';
    payload = JSON.stringify(body);
  }
  if (method !== 'GET' && s.csrf) headers['X-CSRF-Token'] = s.csrf;
  if (extra) Object.assign(headers, extra);
  const res = http.request(method, BASE + path, payload, {
    headers,
    redirects: 0,
    tags: { name },
  });
  if (res.status > 0 && res.status < 400) {
    const j = parse(res);
    if (j && typeof j.csrf === 'string' && j.csrf) s.csrf = j.csrf;
    const et = hdr(res, 'ETag');
    if (et) s.etag = et;
  }
  return res;
}

function extractCsrf(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  const attrRe = /([a-zA-Z_:][-\w:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  for (const t of tags) {
    const attrs = {};
    let m;
    attrRe.lastIndex = 0;
    while ((m = attrRe.exec(t)) !== null) {
      attrs[m[1].toLowerCase()] = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4];
    }
    if (attrs.name === 'csrf' && attrs.value && !/\sdisabled\b/i.test(t)) return attrs.value;
  }
  return '';
}

function login() {
  s.csrf = '';
  const user = 'bench-' + (((__VU - 1) % 16) + 1);
  const form = send('GET', '/v2/login-form', null, null, 'login-form');
  const formCsrf = extractCsrf(form.body);
  const okForm = check(form, {
    'login form 200': (r) => r.status === 200,
    'login form csrf': () => !!formCsrf,
  });
  if (!okForm) {
    bf.add(1);
    return false;
  }
  const lr = send('POST', '/v2/login', { username: user, password: 'bench', csrf: formCsrf }, null, 'login');
  let ok = check(lr, { 'login 200/302': (r) => r.status === 200 || r.status === 302 });
  if (!ok) {
    bf.add(1);
    return false;
  }
  if (lr.status === 302) {
    const loc = hdr(lr, 'Location');
    if (!loc) {
      bf.add(1);
      return false;
    }
    const gr = send('GET', relPath(loc), null, null, 'login-redirect');
    const gj = parse(gr);
    ok = check(gr, { 'redirect target 200': (r) => r.status === 200 });
    if (!ok) {
      bf.add(1);
      return false;
    }
    if (gj && gj.grant_id) s.grant = gj.grant_id;
  } else {
    const lj = parse(lr);
    ok = check(lr, { 'login has csrf': () => !!(lj && lj.csrf) });
    if (!ok) {
      bf.add(1);
      return false;
    }
  }
  bf.add(0);
  return true;
}

// Single bounded recovery per operation (expired/session); denied is never recovered.
function authed(method, path, body, hfn, name) {
  let res = send(method, path, body, hfn ? hfn() : null, name);
  if (res.status !== 401) return res;
  const j = parse(res);
  const e = j && j.error;
  if (e !== 'expired' && e !== 'session') return res;
  let renewed = false;
  if (e === 'expired') {
    const r = send('POST', '/v2/session/renew', {}, null, 'renew');
    renewed = r.status >= 200 && r.status < 300;
  }
  if (!renewed) {
    if (!login()) return res;
  }
  if (s.cart) send('POST', '/v2/carts/' + s.cart + '/recover', {}, null, 'recover');
  return send(method, path, body, hfn ? hfn() : null, name);
}

function pickVariant(p) {
  if (!p || !Array.isArray(p.variants)) return null;
  for (const v of p.variants) {
    if (v && v.in_stock === true) return { product: p.id, variant: v.id };
  }
  return null;
}

function selectProduct() {
  const res = authed('GET', '/v2/catalog', null, null, 'catalog');
  if (res.status !== 200) return null;
  const j = parse(res);
  const products = (j && j.data && j.data.products) || [];
  for (const p of products) {
    const c = pickVariant(p);
    if (c) return c;
  }
  // Fallback: bounded paging, at most 3 pages, following only the returned next link.
  let next = '/v2/catalog/page';
  for (let i = 0; i < 3 && next; i++) {
    const pr = authed('GET', relPath(next), null, null, 'catalog-page');
    if (pr.status !== 200) return null;
    const pj = parse(pr);
    if (!pj) return null;
    const d = pj.data || pj;
    const p = d.product || (d.products && d.products[0]) || pj.product || null;
    const c = pickVariant(p);
    if (c) return c;
    next = pj.next || null;
  }
  return null;
}

export function journey() {
  s = { csrf: '', cart: '', etag: '', grant: '' };

  if (!login()) return;

  const pick = selectProduct();
  const okPick = check(pick, { 'in-stock product found': (p) => !!p });
  bf.add(okPick ? 0 : 1);
  if (!okPick) return;

  const cartBody = { product_id: pick.product, variant_id: pick.variant };
  if (s.grant) {
    cartBody.grant_id = s.grant;
    s.grant = ''; // grant is passed once
  }
  const cr = authed('POST', '/v2/carts', cartBody, null, 'cart-create');
  const cj = parse(cr);
  const okCart = check(cr, {
    'cart 201': (r) => r.status === 201,
    'cart id': () => !!(cj && cj.id),
  });
  bf.add(okCart ? 0 : 1);
  if (!okCart) return;
  s.cart = cj.id;

  if (!s.etag) {
    const g = authed('GET', '/v2/carts/' + s.cart, null, null, 'cart-get');
    if (g.status !== 200) {
      bf.add(1);
      return;
    }
  }

  const idem = String(s.cart);
  const orderHeaders = () => {
    const h = { 'Idempotency-Key': idem };
    if (s.etag) h['If-Match'] = s.etag;
    return h;
  };
  let or = authed('POST', '/v2/orders', { cart_id: s.cart }, orderHeaders, 'order');
  if (or.status === 412) {
    // Re-read cart for a fresh ETag and retry the same order once with the same key.
    const g = authed('GET', '/v2/carts/' + s.cart, null, null, 'cart-get');
    if (g.status === 200) {
      or = authed('POST', '/v2/orders', { cart_id: s.cart }, orderHeaders, 'order');
    }
  }
  const oj = parse(or);
  const okOrder = check(or, {
    'order 201': (r) => r.status === 201,
    'order accepted': () => !!(oj && oj.accepted === true),
  });
  bf.add(okOrder ? 0 : 1);
}
