import os
import re
import time
from html import unescape

from locust import HttpUser, LoadTestShape, task, constant

RATE = 2.0        # committed checkout journeys per second (shared by all users)
USERS = 4         # JMX ThreadGroup.num_threads, ramp 0
DURATION = 38     # JMX ThreadGroup.duration (seconds)

INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
ATTR_RE = re.compile(
    r"([^\s=/>\"']+)\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s\"'>]+))", re.S)


def form_csrf(text):
    text = re.sub(r"<!--.*?-->", "", text or "", flags=re.S)
    for tag in INPUT_RE.findall(text):
        if re.search(r"\bdisabled\b", tag, re.I):
            continue
        attrs = {}
        for m in ATTR_RE.finditer(tag):
            val = next(g for g in m.group(2, 3, 4) if g is not None)
            attrs[m.group(1).lower()] = unescape(val)
        if attrs.get("name") == "csrf" and attrs.get("value"):
            return attrs["value"]
    return None


def products_of(d):
    if not isinstance(d, dict):
        return []
    data = d.get("data")
    if isinstance(data, dict):
        if isinstance(data.get("products"), list):
            return data["products"]
        if isinstance(data.get("product"), dict):
            return [data["product"]]
        if "variants" in data:
            return [data]
    if isinstance(d.get("product"), dict):
        return [d["product"]]
    return []


def pick_variant(products):
    for p in products:
        vs = p.get("variants") or []
        if vs and vs[0].get("in_stock"):
            return p.get("id"), vs[0].get("id")
    for p in products:
        for v in (p.get("variants") or []):
            if v.get("in_stock"):
                return p.get("id"), v.get("id")
    return None


class Pacer:
    next_t = None
    counter = 0


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0)

    def on_start(self):
        idx = Pacer.counter
        Pacer.counter += 1
        self.username = "bench-%d" % ((idx % 16) + 1)
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant = None

    # ---------- helpers ----------
    @staticmethod
    def _json(r):
        try:
            d = r.json()
            return d if isinstance(d, dict) else {}
        except Exception:
            return {}

    def _take_csrf(self, d):
        if isinstance(d, dict) and d.get("csrf"):
            self.csrf = d["csrf"]

    def _pace(self):
        # One shared constant-rate schedule: one journey (checkout) per 1/RATE s.
        now = time.monotonic()
        t = Pacer.next_t
        if t is None or t < now:
            t = now
        Pacer.next_t = t + 1.0 / RATE
        if t > now:
            time.sleep(t - now)

    def call(self, method, path, name, body=None, headers=None, expect=(200,),
             check=None, recover=True, on_412=None):
        tried_auth = False
        tried_412 = False
        while True:
            h = dict(headers() if callable(headers) else (headers or {}))
            if method != "GET" and self.csrf:
                h["X-CSRF-Token"] = self.csrf
            action = None
            with self.client.request(method, path, name=name, json=body, headers=h,
                                     allow_redirects=False, catch_response=True) as r:
                data = self._json(r)
                code = r.status_code
                err = data.get("error")
                if code == 401 and recover and not tried_auth and err in ("expired", "session"):
                    r.success()
                    action = err
                elif code == 412 and on_412 is not None and not tried_412:
                    r.success()
                    action = "412"
                else:
                    ok = code in expect
                    if ok and check is not None:
                        try:
                            ok = bool(check(r, data))
                        except Exception:
                            ok = False
                    if ok:
                        r.success()
                    else:
                        r.failure("unexpected status %s" % code)
                    return r, data, ok
            if action == "412":
                tried_412 = True
                on_412()
            else:
                tried_auth = True
                if not self._recover(action):
                    return r, data, False

    def _recover(self, kind):
        if kind == "expired":
            r, d, ok = self.call("POST", "/v2/session/renew", "POST /v2/session/renew",
                                 body={}, recover=False)
            if not ok:
                return False
            self._take_csrf(d)
        else:
            if not self._login():
                return False
        if self.cart_id:
            r, d, ok = self.call("POST", "/v2/carts/%s/recover" % self.cart_id,
                                 "POST /v2/carts/[id]/recover", body={},
                                 expect=(200, 201, 204), recover=False)
            if not ok:
                return False
            self._take_csrf(d)
        return True

    def _login(self):
        self.csrf = None
        r, d, ok = self.call("GET", "/v2/login-form", "GET /v2/login-form",
                             recover=False, check=lambda r, d: bool(form_csrf(r.text)))
        if not ok:
            return False
        form = form_csrf(r.text)
        body = {"username": self.username, "password": "bench", "csrf": form}
        r, d, ok = self.call("POST", "/v2/login", "POST /v2/login", body=body,
                             expect=(200, 302), recover=False,
                             check=lambda r, d: r.status_code == 302 or bool(d.get("csrf")))
        if not ok:
            return False
        self._take_csrf(d)
        if d.get("grant_id"):
            self.grant = d["grant_id"]
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if not loc:
                return False
            r, d, ok = self.call("GET", loc, "GET /v2/login-redirect", recover=False)
            if not ok:
                return False
            self._take_csrf(d)
            if d.get("grant_id"):
                self.grant = d["grant_id"]
        return True

    def _select(self):
        r, d, ok = self.call("GET", "/v2/catalog", "GET /v2/catalog")
        if not ok:
            return None
        pick = pick_variant(products_of(d))
        nxt = d.get("next")
        pages = 0
        while not pick and nxt is None and pages < 0:
            break
        if not pick:
            url = "/v2/catalog/page"
            pages = 0
            while url and pages < 3 and not pick:
                r, d, ok = self.call("GET", url, "GET /v2/catalog/page")
                if not ok:
                    return None
                pick = pick_variant(products_of(d))
                url = d.get("next")
                pages += 1
        return pick

    # ---------- journey ----------
    @task
    def journey(self):
        self._pace()
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant = None

        if not self._login():
            return
        pick = self._select()
        if not pick or not pick[0] or not pick[1]:
            return

        body = {"product_id": pick[0], "variant_id": pick[1]}
        if self.grant:
            body["grant_id"] = self.grant
        r, d, ok = self.call("POST", "/v2/carts", "POST /v2/carts", body=body,
                             expect=(201,), check=lambda r, d: bool(d.get("id")))
        if not ok:
            return
        self.grant = None
        self.cart_id = d["id"]
        self.etag = r.headers.get("ETag")
        self._take_csrf(d)

        cid = self.cart_id

        def hdrs():
            h = {"Idempotency-Key": str(cid)}
            if self.etag:
                h["If-Match"] = self.etag
            return h

        def refresh():
            rr, dd, okk = self.call("GET", "/v2/carts/%s" % cid, "GET /v2/carts/[id]",
                                    recover=False)
            if okk and rr.headers.get("ETag"):
                self.etag = rr.headers["ETag"]

        r, d, ok = self.call("POST", "/v2/orders", "POST /v2/orders",
                             body={"cart_id": cid}, headers=hdrs, expect=(201,),
                             check=lambda r, d: d.get("accepted") is True,
                             on_412=refresh)
        if ok:
            self._take_csrf(d)


class ShopShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() < DURATION:
            return (USERS, USERS)
        return None
