import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.util.*;
import java.util.function.Function;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  // The source JMX defines no transaction controllers and no error-rate limits, so
  // no global assertions are added; the per-request checks below are the only gates.

  static final String BASE =
      System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  static final String ERR = "\"error\"\\s*:\\s*\"(\\w+)\"";
  static final String DENIED = "\"error\"\\s*:\\s*\"denied\"";
  static final String CSRF = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";

  static String v(Session s, String k) {
    Object o = s.get(k);
    return String.valueOf(o);
  }

  // Status guard. The lenient attempt tolerates 401 so that expected expiry is not a failed
  // sample; 401 "denied" still fails.
  static CheckBuilder[] guard(boolean lenient, Integer... ok) {
    List<Integer> allowed = new ArrayList<>(Arrays.asList(ok));
    if (!lenient) {
      return new CheckBuilder[] {status().in(allowed)};
    }
    allowed.add(401);
    return new CheckBuilder[] {
      status().in(allowed),
      status().saveAs("lastStatus"),
      regex(ERR).optional().saveAs("err"),
      regex(DENIED).notExists()
    };
  }

  // Body checks apply only when the response is not an interrupted (401) one.
  static CheckBuilder when(boolean lenient, CheckBuilder c) {
    if (!lenient) {
      return c;
    }
    return checkIf((response, session) -> response.status().code() != 401).then(c);
  }

  static ChainBuilder loginFlow() {
    return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200), css("input[name=csrf]", "value").saveAs("form")))
        .exec(session -> session.remove("location"))
        .exec(
            http("POST /v2/login")
                .post("/v2/login")
                .asJson()
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                .check(
                    status().in(List.of(200, 302)),
                    header("Location").optional().saveAs("location"),
                    checkIf((response, session) -> response.status().code() == 200)
                        .then(regex(CSRF).saveAs("csrf"))))
        .doIf(session -> session.contains("location"))
        .then(
            exec(
                http("GET /v2/login-redirect")
                    .get("#{location}")
                    .check(
                        status().is(200),
                        regex(CSRF).optional().saveAs("csrf"),
                        regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("grant"))));
  }

  static ChainBuilder catalog(boolean lenient) {
    return exec(
        http("GET /v2/catalog")
            .get("/v2/catalog")
            .check(guard(lenient, 200))
            .check(
                when(
                    lenient,
                    jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                        .saveAs("product")))
            .check(
                when(
                    lenient,
                    jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                        .saveAs("variant")))
            .check(when(lenient, regex(CSRF).optional().saveAs("csrf"))));
  }

  static ChainBuilder cart(boolean lenient) {
    return exec(
        http("POST /v2/carts")
            .post("/v2/carts")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(
                StringBody(
                    s -> {
                      String g =
                          s.contains("grant")
                              ? ",\"grant_id\":\"" + v(s, "grant") + "\""
                              : "";
                      return "{\"product_id\":\""
                          + v(s, "product")
                          + "\",\"variant_id\":\""
                          + v(s, "variant")
                          + "\""
                          + g
                          + "}";
                    }))
            .check(guard(lenient, 201))
            .check(when(lenient, regex("\"id\"\\s*:\\s*\"(cart-[^\"]+)\"").saveAs("cart")))
            .check(when(lenient, regex(CSRF).optional().saveAs("csrf")))
            .check(when(lenient, header("ETag").optional().saveAs("etag"))));
  }

  static ChainBuilder order(boolean lenient) {
    return exec(
        http("POST /v2/orders")
            .post("/v2/orders")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .header("Idempotency-Key", "#{cart}")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(guard(lenient, 200, 201))
            .check(when(lenient, regex("\"accepted\"\\s*:\\s*true").exists()))
            .check(when(lenient, regex(CSRF).optional().saveAs("csrf")))
            .check(when(lenient, header("ETag").optional().saveAs("etag"))));
  }

  static ChainBuilder renew(boolean revoked) {
    return exec(
        http("POST /v2/session/renew")
            .post("/v2/session/renew")
            .asJson()
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().in(revoked ? List.of(200, 401) : List.of(200)),
                status().saveAs("renewStatus"),
                regex(CSRF).optional().saveAs("csrf")));
  }

  static ChainBuilder recovery() {
    return exec(session -> session.remove("renewStatus"))
        .doIfOrElse(session -> "session".equals(session.getString("err")))
        .then(renew(true))
        .otherwise(renew(false))
        .doIf(session -> session.contains("renewStatus") && session.getInt("renewStatus") == 401)
        .then(loginFlow())
        .doIf(session -> session.contains("cart"))
        .then(
            exec(
                http("POST /v2/carts/{id}/recover")
                    .post("/v2/carts/#{cart}/recover")
                    .asJson()
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(
                        status().in(List.of(200, 201, 204)),
                        regex(CSRF).optional().saveAs("csrf"),
                        header("ETag").optional().saveAs("etag"))));
  }

  // One lenient attempt; on 401 expired/session, recover once and retry the same operation once.
  static ChainBuilder recoverable(Function<Boolean, ChainBuilder> attempt) {
    return exec(session -> session.removeAll("err", "lastStatus"))
        .exec(attempt.apply(true))
        .doIf(
            session ->
                session.contains("lastStatus")
                    && session.getInt("lastStatus") == 401
                    && session.contains("err")
                    && ("expired".equals(session.getString("err"))
                        || "session".equals(session.getString("err"))))
        .then(exec(recovery()).exec(attempt.apply(false)));
  }

  static ChainBuilder journey() {
    return exec(flushCookieJar())
        .exec(
            session ->
                session
                    .removeAll(
                        "location",
                        "cart",
                        "grant",
                        "err",
                        "lastStatus",
                        "renewStatus",
                        "product",
                        "variant",
                        "form")
                    .set("csrf", "MISSING")
                    .set("etag", "MISSING"))
        .exec(loginFlow())
        .exec(recoverable(ModelSimulation::catalog))
        .doIf(session -> session.contains("product") && session.contains("variant"))
        .then(exec(recoverable(ModelSimulation::cart)))
        .doIf(session -> session.contains("cart"))
        .then(exec(recoverable(ModelSimulation::order)));
  }

  HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE)
          .disableFollowRedirect()
          .disableCaching()
          .acceptHeader("application/json, text/html, */*");

  FeederBuilder<Object> users =
      listFeeder(
              List.of(
                  Map.<String, Object>of("username", "bench-1"),
                  Map.<String, Object>of("username", "bench-2")))
          .queue();

  ScenarioBuilder scn = scenario("m06").feed(users).repeat(2).on(journey());

  {
    setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }
}
