import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 412, 429));

// numerator: unexpected /v2/work failures; denominator: all raw /v2/work business responses
// (including expected expiry). The translated JMX journey issues no /v2/work calls.
export const business_failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    'checks{transaction:login_form}': ['rate==1'],
    'checks{transaction:login}': ['rate==1'],
    'checks{transaction:catalog}': ['rate==1'],
    'checks{transaction:cart_create}': ['rate==1'],
    'checks{transaction:order}': ['rate==1'],
    business_failure: ['rate<0.01'],
  },
};

function parse(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function hdr(res, name) {
  const l = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === l) return res.headers[k];
  }
