import os
import time
from html.parser import HTMLParser
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

USERS = 2
ITERATIONS = 2
TOTAL_JOURNEYS = USERS * ITERATIONS
MAX_RUNTIME = 180

# Exit-code rule: every transaction (stats entry) is evaluated against its own
# request count. The error limit is 0%, matching JMeter's "any assertion/sample
# error is an error". Any entry with failures, an incomplete run, or no samples
# gives exit code 1.
ERROR_LIMIT = 0.0

_state = {"done": 0, "next_user": 0}


class _CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.cands = []
        self.form = ""

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == "form":
            self.form = dict((k.lower(), v or "") for k, v in attrs).get("action", "")
        elif tag == "input":
            a = dict((k.lower(), (v if v is not None else "")) for k, v in attrs)
            if a.get("name", "").strip().lower() == "csrf" and a.get("value"):
                score = 0
                if "disabled" not in a:
                    score += 4
                if a.get("type", "").lower() == "hidden":
                    score += 2
                if "login" in self.form:
                    score += 1
                self.cands.append((score, a["value"]))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.form = ""


def parse_csrf(html):
    p = _CsrfParser()
    try:
        p.feed(html or "")
    except Exception:
        pass
    if not p.cands:
        return None
    best = None
    for i, (s, v) in enumerate(p.cands):
        if best is None or s > best[0]:
            best = (s, v)
    return best[1]


def to_path(location):
    sp = urlsplit(location)
    path = sp.path or "/"
    if sp.query:
        path += "?" + sp.query
    return path


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        _state["next_user"] += 1
        n = _state["next_user"]
        self.username = "bench-%d" % (((n - 1) % 16) + 1)
        self.iter_count = 0
        self._reset()

    def _reset(self):
        self.csrf = None
        self.etag = None
        self.cart = None
        self.grant = None
        self.product = None
        self.variant = None
        self.form_token = None

    # ---------- helpers ----------
    @staticmethod
    def _json(resp):
        try:
            d = resp.json()
            return d if isinstance(d, dict) else {}
        except Exception:
            return {}

    def _absorb(self, resp, data):
        if resp.status_code < 400:
            c = data.get("csrf")
            if isinstance(c, str) and c:
                self.csrf = c
            et = resp.headers.get("ETag")
            if et:
                self.etag = et

    def _api(self, method, path, name, body=None, headers=None, auth=True,
             check=None, recover=True, retry412=False):
        recovered = False
        retried412 = False
        while True:
            hdrs = {}
            if auth and method != "GET" and self.csrf:
                hdrs["X-CSRF-Token"] = self.csrf
            if headers:
                hdrs.update(headers() if callable(headers) else headers)
            action = None
            kwargs = dict(name=name, headers=hdrs, allow_redirects=False,
                          timeout=3, catch_response=True)
