        if not isinstance(products, list):
            return False, "no products list"
        pick = None
        for p in products:
            vs = p.get("variants") or []
            if vs and vs[0].get("in_stock") in (True, "true"):
                pick = (p.get("id"), vs[0].get("id"))
                break
