        finally:
            self.iter_count += 1
            _state["done"] += 1
        if self.iter_count >= ITERATIONS:
            raise StopUser()


class Shape(LoadTestShape):
    def _finalize(self):
        bad = _state["done"] < TOTAL_JOURNEYS
        runner = getattr(self, "runner", None)
        if runner is not None:
            seen = 0
            for entry in runner.stats.entries.values():
                if entry.num_requests <= 0:
                    continue
                seen += entry.num_requests
                if entry.num_failures / float(entry.num_requests) > ERROR_LIMIT:
                    bad = True
            if seen == 0:
                bad = True
            try:
                runner.environment.process_exit_code = 1 if bad else 0
            except Exception:
                pass

    def tick(self):
        if _state["done"] >= TOTAL_JOURNEYS or self.get_run_time() > MAX_RUNTIME:
            self._finalize()
            return None
        return (USERS, USERS)
