const failure = new Rate('business_failure');
export const options = {"scenarios": {"journeys": {"executor": "per-vu-iterations", "vus": 2, "iterations": 2, "maxDuration": "30s"}}, "thresholds": {"checks": ["rate==1"]}};

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';
// Per-VU, per-iteration state. Reset at the start of every journey.
let csrf = '', cart = '', grant = '';

function resetState() { csrf = ''; cart = ''; grant = ''; }
function body(r) { try { return r.json(); } catch (_) { return {}; } }
function hdr(r, name) {
  const n = name.toLowerCase();
  for (const k in r.headers) { if (k.toLowerCase() === n) return r.headers[k]; }
  return '';
}
function url(p) {
  if (!p) return p;
  return /^https?:\/\//i.test(p) ? p : base + p;
}
function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({'Content-Type': 'application/json'}, extra);
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  const r = http.request(method, url(path), data === null ? null : JSON.stringify(data), {
    headers: headers, redirects: 0, timeout: '3s'});
  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([^\s=\/>"']+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  const inner = tag.replace(/^<\s*[a-zA-Z0-9]+/, '');
  let m;
  while ((m = re.exec(inner)) !== null) {
    const v = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : ''));
    attrs[m[1].toLowerCase()] = v;
  }
  return attrs;
}
function inputValue(html, name) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  let fallback;
  for (const t of tags) {
    const a = parseAttrs(t);
    if (a.name !== name || ('disabled' in a) || a.value === undefined) continue;
    if ((a.type || '').toLowerCase() === 'hidden') return a.value;
    if (fallback === undefined) fallback = a.value;
  }
  return fallback;
}
function formAction(html) {
  const forms = String(html || '').match(/<form\b[^>]*>/gi) || [];
  for (const f of forms) {
    const a = parseAttrs(f);
    if (a.action && a.action.indexOf('/v2/challenges/') >= 0) return a.action;
  }
  const m = String(html || '').match(/\/v2\/challenges\/[^"'\s>]+/);
  return m ? m[0] : '';
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = inputValue(r.body, 'csrf');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token});
  if (r.status === 302) {
    r = raw(hdr(r, 'Location')); // follow dynamic Location exactly once
  }
  const ok = check(r, {'login': x => x.status === 200});
  return ok;
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      let renewed = {status: 0};
      if (err === 'expired') renewed = raw('/v2/session/renew', 'POST', {});
