function work(override) {
  if (!csrf) login();
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    sleep((Number(hdr(r, 'Retry-After')) || 1) + .01);
    r = request(path, 'POST', {});
  }
  check(r, {'operation or expected throttle': x => (x.status === 200 && body(x).ok === true) || (cfg.completion && x.status === 429)});
}

function productsOf(b) {
  const d = (b && b.data) || {};
  if (Array.isArray(d.products)) return d.products;
  if (d.product) return [d.product];
  if (b && b.product) return [b.product];
  return [];
}

function flow() {
  resetState();
  if (!login()) return;

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const token = inputValue(r.body, 'challenge');
    const action = formAction(r.body);
    r = request(action, 'POST', {challenge: token});
    r = request(hdr(r, 'Location'));
    grant = body(r).grant_id || '';
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog', product, variant;
  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    product = productsOf(b).find(p => (p.variants || []).some(v => v.in_stock));
    if (product) break;
    page = b.next;
