import re

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'flow'}

_ATTR = re.compile(r'([^\s=/>"\']+)(?:\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+)))?')
_COMMENT = re.compile(r'<!--.*?-->', re.S)
_INPUT = re.compile(r'<input\b([^>]*)>', re.I | re.S)


def input_value(html, wanted):
    """Return value of the first live <input name=wanted value=...> (any attribute order/quoting)."""
    html = _COMMENT.sub('', html or '')
    for match in _INPUT.finditer(html):
        attrs = {}
        for a in _ATTR.finditer(match.group(1)):
            key = a.group(1).lower()
            val = a.group(2) if a.group(2) is not None else (
                a.group(3) if a.group(3) is not None else (a.group(4) or ''))
            attrs[key] = val
        if attrs.get('name') == wanted and attrs.get('value') and 'disabled' not in attrs:
            return attrs['value']
    return None


def extract_products(body):
    data = body.get('data') if isinstance(body, dict) else None
    if isinstance(data, dict):
        if isinstance(data.get('products'), list):
            return data['products']
        if isinstance(data.get('product'), dict):
            return [data['product']]
        if 'variants' in data:
            return [data]
    if isinstance(body, dict) and isinstance(body.get('product'), dict):
        return [body['product']]
    return []


def pick_product(products):
    for item in products:
        for variant in item.get('variants', []) or []:
            if variant.get('in_stock'):
                return item, variant
    return None, None


class MatrixUser(HttpUser):
    wait_time = constant(0)
    counter = 0

    def on_start(self):
        MatrixUser.counter += 1
        number = MatrixUser.counter
        worker = getattr(self, '_p95_worker_id', None)
        if worker:
            try:
                number = int(str(worker).rsplit('-', 1)[1])
            except (IndexError, ValueError):
                pass
        self.username = 'bench-%d' % ((number - 1) % 16 + 1)
        self.password = 'bench'
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=5) as response:
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {}
            except ValueError:
                body = {}
            error = body.get('error')
            clean = path.split('?', 1)[0]
            allowed = (response.status_code < 400
                       or response.status_code == 401 and error in ('expired', 'session')
                       or response.status_code == 412 and error in ('etag', 'etag_conflict')
                       or response.status_code == 429 and clean in ('/v2/work', '/v2/browse'))
            if (clean == '/v2/orders' and method == 'POST' and response.status_code < 400
                    and body.get('accepted') is not True):
                allowed = False
            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')
                self.environment.process_exit_code = 99
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def login(self):
        self.csrf = ''
        form, _ = self.raw('/v2/login-form')
        token = input_value(form.text, 'csrf')
        if not token:
            self.environment.process_exit_code = 99
            return False
        response, body = self.raw('/v2/login', 'POST',
                                  {'username': self.username, 'password': self.password,
                                   'csrf': token})
        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                self.raw(location, name='/v2/login-redirect')
        return response.status_code < 400

    def recover(self):
        renewed, _ = self.raw('/v2/session/renew', 'POST', {})
        if renewed.status_code != 200:
            self.login()
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {},
                                   name='/v2/carts/[id]/recover')
            self.etag = response.headers.get('ETag', self.etag)

    def request(self, path, method='GET', data=None, headers=None, name=None):
        headers = dict(headers or {})
        response, body = self.raw(path, method, data, headers, name)
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            self.recover()
            if 'If-Match' in headers and self.etag:
                headers['If-Match'] = self.etag
            response, body = self.raw(path, method, data, headers, name)
        return response, body

    def reset_state(self):
        self.client.cookies.clear()
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''

    def find_product(self):
        _, body = self.request('/v2/catalog')
        product, variant = pick_product(extract_products(body))
        if product:
            return product, variant
        page = body.get('next') or '/v2/catalog/page'
        for _ in range(3):
            _, body = self.request(page, name='/v2/catalog/page')
            product, variant = pick_product(extract_products(body))
            if product:
                return product, variant
            page = body.get('next')
            if not page:
                break
        return None, None

    def flow(self):
        self.reset_state()
        if not self.login():
            return
        product, variant = self.find_product()
        if not product:
            self.environment.process_exit_code = 99
            return
        payload = {'product_id': product['id'], 'variant_id': variant['id']}
        if self.grant:
            payload['grant_id'] = self.grant
        response, body = self.request('/v2/carts', 'POST', payload)
        self.cart = body.get('id', '') if response.status_code < 400 else ''
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
            return
        order = {'cart_id': self.cart}
        headers = {'Idempotency-Key': 'order-' + self.cart}
        if self.etag:
            headers['If-Match'] = self.etag
        response, _ = self.request('/v2/orders', 'POST', order, headers)
        if response.status_code == 412:
            response, _ = self.request('/v2/carts/' + self.cart, name='/v2/carts/[id]')
            self.etag = response.headers.get('ETag', self.etag)
            headers['If-Match'] = self.etag
            self.request('/v2/orders', 'POST', order, headers)

    @task
    def run_scenario(self):
        self.flow()
        self.cart = ''
        self.etag = ''
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.seen_users = False

    def tick(self):
        users = CFG.get('users', 2)
        if self.get_run_time() > 120:
            return None
        count = self.runner.user_count if self.runner else 0
        if count > 0:
            self.seen_users = True
        if self.seen_users and count == 0:
            return None
        return users, max(1, users)
