    /** Adds status/denial checks. 401 is tolerated on the first attempt only so it can be classified. */
    private static HttpRequestActionBuilder guard(HttpRequestActionBuilder b, boolean first, boolean order) {
        CheckBuilder statusCheck = first
            ? (order ? status().in(201, 401) : status().in(200, 201, 401))
            : (order ? status().is(201) : status().in(200, 201));
        return b.check(statusCheck, status().saveAs("opStatus"),
            regex(ERROR_RE).optional().saveAs("opErr"),
            regex(DENIED_RE).notExists());
    }

    private static boolean recoverable(Session session) {
        if (session.getInt("opStatus") != 401) return false;
        String err = session.getString("opErr");
        return "expired".equals(err) || "session".equals(err);
    }

    private static ChainBuilder recovery() {
        return doIf(session -> "expired".equals(session.getString("opErr"))).then(
                exec(http("renew").post("/v2/session/renew")
                    .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
