                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIfOrElse(session -> session.contains("etag"))
                .then(checkout(true))
                .orElse(checkout(false)));
    }

    public ModelSimulation() {
        setUp(scenario("checkout-threshold").exec(repeat(2).on(flow())).injectOpen(atOnceUsers(2)))
            .assertions(details("checkout").responseTime().percentile3().lt(250))
            .protocols(HTTP);
    }
