  }
  return r;
}

function formToken(r) {
  let t = '';
  try {
    const sel = r.html().find('input[name="csrf"]');
    for (let i = 0; i < sel.size(); i++) {
      const e = sel.eq(i);
      const v = e.attr('value');
      if (v && e.attr('disabled') === undefined) { t = v; break; }
    }
