  if (!t) {
    const s = String(r.body || '');
    let m = s.match(/name=["']csrf["'][^>]*?value=["']([^"']+)["']/i) ||
            s.match(/value=["']([^"']+)["'][^>]*?name=["']csrf["']/i);
