import java.util.List;
import java.util.Map;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String BASE = System.getenv("BASE_URL") == null
        ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE)
        .disableWarmUp().acceptHeader("application/json");

    private static final String CSRF_INPUT =
        "<input(?=[^>]*\\sname\\s*=\\s*[\\\"']csrf[\\\"'])(?=[^>]*\\svalue\\s*=\\s*[\\\"']([^\\\"']+)[\\\"'])[^>]*>";

    private static Map<String, Object> account(String user, String pass, int qty, int delay) {
        Map<String, Object> m = new HashMap<>();
        m.put("acctUser", user);
        m.put("acctPass", pass);
        m.put("acctQty", qty);
        m.put("acctDelay", delay);
        return m;
    }

    private static List<Map<String, Object>> loadAccounts() {
        String[] paths = {"/fixtures/accounts.json", "/fixtures/r10-accounts.json"};
        for (String p : paths) {
            try {
                JsonNode rows = JSON.readTree(Files.readString(Path.of(p)));
                List<Map<String, Object>> out = new ArrayList<>();
                for (JsonNode r : rows) {
                    String u = r.path("username").asText("");
                    if (u.isEmpty()) continue;
                    out.add(account(u, r.path("password").asText("bench"),
                        Math.max(1, Math.min(20, r.path("quantity").asInt(1))),
                        Math.max(0, r.path("delay").asInt(0))));
                }
                if (!out.isEmpty()) return out;
            } catch (IOException | RuntimeException e) {
                // try next location
            }
        }
        List<Map<String, Object>> out = new ArrayList<>();
        out.add(account("bench-1", "bench", 2, 0));
        out.add(account("bench-2", "bench", 3, 500));
        return out;
    }

    private static final List<Map<String, Object>> ACCOUNTS = loadAccounts();

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "").remove("grant").remove("location")
                .remove("product").remove("variant").remove("nextPage").remove("cart").remove("etag")
                .remove("catalogStatus").remove("patchStatus").remove("renewStatus"))
            .exec(http("login form").get("/v2/login-form")
                .check(regex(CSRF_INPUT).saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + session.getString("acctUser")
                    + "\",\"password\":\"" + session.getString("acctPass")
                    + "\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody")).path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static String cartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product")
            + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
        if (session.contains("grant") && !session.getString("grant").isEmpty()) {
            body += ",\"grant_id\":\"" + session.getString("grant") + "\"";
        }
        return body + "}";
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar()).exec(login())
            .exec(http("catalog").get("/v2/catalog").header("X-CSRF-Token", "#{csrf}")
                .check(status().in(200, 401), status().saveAs("catalogStatus"),
                    bodyString().saveAs("catalogBody"), jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("catalogStatus") == 401).then(
                exec(http("renew").post("/v2/session/renew")
                    .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(http("catalog retry").get("/v2/catalog").header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200), bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exec(session -> selectProduct(session))
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> cartBody(session)))
                .check(status().is(201), jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("cart update").patch("/v2/carts/#{cart}")
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"quantity\":" + session.getInt("acctQty") + "}"))
                .check(status().in(200, 412), status().saveAs("patchStatus"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("patchStatus") == 412).then(
                exec(http("etag refresh").get("/v2/carts/#{cart}").header("X-CSRF-Token", "#{csrf}")
                    .check(header("ETag").saveAs("etag"), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(http("cart retry").patch("/v2/carts/#{cart}")
                    .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .body(StringBody(session -> "{\"quantity\":" + session.getInt("acctQty") + "}"))
                    .check(status().is(200), header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exec(doIf(session -> session.getInt("acctDelay") > 0).then(
                pause(session -> Duration.ofMillis(session.getInt("acctDelay")))))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}").header("If-Match", "#{etag}")
                .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                .check(status().is(201), jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        // Each virtual user takes one distinct account row once, then reuses it for all its iterations.
        FeederBuilder<Object> accounts = listFeeder(ACCOUNTS).circular();
        setUp(scenario("matrix")
                .feed(accounts)
                .exec(repeat(2).on(flow()))
                .injectOpen(atOnceUsers(2)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

