```javascript
import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';

const rows = JSON.parse(open('/fixtures/accounts.json'));
const failure = new Rate('business_failure');
const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {checks: ['rate==1']},
};

// Per-VU state (each VU has its own JS globals and its own cookie jar).
let csrf = '';
let cart = '';

function body(r) { try { return r.json(); } catch (_) { return {}; } }

function hdr(r, name) {
  const want = name.toLowerCase();
  for (const k in r.headers) if (k.toLowerCase() === want) return r.headers[k];
  return undefined;
}

function absolute(loc) {
  return /^https?:\/\//.test(loc) ? loc : base + loc;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({'Content-Type': 'application/json'}, extra);
  if (csrf) headers['X-CSRF-Token'] = csrf;
  const url = /^https?:\/\//.test(path) ? path : base + path;
  const r = http.request(method, url, data === null ? null : JSON.stringify(data), {
    headers: headers, redirects: 0, timeout: '5s',
  });
  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function account() {
  // One distinct account per VU
  return rows[(__VU - 1) % rows.length];
}

function pickToken(doc) {
  const cands = doc.find('input[name="csrf"]').toArray();
  let best = '';
  for (const c of cands) {
    const v = c.attr('value');
    if (!v || c.attr('disabled') !== undefined) continue;
    const t = (c.attr('type') || '').toLowerCase();
    if (t === 'hidden') return v;
    if (!best) best = v;
  }
  return best;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = pickToken(r.html());
  const row = account();
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token});
  if (r.status === 302) {
    r = raw(absolute(hdr(r, 'Location')));
  }
  check(r, {'login': x => x.status === 200});
  return r;
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) {
        if (err === 'session' || renewed.status === 401) login();
      }
      if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
      r = raw(path, method, data, extra);
    }
  }
  return r;
}

function flow() {
  csrf = ''; cart = '';
  login();

  // Staggered per-account delay, taken after login so sessions overlap.
  const row = account();
  if (row.delay) sleep(row.delay / 1000);

  let page = '/v2/catalog', product = null;
  for (let n = 0; n < 3 && page && !product; n++) {
    const b = body(request(page));
    const products = (b.data && b.data.products) || [];
    product = products.find(p => (p.variants || []).some(v => v.in_stock)) || null;
    if (!product) page = b.next || null;
  }
  if (!product) { check(false, {'eligible product': x => x}); return; }
  const variant = product.variants.find(v => v.in_stock);

  let r = request('/v2/carts', 'POST', {product_id: product.id, variant_id: variant.id});
  check(r, {'cart': x => x.status === 201});
  cart = body(r).id;
  if (!cart) return;
  let etag = hdr(r, 'ETag');

  const key = 'order-' + __VU + '-' + __ITER + '-' + cart;
  const orderPayload = {cart_id: cart};
  const mk = () => {
    const h = {'Idempotency-Key': key};
    if (etag) h['If-Match'] = etag;
    return h;
  };
  r = request('/v2/orders', 'POST', orderPayload, mk());
  if (r.status === 412) {
    const g = request('/v2/carts/' + cart);
    etag = hdr(g, 'ETag') || etag;
    r = request('/v2/orders', 'POST', orderPayload, mk());
  }
  check(r, {'accepted': x => x.status === 201 && body(x).accepted === true});
}

export default function () {
  flow();
}
