import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"workload\": true, \"operation\": \"journey\", \"path\": \"/v2/orders\", \"rate\": 1, \"max_vus\": 4}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final double RATE = CFG.path("rate").asDouble(1);
    private static final String BASE = System.getenv("BASE_URL") == null
        ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");
    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE)
        .disableWarmUp().acceptHeader("application/json");

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static boolean is(Session session, String key, int value) {
        return session.contains(key) && session.getInt(key) == value;
    }

    private static boolean needsRecovery(Session session) {
        return is(session, "orderStatus", 401) && session.contains("err")
            && ("expired".equals(session.getString("err")) || "session".equals(session.getString("err")));
    }

    private static ChainBuilder login() {
        return exec(http("login form").get("/v2/login-form")
                .check(regex("<input(?=[^>]*\\bname=[\\\"']csrf[\\\"'])(?=[^>]*\\bvalue=[\\\"']([^\\\"']+)[\\\"'])[^>]*>")
                    .saveAs("formCsrf")))
            .exec(session -> session.remove("location").remove("grant"))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session) + "\",\"password\":\"bench\",\"csrf\":\""
                    + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody")).path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static HttpRequestActionBuilder orderRequest(String name, boolean ifMatch, boolean allow401) {
        HttpRequestActionBuilder request = http(name).post("/v2/orders")
            .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}");
        if (ifMatch) request = request.header("If-Match", "#{etag}");
        return request
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(allow401 ? status().in(201, 401) : status().is(201),
                status().saveAs("orderStatus"),
