                regex("\"error\"\\s*:\\s*\"denied\"").notExists(),
                regex("\"accepted\"\\s*:\\s*false").notExists(),
                jsonPath("$.csrf").optional().saveAs("csrf"));
    }

    private static ChainBuilder order(String name, boolean allow401) {
        return doIfOrElse(session -> session.contains("etag")).then(
            exec(orderRequest(name, true, allow401)))
            .orElse(exec(orderRequest(name, false, allow401)));
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(session -> session.set("csrf", "").remove("grant").remove("location")
                .remove("product").remove("variant").remove("cart").remove("etag")
                .remove("orderStatus").remove("err").remove("catalogStatus"))
