import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null
      ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  HttpProtocolBuilder protocol = http
      .baseUrl(BASE)
      .disableFollowRedirect()
      .acceptHeader("application/json, text/html, */*");

  static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";

  static ChainBuilder updateToken = exec(session -> {
    String t = session.contains("csrfNew") ? session.getString("csrfNew") : session.getString("csrf");
    return session.set("tok", t);
  });

  static ChainBuilder workCall = exec(
      http("work")
          .post("/v2/work")
          .header("X-CSRF-Token", "#{tok}")
          .header("Content-Type", "application/json")
          .body(StringBody("{}"))
          .check(status().in(200, 401, 429).saveAs("ws"))
          .check(regex("\"error\"\\s*:\\s*\"([a-z]+)\"").optional().saveAs("werr"))
  );

  static ChainBuilder journey =
      exec(session -> session.set("user", "bench-" + (1 + (int) (session.userId() % 16))))
      .exec(
          http("login_form")
              .get("/v2/login-form")
              .check(status().is(200))
              .check(css("input[name=csrf]", "value").saveAs("csrf"))
      )
      .exec(
          http("login")
              .post("/v2/login")
              .header("Content-Type", "application/json")
              .body(StringBody("{\"username\":\"#{user}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
              .check(status().in(200, 302).saveAs("ls"))
              .check(header("Location").optional().saveAs("loc"))
              .check(regex(CSRF_RE).optional().saveAs("csrfNew"))
      )
      .doIf(session -> session.getInt("ls") == 302 && session.contains("loc")).then(
          exec(
              http("login_redirect")
                  .get("#{loc}")
                  .check(status().is(200))
                  .check(regex(CSRF_RE).optional().saveAs("csrfNew"))
          )
      )
      .exec(updateToken)
      .exec(session -> session.remove("werr"))
      .exec(workCall)
      // scheduled 429: honor Retry-After of 1s, at most 4 retries
      .repeat(4).on(
          doIf(session -> session.contains("ws") && session.getInt("ws") == 429).then(
              pause(Duration.ofSeconds(1))
              .exec(session -> session.remove("ws"))
              .exec(workCall)
          )
      )
      // expired session: renew once and retry once
      .doIf(session -> session.contains("ws") && session.getInt("ws") == 401
          && "expired".equals(session.getString("werr"))).then(
          exec(session -> session.remove("csrfNew"))
          .exec(
              http("renew")
                  .post("/v2/session/renew")
                  .header("X-CSRF-Token", "#{tok}")
                  .header("Content-Type", "application/json")
                  .body(StringBody("{}"))
                  .check(status().is(200))
                  .check(regex(CSRF_RE).optional().saveAs("csrfNew"))
          )
          .exec(updateToken)
          .exec(session -> session.remove("ws").remove("werr"))
          .exec(workCall)
      )
      // denied / revoked 401 is a real failure
      .exec(session -> {
        if (session.contains("ws") && session.getInt("ws") == 401) {
          return session.markAsFailed();
        }
        return session;
      });

  ScenarioBuilder scn = scenario("work").exec(journey);

  {
    setUp(
        scn.injectOpen(
            constantUsersPerSec(5).during(Duration.ofSeconds(38))
        )
    ).protocols(protocol).maxDuration(Duration.ofSeconds(55));
  }
}
