import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const business_failure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: 8,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

// Per-VU state (each VU has its own cookie jar).
let session = { csrf: null, loggedIn: false };

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  const inner = tag.replace(/^<\s*input/i, '').replace(/\/?>$/, '');
  let m;
  while ((m = re.exec(inner)) !== null) {
    const k = m[1].toLowerCase();
    const v = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4] !== undefined ? m[4] : '';
    if (!(k in attrs)) attrs[k] = v;
  }
  return attrs;
}

function extractCsrf(html) {
  if (!html) return null;
  const clean = html.replace(/<!--[\s\S]*?-->/g, '');
  const tags = clean.match(/<\s*input\b[^>]*>/gi) || [];
  let fallback = null;
  for (const t of tags) {
    const a = parseAttrs(t);
    if (a.name === 'csrf' && a.value !== undefined && a.value !== '') {
      if ('disabled' in a) {
        if (!fallback) fallback = a.value;
        continue;
      }
      return a.value;
    }
  }
  return fallback;
}

function jsonOf(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function absUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  return BASE + '/' + loc;
}

function login() {
  session.loggedIn = false;
  session.csrf = null;
  const n = ((__VU - 1) % 16) + 1;
  const username = 'bench-' + n;

  const form = http.get(BASE + '/v2/login-form', { tags: { name: 'login_form' } });
  const formCsrf = extractCsrf(form.body);
  if (form.status !== 200 || !formCsrf) return false;

  let res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );

  let csrf = null;
  if (res.status >= 300 && res.status < 400) {
    const loc = absUrl(res.headers['Location'] || res.headers['location']);
    if (loc) {
      const r2 = http.get(loc, { redirects: 0, tags: { name: 'login_redirect' } });
      if (r2.status >= 400) return false;
      const j2 = jsonOf(r2);
      if (j2 && j2.csrf) csrf = j2.csrf;
    }
  } else if (res.status >= 400) {
    return false;
  }
  const j = jsonOf(res);
  if (j && j.csrf) csrf = j.csrf;
  if (!csrf && session.csrf) csrf = session.csrf;
  if (!csrf) return false;
  session.csrf = csrf;
  session.loggedIn = true;
  return true;
}

function renew() {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf || '' },
    tags: { name: 'renew' },
  });
  if (res.status >= 400) return false;
  const j = jsonOf(res);
  if (j && j.csrf) session.csrf = j.csrf;
  return true;
}

function errorOf(res) {
  const j = jsonOf(res);
  if (j) {
    if (typeof j.error === 'string') return j.error;
    if (j.error && typeof j.error === 'object') return j.error.code || j.error.error || '';
  }
  return '';
}

export default function () {
  if (!session.loggedIn) {
    if (!login()) {
      check(null, { 'login succeeded': () => false });
      return;
    }
  }

  let recovered = false;
  let retries429 = 0;

  while (true) {
    const res = http.post(BASE + '/v2/work', '{}', {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf || '' },
      tags: { name: 'work' },
    });

    if (res.status === 200) {
      const j = jsonOf(res);
      const ok = !!(j && j.ok === true);
      if (j && j.csrf) session.csrf = j.csrf;
      check(res, { 'work ok': () => ok });
      business_failure.add(!ok);
      return;
    }

    if (res.status === 429 && retries429 < 4) {
      business_failure.add(false);
      retries429++;
      const ra = parseFloat(res.headers['Retry-After'] || res.headers['retry-after'] || '1');
      sleep(isNaN(ra) || ra <= 0 ? 1 : ra);
      continue;
    }

    if (res.status === 401) {
      const err = errorOf(res);
      if (err === 'expired' && !recovered) {
        business_failure.add(false);
        recovered = true;
        if (renew()) continue;
        if (login()) continue;
        return;
      }
      if (err === 'session' && !recovered) {
        business_failure.add(false);
        recovered = true;
        if (!renew()) {
          if (!login()) return;
        }
        continue;
      }
      check(res, { 'work not denied': () => false });
      business_failure.add(true);
      return;
    }

    check(res, { 'work status ok': () => false });
    business_failure.add(true);
    return;
  }
}
