import os
import re
import time
import itertools

import gevent
from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser  # noqa: F401  (imported per contract; not used)

TARGET_RATE = 5.0
N_USERS = 10                    # each user issues 1 request / 2s -> 5/s total
PERIOD = N_USERS / TARGET_RATE  # 2.0 s per user
STAGGER = PERIOD / N_USERS      # 0.2 s between users
SCORE_END = 35.0                # T0 + 5 warmup + 30 scored

_ATTR_RE = re.compile(r'([A-Za-z_:][\w:.-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))')
_INPUT_RE = re.compile(r'<input\b([^>]*)>', re.I | re.S)
_COMMENT_RE = re.compile(r'<!--.*?-->', re.S)


def find_csrf(html):
    html = _COMMENT_RE.sub("", html or "")
    fallback = None
    for m in _INPUT_RE.finditer(html):
        attrs = {}
        for a in _ATTR_RE.finditer(m.group(1)):
            val = a.group(2) if a.group(2) is not None else (
                a.group(3) if a.group(3) is not None else a.group(4))
            attrs[a.group(1).lower()] = val
        if attrs.get("name") == "csrf" and attrs.get("value"):
            if attrs.get("type", "hidden").lower() == "hidden":
                return attrs["value"]
            if fallback is None:
                fallback = attrs["value"]
    return fallback


def safe_json(resp):
    try:
        j = resp.json()
        return j if isinstance(j, dict) else {}
    except Exception:
        return {}


def err_kind(resp):
    j = safe_json(resp)
    e = j.get("error")
    if isinstance(e, dict):
        e = e.get("code") or e.get("error") or e.get("message")
    text = str(e or "")
    if not text:
        text = resp.text or ""
    text = text.lower()
    if "expired" in text:
        return "expired"
    if "denied" in text:
        return "denied"
    if "session" in text:
        return "session"
    return "other"


class WorkUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    _counter = itertools.count(0)
    start_at = None   # shared schedule origin
    t0 = None         # time of first work POST

    def on_start(self):
        self.idx = next(WorkUser._counter)
        self.username = "bench-%d" % (self.idx % 16 + 1)
        self.csrf = None
        if WorkUser.start_at is None:
            WorkUser.start_at = time.time() + 3.0
        self.next_at = WorkUser.start_at + (self.idx % N_USERS) * STAGGER
        self.login()

    def wait_time(self):
        return max(0.0, self.next_at - time.time())

    # ---------- auth ----------
    def login(self):
        for _ in range(2):
            if self._login_once():
                return True
        return False

    def _login_once(self):
        self.csrf = None
        form_csrf = None
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True) as r:
            if r.status_code != 200:
                r.failure("login form status %s" % r.status_code)
                return False
            form_csrf = find_csrf(r.text)
            if not form_csrf:
                r.failure("csrf not found")
                return False
            r.success()
        token = form_csrf
        with self.client.post("/v2/login",
                              json={"username": self.username, "password": "bench",
                                    "csrf": form_csrf},
                              name="/v2/login", allow_redirects=False,
                              catch_response=True) as r:
            if r.status_code in (301, 302, 303, 307, 308):
                loc = r.headers.get("Location")
                j = safe_json(r)
                if j.get("csrf"):
                    token = j["csrf"]
                r.success()
                if loc:
                    with self.client.get(loc, name="/v2/login-redirect",
                                         allow_redirects=False,
                                         catch_response=True) as r2:
                        if r2.status_code < 400:
                            j2 = safe_json(r2)
                            if j2.get("csrf"):
                                token = j2["csrf"]
                            r2.success()
                        else:
                            r2.failure("login redirect status %s" % r2.status_code)
                            return False
            elif r.status_code == 200:
                j = safe_json(r)
                if j.get("csrf"):
                    token = j["csrf"]
                r.success()
            else:
                r.failure("login status %s" % r.status_code)
                return False
        self.csrf = token
        return True

    def renew(self):
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": self.csrf or ""},
                              name="/v2/session/renew", catch_response=True) as r:
            if r.status_code < 400:
                j = safe_json(r)
                if j.get("csrf"):
                    self.csrf = j["csrf"]
                r.success()
                return True
            r.success()  # expected possible failure for revoked sessions
            return False

    def relogin(self):
        try:
            self.client.cookies.clear()
        except Exception:
            pass
        return self.login()

    # ---------- work ----------
    def post_work(self):
        retries429 = 0
        recovered = False
        while True:
            outcome = "done"
            retry_after = 1.0
            with self.client.post("/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf or ""},
                                  name="/v2/work", catch_response=True) as r:
                code = r.status_code
                if code == 200:
                    j = safe_json(r)
                    if j.get("ok") is True:
                        r.success()
                    else:
                        r.failure("ok not true")
                    if j.get("csrf"):
                        self.csrf = j["csrf"]
                elif code == 429:
                    r.success()
                    outcome = "r429"
                    try:
                        retry_after = float(r.headers.get("Retry-After", "1"))
                    except Exception:
                        retry_after = 1.0
                elif code == 401:
                    kind = err_kind(r)
                    if kind == "expired" and not recovered:
                        r.success()
                        outcome = "expired"
                    elif kind == "session" and not recovered:
                        r.success()
                        outcome = "session"
                    else:
                        r.failure("401 %s" % kind)
                elif code < 400:
                    r.success()
                else:
                    r.failure("status %s" % code)

            if outcome == "r429":
                if retries429 >= 4:
                    return
                retries429 += 1
                gevent.sleep(max(retry_after, 1.0))
                continue
            if outcome == "expired":
                recovered = True
                if not self.renew():
                    if not self.relogin():
                        return
                continue
            if outcome == "session":
                recovered = True
                if not self.relogin():
                    return
                continue
            return

    @task
    def work(self):
        now = time.time()
        if WorkUser.t0 is not None and self.next_at >= WorkUser.t0 + SCORE_END:
            # window finished for this user; stay idle until shape ends
            self.next_at = now + 0.5
            return
        if not self.csrf:
            if not self.login():
                self.next_at = time.time() + 1.0
                return
        if WorkUser.t0 is None:
            WorkUser.t0 = time.time()
        self.post_work()
        self.next_at += PERIOD
        if self.next_at < time.time() - 0.5:
            self.next_at = time.time()


class Shape(LoadTestShape):
    def tick(self):
        rt = self.get_run_time()
        if rt > 60:
            return None
        t0 = WorkUser.t0
        if t0 is not None and time.time() >= t0 + SCORE_END + 0.5:
            return None
        return (N_USERS, N_USERS)
