public class ModelSimulation extends Simulation {

  static final String BASE = System.getenv("BASE_URL") != null
      ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  HttpProtocolBuilder protocol = http
      .baseUrl(BASE)
      .disableFollowRedirect()
      .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8");

