import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const business_failure = new Rate('business_failure');

export const options = {
  discardResponseBodies: false,
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 10,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
    checks: ['rate>0.99'],
  },
};

const JSON_HEADERS = { 'Content-Type': 'application/json' };

// Per-VU state (each VU has its own cookie jar)
let csrf = null;
let loggedIn = false;

function username() {
  return 'bench-' + (((__VU - 1) % 16) + 1);
}

function absUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  return BASE + (loc.charAt(0) === '/' ? '' : '/') + loc;
}

function safeJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractCsrf(html) {
  if (!html) return null;
  try {
    const doc = parseHTML(html);
    const inputs = doc.find('input[name=csrf]');
    let fallback = null;
    for (let i = 0; i < inputs.size(); i++) {
      const el = inputs.eq(i);
      const v = el.attr('value');
      if (!v) continue;
      const disabled = el.attr('disabled');
      if (disabled !== undefined && disabled !== null) continue;
      const type = (el.attr('type') || 'hidden').toLowerCase();
      if (type === 'hidden') return v;
      if (!fallback) fallback = v;
    }
    if (fallback) return fallback;
  } catch (e) {
    // fall through to regex
  }
  let m = html.match(/<input[^>]*name\s*=\s*["']?csrf["']?[^>]*value\s*=\s*["']([^"']+)["']/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*value\s*=\s*["']([^"']+)["'][^>]*name\s*=\s*["']?csrf["']?/i);
  return m ? m[1] : null;
}

function login() {
  csrf = null;
  loggedIn = false;
  const form = http.get(BASE + '/v2/login-form', { tags: { name: 'login-form' } });
  const token = extractCsrf(form.body);
  const res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username(), password: 'bench', csrf: token }),
    { headers: JSON_HEADERS, redirects: 0, tags: { name: 'login' } }
  );
  let body = null;
  if (res.status >= 300 && res.status < 400) {
    const loc = absUrl(res.headers['Location'] || res.headers['location']);
    if (loc) {
      const r2 = http.get(loc, { redirects: 0, tags: { name: 'login-redirect' } });
      body = safeJson(r2);
    }
  } else if (res.status === 200) {
    body = safeJson(res);
  }
  if (body && body.csrf) {
    csrf = body.csrf;
    loggedIn = true;
  } else if (res.status >= 300 && res.status < 400) {
    // session cookie set; csrf may be missing from redirect target
    loggedIn = true;
  }
  return loggedIn;
}

function renew() {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: Object.assign({ 'X-CSRF-Token': csrf || '' }, JSON_HEADERS),
    tags: { name: 'renew' },
  });
  if (res.status === 200) {
    const b = safeJson(res);
    if (b && b.csrf) csrf = b.csrf;
    return true;
  }
  return false;
}

function errorCode(res) {
  const j = safeJson(res);
  if (j && j.error !== undefined && j.error !== null) {
    if (typeof j.error === 'string') return j.error;
    if (j.error.code) return j.error.code;
  }
  const b = res.body || '';
  if (b.indexOf('expired') !== -1) return 'expired';
  if (b.indexOf('denied') !== -1) return 'denied';
  if (b.indexOf('session') !== -1) return 'session';
  return '';
}

function doWork() {
  let retries429 = 0;
  let renewed = false;
  let relogged = false;

  for (let guard = 0; guard < 10; guard++) {
    const res = http.post(BASE + '/v2/work', '{}', {
      headers: Object.assign({ 'X-CSRF-Token': csrf || '' }, JSON_HEADERS),
      tags: { name: 'POST /v2/work' },
    });

    if (res.status === 200) {
      const b = safeJson(res);
      const ok = !!(b && b.ok === true);
      business_failure.add(!ok);
      check(res, {
        'work status 200': (r) => r.status === 200,
        'work ok true': () => ok,
      });
      if (b && b.csrf) csrf = b.csrf;
      return;
    }

    if (res.status === 429) {
      business_failure.add(false); // scheduled throttling is expected
      if (retries429 < 4) {
        retries429++;
        const ra = parseFloat(res.headers['Retry-After'] || res.headers['retry-after'] || '1');
        sleep(isNaN(ra) || ra <= 0 ? 1 : ra);
        continue;
      }
      check(res, { 'work not throttled beyond retries': () => false });
      return;
    }

    if (res.status === 401) {
      const code = errorCode(res);
      if (code === 'expired' && !renewed) {
        business_failure.add(false);
        renewed = true;
        if (!renew()) {
          if (relogged || !login()) return;
          relogged = true;
        }
        continue;
      }
      if (code === 'session' && !relogged) {
        business_failure.add(false);
        relogged = true;
        renewed = true;
        if (!renew()) {
          if (!login()) return;
        }
        continue;
      }
      // denied or recovery exhausted: unexpected
      business_failure.add(true);
      check(res, { 'work authorized': () => false });
      return;
    }

    // 500 and anything else: unexpected
    business_failure.add(true);
    check(res, { 'work status 200': (r) => r.status === 200 });
    return;
  }
}

export default function () {
  if (!loggedIn) {
    if (!login()) {
      check(null, { 'login succeeded': () => false });
      return;
    }
  }
  doWork();
}
