```python
import os
import re
import time
from html.parser import HTMLParser

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

TARGET_RATE = 5.0
PERIOD = 1.0 / TARGET_RATE
USERS = 16
RUN_SECONDS = 50

_state = {"next": 0.0, "idx": 0}


def _claim_slot():
    """Hand out evenly spaced global start slots (one every 200 ms)."""
    now = time.time()
    nxt = _state["next"]
    # allow at most one slot of catch-up; otherwise restart from now
    if nxt < now - PERIOD:
        nxt = now
    _state["next"] = nxt + PERIOD
    return nxt


class _CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        if tag != "input":
            return
        a = {}
        for k, v in attrs:
            a[(k or "").lower()] = v
        if a.get("name") != "csrf":
            return
        if "disabled" in a:
            return
        val = a.get("value")
        if val:
            self.candidates.append((a.get("type", ""), val))

    handle_startendtag = handle_starttag


def _extract_csrf(html):
    p = _CsrfParser()
    try:
        p.feed(html)
    except Exception:
        pass
    for typ, val in p.candidates:
        if (typ or "").lower() == "hidden":
            return val
    if p.candidates:
        return p.candidates[0][1]
    m = re.search(r'name\s*=\s*["\']?csrf["\']?[^>]*?value\s*=\s*["\']([^"\']+)["\']', html)
    return m.group(1) if m else None


def _json(r):
    try:
        d = r.json()
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


class WorkUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def wait_time(self):
        slot = _claim_slot()
        return max(0.0, slot - time.time())

    def on_start(self):
        _state["idx"] += 1
        self.username = "bench-%d" % (((_state["idx"] - 1) % 16) + 1)
        self.csrf = None
        self.primed = False
        for _ in range(3):
            if self.login():
                break

    # ---------- auth ----------
    def login(self):
        form_csrf = None
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True) as r:
            if r.status_code == 200:
                form_csrf = _extract_csrf(r.text)
                if form_csrf:
                    r.success()
                else:
                    r.failure("csrf input not found")
            else:
                r.failure("login-form status %s" % r.status_code)
        if not form_csrf:
            return False

        location = None
        new_csrf = None
        ok = False
        with self.client.post(
                "/v2/login", name="/v2/login",
                json={"username": self.username, "password": "bench", "csrf": form_csrf},
                allow_redirects=False, catch_response=True) as r:
            if r.status_code in (301, 302, 303, 307, 308):
                location = r.headers.get("Location")
                new_csrf = _json(r).get("csrf")
                if location:
                    r.success()
                    ok = True
                else:
                    r.failure("redirect without Location")
            elif r.status_code == 200:
                new_csrf = _json(r).get("csrf")
                if new_csrf:
                    r.success()
                    ok = True
                else:
                    r.failure("login response without csrf")
            else:
                r.failure("login status %s" % r.status_code)
        if not ok:
            return False

        if location:
            with self.client.get(location, name="/v2/login-redirect",
                                 allow_redirects=False, catch_response=True) as r:
                if r.status_code < 400:
                    c = _json(r).get("csrf")
                    if c:
                        new_csrf = c
                    r.success()
                else:
                    r.failure("login redirect status %s" % r.status_code)
                    return False

        if not new_csrf:
            return False
        self.csrf = new_csrf
        return True

    def renew(self):
        with self.client.post("/v2/session/renew", name="/v2/session/renew",
                              json={}, headers={"X-CSRF-Token": self.csrf or ""},
                              catch_response=True) as r:
            if r.status_code < 400:
                c = _json(r).get("csrf")
                if c:
                    self.csrf = c
                r.success()
                return True
            r.failure("renew status %s" % r.status_code)
            return False

    # ---------- work ----------
    @task
    def work(self):
        if not self.primed:
            # first iteration: no request, let wait_time schedule the first slot
            self.primed = True
            return
        if not self.csrf:
            if not self.login():
                return

        recovered = False
        retries_429 = 0
        while True:
            action = None
            sleep_for = 1.0
            with self.client.post("/v2/work", name="/v2/work", json={},
                                  headers={"X-CSRF-Token": self.csrf or ""},
                                  catch_response=True) as r:
                sc = r.status_code
                data = _json(r)
                if sc == 200:
                    if data.get("ok") is True:
                        c = data.get("csrf")
                        if c:
                            self.csrf = c
                        r.success()
                    else:
                        r.failure("work ok is not true")
                    return
                elif sc == 429:
                    ra = r.headers.get("Retry-After")
                    if ra is not None and retries_429 < 4:
                        try:
                            sleep_for = max(1.0, float(ra))
                        except Exception:
                            sleep_for = 1.0
                        r.success()
                        action = "retry429"
                    else:
                        r.failure("429 without Retry-After or retries exhausted")
                        return
                elif sc == 401:
                    err = data.get("error")
                    if err == "expired" and not recovered:
                        r.success()
                        action = "renew"
                    elif err == "session" and not recovered:
                        r.success()
                        action = "relogin"
                    elif err == "denied":
                        r.failure("denied")
                        return
                    else:
                        r.failure("401 %s" % err)
                        return
                else:
                    r.failure("unexpected status %s" % sc)
                    return

            if action == "retry429":
                retries_429 += 1
                time.sleep(sleep_for)
                continue
            if action == "renew":
                recovered = True
                if not self.renew():
                    if not self.login():
                        return
                continue
            if action == "relogin":
                recovered = True
                if not self.renew():
                    if not self.login():
                        return
                continue
            return


class ConstantShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() > RUN_SECONDS:
            return None
        return (USERS, USERS)
