```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const RATE = 8;

const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: RATE,
      timeUnit: '1s',
      duration: '40s',          // T0 (<~1s) + 5s warmup + 30s scored + ~5s drain
      preAllocatedVUs: 32,
      maxVUs: 32,
      gracefulStop: '5s',
    },
  },
  thresholds: {
    business_failure: ['rate<0.01'],
  },
};

http.setResponseCallback(
  http.expectedStatuses({ min: 200, max: 399 }, 401, 429)
);

// Per-VU state. The VU keeps its own cookie jar.
const state = { loggedIn: false, csrf: null };

function jsonOf(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function absUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  return BASE + (loc.charAt(0) === '/' ? '' : '/') + loc;
}

function extractCsrf(body) {
  if (!body) return null;
  const html = String(body).replace(/<!--[\s\S]*?-->/g, '');
  try {
    const doc = parseHTML(html);
    const els = doc.find('input[name=csrf]');
    let found = null;
    els.each(function (i, el) {
      if (found) return;
      const v = el.attr('value');
      const dis = el.attr('disabled');
      if (v && (dis === undefined || dis === null)) found = v;
    });
    if (found) return found;
  } catch (e) {
    // fall through to the regex fallback
  }
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const t of tags) {
    if (/\bname\s*=\s*["']?csrf["']?(?=[\s>\/]|$)/i.test(t)) {
      const m = t.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      if (m) return m[1] || m[2] || m[3];
    }
  }
  return null;
}

function authHeaders() {
  return {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf || '',
  };
}

function login() {
  const n = ((__VU - 1) % 16) + 1;
  const username = 'bench-' + n;
  for (let attempt = 0; attempt < 2; attempt++) {
    const form = http.get(BASE + '/v2/login-form', {
      redirects: 0,
      tags: { name: 'login-form' },
    });
    const formCsrf = extractCsrf(form.body);
    if (!formCsrf) continue;
    const res = http.post(
      BASE + '/v2/login',
      JSON.stringify({ username: username, password: 'bench', csrf: formCsrf }),
      {
        headers: { 'Content-Type': 'application/json' },
        redirects: 0,
        tags: { name: 'login' },
      }
    );
    let body = null;
    if (res.status === 302) {
      const loc = absUrl(res.headers['Location'] || res.headers['location']);
      if (loc) {
        const r2 = http.get(loc, { redirects: 0, tags: { name: 'login-redirect' } });
        body = jsonOf(r2);
      }
    } else if (res.status === 200) {
      body = jsonOf(res);
    } else {
      continue;
    }
    state.csrf = (body && body.csrf) || formCsrf;
    state.loggedIn = true;
    return true;
  }
  state.loggedIn = false;
  return false;
}

function renew() {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: authHeaders(),
    redirects: 0,
    tags: { name: 'renew' },
  });
  if (res.status === 200) {
    const b = jsonOf(res);
    if (b && b.csrf) state.csrf = b.csrf;
    return true;
  }
  return false;
}

function retryAfterSeconds(res) {
  const h = res.headers['Retry-After'] || res.headers['retry-after'];
  const v = parseFloat(h);
  return isFinite(v) && v > 0 ? v : 1;
}

function doWork() {
  let retries429 = 0;
  let expiredRetried = false;
  let sessionRetried = false;

  for (let guard = 0; guard < 8; guard++) {
    const res = http.post(BASE + '/v2/work', '{}', {
      headers: authHeaders(),
      redirects: 0,
      tags: { name: 'work' },
    });
    const body = jsonOf(res);

    if (res.status === 200) {
      const ok = !!(body && body.ok === true);
      businessFailure.add(!ok);
      check(res, { 'work ok': () => ok });
      if (body && body.csrf) state.csrf = body.csrf;
      return;
    }

    if (res.status === 429) {
      businessFailure.add(false); // scheduled throttle, expected
      if (retries429 < 4) {
        retries429++;
        sleep(Math.max(1, retryAfterSeconds(res)));
        continue;
      }
      check(res, { 'work not throttled after retries': () => false });
      return;
    }

    if (res.status === 401) {
      const err = body && body.error;
      if (err === 'expired' && !expiredRetried) {
        businessFailure.add(false); // expected expiry
        expiredRetried = true;
        if (!renew()) {
          if (!login()) return;
        }
        continue;
      }
      if (err === 'session' && !sessionRetried) {
        businessFailure.add(false); // expected revocation
        sessionRetried = true;
        if (!renew()) {
          if (!login()) return;
        }
        continue;
      }
      businessFailure.add(true);
      check(res, { 'work authorized': () => false });
      return;
    }

    businessFailure.add(true);
    check(res, { 'work expected status': () => false });
    return;
  }
}

export default function () {
  if (!state.loggedIn) {
    if (!login()) {
      check(null, { 'login succeeded': () => false });
      return;
    }
  }
  doWork();
}
