import os
import re
import time
import html

from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser

TARGET_RATE = 8.0
INTERVAL = 1.0 / TARGET_RATE
N_USERS = 16
SCORE_END_OFFSET = 36.0     # users stop sending after T0 + 36s (scored window ends at T0 + 35s)
SHAPE_END_OFFSET = 36.5
HARD_STOP = 52.0

# Shared pacing state (all virtual users run as greenlets in one process)
S = {"next": 0.0, "t0": None, "ready": 0, "acct": 0, "launch": None}

COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
ATTR_RE = re.compile(r"""([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))""", re.S)


def extract_csrf(text):
    text = COMMENT_RE.sub("", text or "")
    best = None
    for tag in INPUT_RE.findall(text):
        attrs = {}
        for m in ATTR_RE.finditer(tag):
            val = m.group(2) if m.group(2) is not None else (
                m.group(3) if m.group(3) is not None else m.group(4))
            attrs[m.group(1).lower()] = html.unescape(val or "")
        if attrs.get("name") != "csrf":
            continue
        if "disabled" in tag.lower().split() or "value" not in attrs:
            continue
        if not attrs["value"]:
            continue
        if attrs.get("type", "").lower() == "hidden":
            return attrs["value"]
        if best is None:
            best = attrs["value"]
    return best


def safe_json(r):
    try:
        j = r.json()
        return j if isinstance(j, dict) else {}
    except Exception:
        return {}


def pace():
    """Global, evenly spaced slot allocation; no catch-up bursts after stalls."""
    now = time.time()
    slot = max(now, S["next"])
    S["next"] = slot + INTERVAL
    d = slot - now
    if d > 0:
        time.sleep(d)


def finished():
    t0 = S["t0"]
    return t0 is not None and time.time() >= t0 + SCORE_END_OFFSET


class WorkUser(HttpUser):
    wait_time = constant(0)
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def on_start(self):
        if S["launch"] is None:
            S["launch"] = time.time()
        n = S["acct"]
        S["acct"] += 1
        self.username = "bench-%d" % (n % 16 + 1)
        self.csrf = None

    def login(self):
        for _ in range(3):
            token = None
            with self.client.get("/v2/login-form", catch_response=True) as r:
                token = extract_csrf(r.text) if r.status_code == 200 else None
                if not token:
                    r.failure("login csrf not found")
                    continue
                r.success()
            loc = None
            ok = False
            with self.client.post(
                "/v2/login",
                json={"username": self.username, "password": "bench", "csrf": token},
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code in (301, 302, 303, 307, 308):
                    loc = r.headers.get("Location")
                    j = safe_json(r)
                    self.csrf = j.get("csrf") or self.csrf
                    r.success()
                    ok = True
                elif r.status_code == 200:
                    j = safe_json(r)
                    self.csrf = j.get("csrf") or self.csrf
                    if self.csrf:
                        r.success()
                        ok = True
                    else:
                        r.failure("no csrf in login response")
                else:
                    r.failure("login status %s" % r.status_code)
            if not ok:
                continue
            if loc:
                with self.client.get(loc, catch_response=True, name="/v2/login-redirect") as r2:
                    if r2.status_code < 400:
                        j = safe_json(r2)
                        self.csrf = j.get("csrf") or self.csrf
                        r2.success()
                    else:
                        r2.failure("login redirect status %s" % r2.status_code)
                        continue
            if self.csrf:
                return True
        return False

    def renew(self):
        with self.client.post(
            "/v2/session/renew", json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                j = safe_json(r)
                self.csrf = j.get("csrf") or self.csrf
                r.success()
                return True
            if r.status_code < 500:
                r.success()  # renewal may legitimately fail on revoked sessions
                return False
            r.failure("renew status %s" % r.status_code)
            return False

    def work(self):
        renewed = False
        relogged = False
        retries429 = 0
        while True:
            pace()
            action = None
            wait = 0.0
            started = time.time()
            with self.client.post(
                "/v2/work", json={},
                headers={"X-CSRF-Token": self.csrf or ""},
                catch_response=True, name="/v2/work",
            ) as r:
                sc = r.status_code
                if sc == 200:
                    j = safe_json(r)
                    if j.get("ok") is True:
                        r.success()
                        if j.get("csrf"):
                            self.csrf = j["csrf"]
                        if S["t0"] is None:
                            S["t0"] = started
                        return True
                    r.failure("work ok not true")
                    return False
                elif sc == 429:
                    r.success()  # scheduled throttle, expected
                    retries429 += 1
                    if retries429 > 4:
                        return False
                    try:
                        wait = float(r.headers.get("Retry-After", "1"))
                    except Exception:
                        wait = 1.0
                    wait = max(wait, 1.0)
                    action = "wait"
                elif sc == 401:
                    err = safe_json(r).get("error")
                    if isinstance(err, dict):
                        err = err.get("code") or err.get("error")
                    err = str(err or "")
                    if err == "expired" and not renewed:
                        r.success()
                        action = "renew"
                    elif err == "session" and not relogged:
                        r.success()
                        action = "relogin"
                    else:
                        r.failure("401 %s" % err)
                        return False
                else:
                    r.failure("work status %s" % sc)
                    return False
            if action == "wait":
                time.sleep(wait)
            elif action == "renew":
                renewed = True
                if not self.renew():
                    relogged = True
                    if not self.login():
                        return False
            elif action == "relogin":
                relogged = True
                if not self.renew():
                    if not self.login():
                        return False
            if finished():
                return False

    @task
    def journey(self):
        logged = self.login()
        S["ready"] += 1
        if not logged:
            raise StopUser()
        # Let enough users finish login so pacing is smooth from the first request
        while (S["ready"] < min(N_USERS, 8)
               and time.time() - (S["launch"] or time.time()) < 4.0):
            time.sleep(0.05)
        while not finished():
            self.work()
        raise StopUser()


class PacedShape(LoadTestShape):
    def tick(self):
        t = self.get_run_time()
        t0 = S["t0"]
        if t0 is not None and time.time() >= t0 + SHAPE_END_OFFSET:
            return None
        if t > HARD_STOP:
            return None
        return (N_USERS, N_USERS)
